  @Test func notesFoldersCreateDryRunAndExecutionVerifiesFolder() throws {
    let implementation = TestNotesImplementation()
    let command = NotesCommand(implementation: implementation)
    let dryRunOptions = try CLIOptionsFixture.parse([
      "folders", "create", "--name", "Planning", "--parent", "Work", "--dry-run", "--json",
    ])

    let dryRun = try #require(try command.run(options: dryRunOptions))
    let dryRunObject = try jsonObject(dryRun.stdout ?? "")
    let dryRunData = dryRunObject["data"] as? [String: Any]
    let summary = dryRunData?["normalizedArguments"] as? [String: Any]

    #expect(dryRunData?["operation"] as? String == "notes.folders.create")
    #expect(summary?["name"] as? String == "Planning")
    #expect(summary?["account"] as? String == "iCloud")
    #expect(summary?["parent"] as? String == "Work")
    #expect(summary?["parent_id"] as? String == "folder-work")
    #expect(implementation.createdFolderDrafts.isEmpty)

    let executeOptions = try CLIOptionsFixture.parse([
      "folders", "create", "--name", "Planning", "--parent", "Work", "--json",
    ])
    let executed = try #require(try command.run(options: executeOptions))
    let executedObject = try jsonObject(executed.stdout ?? "")
    let executedData = executedObject["data"] as? [String: Any]
    let folder = executedData?["folder"] as? [String: Any]
    let verification = executedData?["verification"] as? [String: Any]
    let checks = verification?["checks"] as? [[String: Any]]

    #expect(executedData?["operation"] as? String == "notes.folders.create")
    #expect(executedData?["changed"] as? Bool == true)
    #expect(folder?["id"] as? String == "folder-created")
    #expect(folder?["name"] as? String == "Planning")
    #expect(folder?["accountName"] as? String == "iCloud")
    #expect(folder?["parentID"] as? String == "folder-work")
    #expect(verification?["verified"] as? Bool == true)
    #expect(checks?.contains { $0["name"] as? String == "name" } == true)
    #expect(checks?.contains { $0["name"] as? String == "account" } == true)
    #expect(checks?.contains { $0["name"] as? String == "parent" } == true)
    #expect(implementation.createdFolderDrafts.map(\.parentName) == ["Work"])
  }

