  @Test func notesSmartFoldersBuiltInCriteriaCreateSupportsAnyRuleScope() throws {
    let implementation = TestNotesImplementation()
    let command = NotesCommand(implementation: implementation)

    let dryRun = try #require(try command.run(options: try CLIOptionsFixture.parse([
      "smart-folders", "create-criteria", "--name", "Pinned Or Unshared", "--account", "iCloud",
      "--criteria", "pinned,not-shared", "--match", "any", "--dry-run", "--json",
    ])))
    let dryRunObject = try jsonObject(dryRun.stdout ?? "")
    let dryRunData = try #require(dryRunObject["data"] as? [String: Any])
    let dryRunSummary = try #require(dryRunData["normalizedArguments"] as? [String: Any])

    #expect(dryRunObject["ok"] as? Bool == true)
