  @Test func notesSessionUnlockedProtectedNoteArtifactExportsUsePrivateExportersWithoutTitleLeakage() throws {
    let implementation = TestNotesImplementation()
    implementation.addProtectedExportFixturesForTesting()
    let command = NotesCommand(implementation: implementation)
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(
      "apple-cli-notes-protected-export-\(UUID().uuidString)",
      isDirectory: true
    )
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }

    let cases: [(format: String, outputName: String, boundaryCheck: String)] = [
      ("pdf", "Protected.pdf", "pdf_header"),
      ("markdown", "Protected.md", "markdown_utf8"),
      ("html", "Protected.html", "html_marker"),
      ("rtf", "Protected.rtf", "rtf_header"),
      ("rtfd", "Protected.rtfd", "rtf_member"),
    ]

    for item in cases {
      let output = root.appendingPathComponent(
        item.outputName,
        isDirectory: item.format == "rtfd"
      )
