    let dryRun = try #require(try command.run(options: dryRunOptions))
    let dryRunObject = try jsonObject(dryRun.stdout ?? "")
    let data = dryRunObject["data"] as? [String: Any]

    #expect(data?["operation"] as? String == "mail.archive")
    #expect(implementation.archivedMessages.isEmpty)

    let executeOptions = try CLIOptionsFixture.parse([
      "mail",
      "archive",
      "--mailbox",
      "Inbox",
      "--id",
      "message-1",
      "--archive-mailbox",
      "Archive",
      "--allow-external-dispatch",
      "--json",
    ])
    let executed = try #require(try command.run(options: executeOptions))
    let executedObject = try jsonObject(executed.stdout ?? "")
    let executedData = executedObject["data"] as? [String: Any]
    let message = executedData?["message"] as? [String: Any]

    #expect(message?["destinationMailboxName"] as? String == "Archive")
    #expect(implementation.archivedMessages.map(\.1) == ["Archive"])
  }

  @Test func mailDeleteDryRunAndExecutionDeletesMessage() throws {
    let implementation = TestMailBackend()
    let command = MailCommand(backend: implementation)
    let dryRunOptions = try CLIOptionsFixture.parse([
      "mail",
      "delete",
      "--mailbox",
      "Inbox",
      "--id",
      "message-1",
      "--dry-run",
      "--json",
    ])

    let dryRun = try #require(try command.run(options: dryRunOptions))
    let dryRunObject = try jsonObject(dryRun.stdout ?? "")
    let data = dryRunObject["data"] as? [String: Any]
    let summary = data?["normalizedArguments"] as? [String: Any]

    #expect(data?["operation"] as? String == "mail.delete")
    #expect(summary?["source_id"] as? String == "message-1")
    #expect(summary?["destination_mailbox"] == nil)
    #expect(implementation.deletedMessages.isEmpty)

    let executeOptions = try CLIOptionsFixture.parse([
      "mail",
      "delete",
      "--mailbox",
      "Inbox",
      "--id",
      "message-1",
      "--allow-external-dispatch",
      "--json",
    ])
    let executed = try #require(try command.run(options: executeOptions))
    let executedObject = try jsonObject(executed.stdout ?? "")
    let executedData = executedObject["data"] as? [String: Any]
    let message = executedData?["message"] as? [String: Any]

    #expect(message?["sourceMailboxName"] as? String == "Inbox")
    #expect(message?["destinationMailboxName"] == nil)
    #expect(implementation.deletedMessages.map(\.id) == ["message-1"])
  }
}

private struct TestRecognizedTextGenerator: NotesAttachmentRecognizedTextGenerating {
  var text: String
  var sourceKind: String
  var pageCount: Int?
  var observationCount: Int

  func generateRecognizedText(
    from input: NotesAttachmentRecognizedTextGenerationInput
  ) throws -> NotesAttachmentRecognizedTextGeneration {
    guard !input.data.isEmpty else {
      throw CLIError(code: .unsupportedOperation, message: "No test OCR source bytes.")
    }
    return NotesAttachmentRecognizedTextGeneration(
      text: text,
      sourceKind: sourceKind,
      pageCount: pageCount,
      observationCount: observationCount
    )
  }
}

