  func makeNoteEditableForTesting(_ id: String) {
    guard var state = noteStates[id] else {
      return
    }
    state.isPasswordProtected = false
    state.isPasswordProtectedAndLocked = false
    state.isEditable = true
    state.isSharedReadOnly = false
    noteStates[id] = state
  }

