  func addSecondBodyTableForTesting(noteID: String = "note-1") {
    guard var structure = bodyStructures[noteID] else {
      return
    }
    let nextOrdinal = (bodyTables[noteID] ?? []).count + 1
    bodyTables[noteID, default: []].append(
      NotesBodyTableRecord(
        ordinal: nextOrdinal,
        idSHA256: testSHA256Hex("table-inline-attachment-\(nextOrdinal)"),
        attachmentIDSHA256: testSHA256Hex("table-attachment-\(nextOrdinal)"),
        contentIdentifierSHA256: testSHA256Hex("table-content-\(nextOrdinal)"),
        typeUTISHA256: testSHA256Hex("com.apple.notes.table"),
        rowCount: 2,
        columnCount: 2,
        isDeletable: true
      ))
    bodyTableCells[noteID, default: [:]][bodyTableCellKey(tableOrdinal: nextOrdinal, row: 1, column: 1)] = "Milestone"
    bodyTableCells[noteID, default: [:]][bodyTableCellKey(tableOrdinal: nextOrdinal, row: 1, column: 2)] = "Owner"
    bodyTableCells[noteID, default: [:]][bodyTableCellKey(tableOrdinal: nextOrdinal, row: 2, column: 1)] = "Verifier"
    bodyTableCells[noteID, default: [:]][bodyTableCellKey(tableOrdinal: nextOrdinal, row: 2, column: 2)] = "Rin"
    structure.tableCount += 1
    structure.inlineAttachmentCount += 1
    if let index = structure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      structure.attachmentKindCounts[index].count += 1
    } else {
      structure.attachmentKindCounts.append(NotesBodyAttachmentKindCount(kind: "table", count: 1))
    }
    bodyStructures[noteID] = structure
    if var note = notes[noteID] {
      note.body = [note.body ?? "", "[table]"].filter { !$0.isEmpty }.joined(separator: "\n")
      notes[noteID] = note
    }
  }

  func seedTextToTableParagraphForTesting(noteID: String = "note-2", text: String = "Name\tOwner") {
    guard var note = notes[noteID], var structure = bodyStructures[noteID] else {
      return
    }
    note.body = text
    notes[noteID] = note
    let anchor = NotesBodyParagraphAnchorRecord(
      ordinal: 1,
      idSHA256: "archive-paragraph-anchor-hash",
      titleByteCount: text.utf8.count,
      titleSHA256: testSHA256Hex(text),
      style: "body",
      alignment: "left"
    )
    structure.plainTextByteCount = text.utf8.count
    structure.plainTextSHA256 = testSHA256Hex(text)
    structure.richTextLength = text.utf8.count
    structure.paragraphCount = 1
    structure.paragraphStyleRunCount = 1
    structure.headingCount = 0
    structure.listItemCount = 0
    structure.checklistItemCount = 0
    structure.checklistDoneCount = 0
    structure.checklistOpenCount = 0
    structure.blockQuoteCount = 0
    structure.tableCount = 0
    structure.inlineAttachmentCount = 0
    structure.styleCounts = [NotesBodyStyleCount(style: "body", count: 1)]
    structure.attachmentKindCounts = []
    structure.paragraphAnchors = [anchor]
    bodyStructures[noteID] = structure
    paragraphAnchors[noteID] = [
      NotesParagraphAnchorResolution(
        anchor: anchor,
        paragraphID: "raw-archive-paragraph-id",
        title: text
      )
    ]
    bodyTables[noteID] = []
    bodyTableCells[noteID] = [:]
  }

  func seedEditableMarkupAttachment(noteID: String = "note-2") -> NotesAttachmentRecord {
    let record = NotesAttachmentRecord(
      id: "attachment-markup-seeded",
      title: "Markup.pdf",
      typeUTI: "com.adobe.pdf",
      contentIdentifier: "attachment-markup-content-seeded",
      attachmentType: 9,
      fileSizeBytes: 2048,
      mediaFilename: "Markup.pdf",
      isInline: false,
      isDeletedOrInTrash: false
    )
    attachments[noteID, default: []].append(record)
    let data = Data("%PDF-1.7 test markup edit pdf".utf8)
    attachmentData[noteID, default: [:]][record.id] = data
    if let contentIdentifier = record.contentIdentifier {
      attachmentData[noteID, default: [:]][contentIdentifier] = data
    }
    return record
  }

  @discardableResult
  func seedInlineImageDescriptionAttachment(
    noteID: String = "note-1",
    id: String = "attachment-inline-image-description",
    title: String = "Inline image",
    typeUTI: String = "public.image",
    description: String? = "Diagram showing the launch flow."
  ) -> NotesAttachmentRecord {
    let record = attachmentWithImageDescriptionEvidence(
      NotesAttachmentRecord(
        id: id,
        title: title,
        typeUTI: typeUTI,
        contentIdentifier: "\(id)-token",
        attachmentType: 9,
        fileSizeBytes: 4096,
        mediaFilename: nil,
        isInline: true,
        isDeletedOrInTrash: false
      ),
      description: description
    )
    attachments[noteID, default: []].append(record)
    if let description = normalizedImageDescription(description) {
      attachmentImageDescriptions[noteID, default: [:]][record.id] = description
      if let contentIdentifier = record.contentIdentifier {
        attachmentImageDescriptions[noteID, default: [:]][contentIdentifier] = description
      }
    }
    return record
  }

