  @discardableResult
  func seedSearchableTextAttachment(
    noteID: String = "note-1",
    id: String,
    title: String,
    typeUTI: String,
    mediaFilename: String,
    text: String,
    kind: String = "model_searchable_text",
    sourceKind: String = "ICAttachment.attachmentModel.searchableTextContent"
  ) -> NotesAttachmentRecord {
    let record = NotesAttachmentRecord(
      id: id,
      title: title,
      typeUTI: typeUTI,
      contentIdentifier: "\(id)-content",
      attachmentType: 9,
      fileSizeBytes: Int64(text.utf8.count),
      mediaFilename: mediaFilename,
      isInline: false,
      isDeletedOrInTrash: false
    )
    attachments[noteID, default: []].append(record)
    seedAttachmentSearchableText(
      noteID: noteID,
      attachment: record,
      text: text,
      kind: kind,
      sourceKind: sourceKind
    )
    return record
  }

  func seedAttachmentSearchableText(
    noteID: String = "note-1",
    attachmentID: String,
    text: String,
    kind: String = "model_searchable_text",
    sourceKind: String = "ICAttachment.attachmentModel.searchableTextContent"
  ) {
    guard let attachment = (attachments[noteID] ?? []).first(where: { record in
      record.id == attachmentID || record.contentIdentifier == attachmentID
        || record.mediaFilename == attachmentID || record.title == attachmentID
    }) else {
      return
    }
    seedAttachmentSearchableText(
      noteID: noteID,
      attachment: attachment,
      text: text,
      kind: kind,
      sourceKind: sourceKind
    )
  }

  private func seedAttachmentSearchableText(
    noteID: String,
    attachment: NotesAttachmentRecord,
    text: String,
    kind: String,
    sourceKind: String
  ) {
    let source = NotesAttachmentSearchableTextSource(
      noteID: noteID,
      attachment: attachment,
      content: [
        NotesAttachmentSearchableTextContentSource(
          kind: kind,
          text: text,
          sourceKind: sourceKind
        )
      ]
    )
    attachmentSearchableTextSources[noteID, default: [:]][attachment.id] = source
    if let contentIdentifier = attachment.contentIdentifier {
      attachmentSearchableTextSources[noteID, default: [:]][contentIdentifier] = source
    }
  }

