  func readFolderMoveImpact(_ draft: NotesFolderMoveDraft) throws -> NotesFolderMoveImpactRecord {
    folderMoveImpactDrafts.append(draft)
    guard let source = folders.first(where: { $0.id == draft.folderID }) else {
      throw CLIError(code: .notFound, message: "Folder was not found.", details: ["folder": draft.folderID])
    }
    let crossAccount = draft.sourceAccountName.localizedCaseInsensitiveCompare(draft.accountName) != .orderedSame
    let sharedReview = source.isSharedViaICloud == true
    let attachmentRisk = source.visibleNoteCount.map { $0 > 0 } ?? false
    let fidelityReview = crossAccount || attachmentRisk
    let sourceIDs = ([draft.folderID] + draft.descendantIDs).sorted().joined(separator: "\n")
    return NotesFolderMoveImpactRecord(
      sourceFolderIDSHA256: testSHA256Hex(draft.folderID),
      sourceAccountSHA256: testSHA256Hex(draft.sourceAccountName),
      destinationKind: draft.parentID == nil ? "account" : "folder",
      destinationIDSHA256: testSHA256Hex(draft.parentID ?? draft.accountID ?? draft.accountName),
      destinationAccountSHA256: testSHA256Hex(draft.accountName),
      crossAccountMove: crossAccount,
      decisionType: 2,
      additionalStep: sharedReview || fidelityReview ? 1 : 0,
      decisionTypeStringSHA256: testSHA256Hex("ICMoveDecision.test"),
      shouldMove: true,
      shouldProceed: true,
      shouldContinueDecisionMaking: false,
      modernSourceObjectCount: 1 + draft.descendantIDs.count,
      htmlSourceObjectCount: 0,
      modernFolderCount: 1 + draft.descendantIDs.count,
      accountCountOfModernSourceObjects: crossAccount ? 2 : 1,
      accountCountOfHTMLSourceObjects: 0,
      ownedSharedRootObjectCount: sharedReview ? 1 : 0,
      joinedSharedRootObjectCount: 0,
      readWriteSharedSubObjectCount: sharedReview ? 1 : 0,
      readOnlySharedSubObjectCount: 0,
      sharedObjectCount: sharedReview ? 1 : 0,
      sharedObjectNotFromDestinationFolderCount: sharedReview ? 1 : 0,
      hasSharedObjectsNotFromDestinationAccount: sharedReview && crossAccount,
      lockedObjectCount: 0,
      hasLockedObjects: false,
      hasLockedNotesNotFromDestinationAccount: false,
      unsupportedObjectCount: 0,
      privateModernNoteWithAttachmentsCount: attachmentRisk ? 1 : 0,
      systemPaperNoteCount: 0,
      mathNoteCount: 0,
      callNoteCount: 0,
      guiltyObjectCount: sharedReview ? 1 : 0,
      sourceObjectSetSHA256: testSHA256Hex(sourceIDs),
      guiltyObjectSetSHA256: sharedReview ? testSHA256Hex(draft.folderID) : nil,
      requiresSharedPermissionReview: sharedReview,
      requiresCrossAccountFidelityReview: fidelityReview,
      privacyBoundary: "hashes_counts_booleans_without_names_participants_note_bodies_or_object_uris",
      sourceKind: "ICMoveDecision.initWithSourceObjects:destination:",
      backendCalls: [
        "ICMoveDecision.objectsForMakingDecisionForNonSharedFolder",
        "ICMoveDecision.initWithSourceObjects:destination:",
      ]
    )
  }

