  func listTags(account: String?, limit: Int) throws -> [NotesTagRecord] {
    tagListQueries.append((account: account, limit: limit))
    let baseTags = [
      NotesTagRecord(
        id: "tag-urgent",
        displayText: "Urgent",
        standardizedContent: "urgent",
        accountName: "iCloud",
        visibleUseCount: 2
      ),
      NotesTagRecord(
        id: "tag-home",
        displayText: "Home",
        standardizedContent: "home",
        accountName: "Local",
        visibleUseCount: 1
      ),
    ]
    let noteTags = notes.values.flatMap(\.tags)
    let uniqueTags = Dictionary(
      grouping: baseTags + noteTags,
      by: { $0.standardizedContent ?? $0.displayText.localizedLowercase }
    )
    .values
    .compactMap { $0.first }
    .sorted { $0.displayText.localizedStandardCompare($1.displayText) == .orderedAscending }
    return uniqueTags
    .filter { !deletedTagContents.contains($0.standardizedContent ?? $0.displayText.localizedLowercase) }
    .filter { account == nil || $0.accountName.localizedCaseInsensitiveCompare(account ?? "") == .orderedSame }
    .prefix(limit)
    .map { $0 }
  }

  func readNotes(tag: String, limit: Int) throws -> [NotesNoteDetail] {
    tagReadQueries.append((tag: tag, limit: limit))
    return notes.values
      .sorted { $0.id < $1.id }
      .filter { note in
        note.tags.contains { testTagMatches($0, tag) }
      }
      .prefix(limit)
      .map { $0 }
  }

