  func exportAttachment(noteID id: String, attachmentID: String) throws -> NotesAttachmentExportSource {
    guard notes[id] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let matches = (attachments[id] ?? []).filter { attachment in
      attachment.id == attachmentID
        || attachment.contentIdentifier == attachmentID
        || attachment.mediaFilename == attachmentID
        || attachment.title == attachmentID
    }
    guard let attachment = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Attachment selector matched multiple attachments on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    let data = attachmentData[id]?[attachment.id]
      ?? attachment.contentIdentifier.flatMap { attachmentData[id]?[$0] }
    guard let data else {
      throw CLIError(
        code: .unsupportedOperation,
        message: "Attachment data could not be read through NotesShared media APIs.",
        details: ["attachment_sha256": "test"]
      )
    }
    return NotesAttachmentExportSource(noteID: id, attachment: attachment, data: data)
  }

  func exportAttachmentPDF(noteID id: String, attachmentID: String) throws -> NotesAttachmentPDFExportSource {
    let source = try exportAttachment(noteID: id, attachmentID: attachmentID)
    guard source.data.count >= 4, source.data.prefix(4) == Data("%PDF".utf8) else {
      throw CLIError(
        code: .unsupportedOperation,
        message: "Attachment does not expose PDF data through Notes private APIs.",
        details: ["attachment_sha256": "test"]
      )
    }
    let sourceKind = attachmentPDFSourceKinds[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentPDFSourceKinds[id]?[$0] }
      ?? "media_pdf"
    return NotesAttachmentPDFExportSource(
      noteID: source.noteID,
      attachment: source.attachment,
      data: source.data,
      sourceKind: sourceKind
    )
  }

  func inspectAttachmentScanPDF(noteID id: String, attachmentID: String) throws
    -> NotesAttachmentScanPDFInspectionSource
  {
    let source = try exportAttachmentPDF(noteID: id, attachmentID: attachmentID)
    scanPDFInspectionLookups.append("\(id):\(source.attachment.id)")
    let lowercasedHints = [
      source.attachment.id,
      source.attachment.title ?? "",
      source.attachment.mediaFilename ?? "",
      source.attachment.typeUTI ?? "",
    ].joined(separator: " ").lowercased()
    let isScan = lowercasedHints.contains("scan")
    let cropHash = isScan
      ? attachmentScanCropDigests[id]?[source.attachment.id]
        ?? source.attachment.contentIdentifier.flatMap { attachmentScanCropDigests[id]?[$0] }
        ?? testSHA256Hex("test-crop-metadata:\(source.attachment.id)")
      : nil
    let pageOrder = attachmentScanPageOrders[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentScanPageOrders[id]?[$0] }
    let pageOrderDigest = pageOrder.map { $0.map(String.init).joined(separator: ",") }
    let pdfPageOrder = attachmentPDFPageOrders[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentPDFPageOrders[id]?[$0] }
    let pdfPageOrderDigest = pdfPageOrder.map { $0.map(String.init).joined(separator: ",") }
    let pdfPageRotations = attachmentPDFPageRotations[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentPDFPageRotations[id]?[$0] }
    let pdfPageRotationDigest = pdfPageRotations.map { $0.map(String.init).joined(separator: ",") }
    let pdfCropDigest = attachmentPDFCropDigests[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentPDFCropDigests[id]?[$0] }
    let scanMetadataHash = isScan
      ? testSHA256Hex("test-scan-metadata:\(source.attachment.id):\(pageOrderDigest ?? "1")")
      : nil
    let pdfDataSHA256 = isScan
      ? testSHA256Hex("test-scan-pdf:\(source.attachment.id):\(pageOrderDigest ?? "1")")
      : pdfPageOrderDigest.map {
        testSHA256Hex(
          "test-pdf:\(source.attachment.id):\($0):\(pdfPageRotationDigest ?? "0"):\(pdfCropDigest ?? "uncropped")"
        )
      } ?? sha256Hex(source.data)
    let orientation = attachmentScanOrientations[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentScanOrientations[id]?[$0] }
    let imageFilterType = attachmentScanFilterTypes[id]?[source.attachment.id]
      ?? source.attachment.contentIdentifier.flatMap { attachmentScanFilterTypes[id]?[$0] }
    var sourceKinds = [source.sourceKind]
    if isScan {
      sourceKinds.append(contentsOf: [
        "ICAttachment.croppingQuad",
        "ICAttachment.scannedDocumentsMetadata",
        "ICAttachment.docCamPDFVersion",
      ])
    }
    if orientation != nil {
      sourceKinds.append("ICAttachment.orientation")
    }
    if imageFilterType != nil {
      sourceKinds.append("ICAttachment.imageFilterType")
    }
    return NotesAttachmentScanPDFInspectionSource(
      noteID: source.noteID,
      attachment: source.attachment,
      pdfDataByteCount: source.data.count,
      pdfDataSHA256: pdfDataSHA256,
      pdfPageCount: source.data.starts(with: Data("%PDF".utf8)) ? (isScan ? pageOrder?.count ?? 1 : pdfPageOrder?.count ?? 1) : nil,
      pdfSourceKind: source.sourceKind,
      croppingQuadPresent: isScan,
      croppingQuadSHA256: cropHash,
      scannedDocumentsMetadataPresent: isScan,
      scannedDocumentsMetadataCount: isScan ? pageOrder?.count ?? 1 : nil,
      scannedDocumentsMetadataSHA256: scanMetadataHash,
      docCamPDFVersion: isScan ? 7 : nil,
      orientation: orientation,
      orientationSHA256: orientation.map { testSHA256Hex("\($0)") },
      imageFilterType: imageFilterType,
      imageFilterTypeSHA256: imageFilterType.map { testSHA256Hex("\($0)") },
      sourceKinds: sourceKinds
    )
  }

