  func addAttachment(_ draft: NotesAttachmentAddDraft) throws -> NotesAttachmentAddWriteResult {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes attachment add target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let next = attachmentAddDrafts.count + 1
    let record = NotesAttachmentRecord(
      id: "attachment-added-\(next)",
      title: draft.filename,
      typeUTI: "public.data",
      contentIdentifier: "attachment-added-content-\(next)",
      attachmentType: 9,
      fileSizeBytes: Int64(draft.data.count),
      mediaFilename: draft.filename,
      isInline: false,
      isDeletedOrInTrash: false
    )
    attachments[draft.noteID, default: []].append(record)
    attachmentData[draft.noteID, default: [:]][record.id] = draft.data
    if let contentIdentifier = record.contentIdentifier {
      attachmentData[draft.noteID, default: [:]][contentIdentifier] = draft.data
    }
    attachmentAddDrafts.append(draft)
    return NotesAttachmentAddWriteResult(noteID: draft.noteID, attachment: record)
  }

  func renameAttachment(_ draft: NotesAttachmentRenameDraft) throws -> NotesAttachmentRenameWriteResult {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes attachment rename target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let current = attachments[draft.noteID] ?? []
    let matches = current.filter { attachment in
      attachment.id == draft.attachmentID
        || attachment.contentIdentifier == draft.attachmentID
        || attachment.mediaFilename == draft.attachmentID
        || attachment.title == draft.attachmentID
    }
    guard let oldAttachment = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Attachment selector matched multiple attachments on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard oldAttachment.isDeletedOrInTrash != true else {
      throw CLIError(
        code: .validationError,
        message: "Notes attachment rename target must be visible.",
        details: ["attachment_sha256": "test"]
      )
    }

    let changed = (oldAttachment.title ?? oldAttachment.mediaFilename) != draft.name
    let renamed = NotesAttachmentRecord(
      id: oldAttachment.id,
      title: draft.name,
      typeUTI: oldAttachment.typeUTI,
      contentIdentifier: oldAttachment.contentIdentifier,
      attachmentType: oldAttachment.attachmentType,
      fileSizeBytes: oldAttachment.fileSizeBytes,
      mediaFilename: oldAttachment.mediaFilename,
      isInline: oldAttachment.isInline,
      isDeletedOrInTrash: oldAttachment.isDeletedOrInTrash
    )
    attachments[draft.noteID] = current.map { $0.id == oldAttachment.id ? renamed : $0 }
    attachmentRenameDrafts.append(draft)
    return NotesAttachmentRenameWriteResult(
      noteID: draft.noteID,
      oldAttachment: oldAttachment,
      attachment: renamed,
      changed: changed
    )
  }

  func removeAttachment(_ draft: NotesAttachmentRemoveDraft) throws -> NotesAttachmentRemoveWriteResult {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes attachment remove target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let current = attachments[draft.noteID] ?? []
    let matches = current.filter { attachment in
      attachment.id == draft.attachmentID
        || attachment.contentIdentifier == draft.attachmentID
        || attachment.mediaFilename == draft.attachmentID
        || attachment.title == draft.attachmentID
    }
    guard let attachment = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Attachment selector matched multiple attachments on the note.",
        details: ["attachment_sha256": "test"]
      )
    }

    attachments[draft.noteID] = current.filter {
      $0.id != attachment.id
        && (attachment.contentIdentifier == nil || $0.contentIdentifier != attachment.contentIdentifier)
    }
    attachmentData[draft.noteID]?[attachment.id] = nil
    if let contentIdentifier = attachment.contentIdentifier {
      attachmentData[draft.noteID]?[contentIdentifier] = nil
    }
    attachmentRemoveDrafts.append(draft)
    return NotesAttachmentRemoveWriteResult(noteID: draft.noteID, attachment: attachment, changed: true)
  }

