  func applyAttachmentMarkup(_ draft: NotesAttachmentMarkupEditDraft) throws
    -> NotesAttachmentMarkupEditWriteResult
  {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes attachment Markup edit target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let current = attachments[draft.noteID] ?? []
    let matches = current.filter { attachment in
      attachment.id == draft.attachmentID
        || attachment.contentIdentifier == draft.attachmentID
        || attachment.mediaFilename == draft.attachmentID
        || attachment.title == draft.attachmentID
    }
    guard let attachment = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Attachment selector matched multiple attachments on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard attachment.isDeletedOrInTrash != true else {
      throw CLIError(
        code: .validationError,
        message: "Notes attachment Markup edit target must be visible.",
        details: ["attachment_sha256": "test"]
      )
    }

    attachmentMarkupModelData[draft.noteID, default: [:]][attachment.id] = draft.data
    if let contentIdentifier = attachment.contentIdentifier {
      attachmentMarkupModelData[draft.noteID, default: [:]][contentIdentifier] = draft.data
    }
    attachmentMarkupEditDrafts.append(draft)
    return NotesAttachmentMarkupEditWriteResult(
      noteID: draft.noteID,
      oldAttachment: attachment,
      attachment: attachment,
      changed: true
    )
  }

  func setAttachmentImageDescription(_ draft: NotesAttachmentImageDescriptionDraft) throws
    -> NotesAttachmentImageDescriptionWriteResult
  {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes image description target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let oldSource = try readAttachmentImageDescription(noteID: draft.noteID, attachmentID: draft.attachmentID)
    let newDescription = normalizedImageDescription(draft.descriptionText)
    if let newDescription {
      attachmentImageDescriptions[draft.noteID, default: [:]][oldSource.attachment.id] = newDescription
      if let contentIdentifier = oldSource.attachment.contentIdentifier {
        attachmentImageDescriptions[draft.noteID, default: [:]][contentIdentifier] = newDescription
      }
    } else {
      attachmentImageDescriptions[draft.noteID, default: [:]].removeValue(forKey: oldSource.attachment.id)
      if let contentIdentifier = oldSource.attachment.contentIdentifier {
        attachmentImageDescriptions[draft.noteID, default: [:]].removeValue(forKey: contentIdentifier)
      }
    }
    updateAttachmentRecord(
      noteID: draft.noteID,
      attachmentID: oldSource.attachment.id,
      description: newDescription
    )
    attachmentImageDescriptionDrafts.append(draft)
    let source = try readAttachmentImageDescription(noteID: draft.noteID, attachmentID: oldSource.attachment.id)
    return NotesAttachmentImageDescriptionWriteResult(
      noteID: draft.noteID,
      oldSource: oldSource,
      source: source,
      changed: oldSource.descriptionText != source.descriptionText
    )
  }

  func listLinks(noteID id: String, limit: Int) throws -> [NotesLinkRecord] {
    guard notes[id] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    return (links[id] ?? []).prefix(limit).map { $0 }
  }

  func listBacklinks(noteID id: String, limit: Int) throws -> [NotesBacklinkRecord] {
    guard notes[id] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    return (backlinks[id] ?? []).prefix(limit).map { $0 }
  }

  func resolveLink(noteID id: String, linkID: String) throws -> NotesLinkResolutionRecord {
    guard notes[id] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let matches = (links[id] ?? []).filter { linkRecordMatches($0, selector: linkID) }
    guard !matches.isEmpty else {
      throw CLIError(code: .notFound, message: "Link was not found.", details: ["link_sha256": testSHA256Hex(linkID)])
    }
    guard matches.count == 1, let link = matches.first else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Link selector matched multiple links.",
        details: ["link_sha256": testSHA256Hex(linkID), "match_count": "\(matches.count)"]
      )
    }
    return NotesLinkResolutionRecord(
      noteID: id,
      requestedLinkID: linkID,
      link: link,
      destination: linkDestination(link)
    )
  }

  func addLink(_ draft: NotesLinkAddDraft) throws -> NotesLinkAddWriteResult {
    guard notes[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes link add target must be editable.",
        details: ["id": draft.noteID]
      )
    }

    let next = linkAddDrafts.count + 1
