  private func selectedLinkTextEvidence(_ draft: NotesLinkAddDraft) throws
    -> (paragraphIDSHA256: String, ordinal: Int?, byteCount: Int, sha256: String, occurrence: Int)?
  {
    guard let selectedText = draft.selectedText else {
      return nil
    }
    guard let anchor = paragraphAnchors[draft.noteID]?.first(where: { resolution in
      if let paragraph = draft.paragraphIDSHA256 {
        return resolution.anchor.idSHA256 == paragraph
      }
      if let ordinal = draft.ordinal {
        return resolution.anchor.ordinal == ordinal
      }
      return false
    }) else {
      throw CLIError(
        code: .notFound,
        message: "Selected text paragraph selector did not match.",
        details: ["id": draft.noteID]
      )
    }
    let body = notes[draft.noteID]?.body ?? anchor.title ?? ""
    let matchCount = selectedTextMatchCount(text: selectedText, body: body)
    guard matchCount > 0 else {
      throw CLIError(
        code: .notFound,
        message: "Selected text did not match the selected paragraph.",
        details: ["id": draft.noteID]
      )
    }
    let occurrence = draft.occurrence ?? 1
    guard occurrence <= matchCount else {
      throw CLIError(
        code: .notFound,
        message: "Selected text occurrence did not match the selected paragraph.",
        details: ["id": draft.noteID]
      )
    }
    return (
      paragraphIDSHA256: anchor.anchor.idSHA256,
      ordinal: draft.ordinal,
      byteCount: selectedText.utf8.count,
      sha256: testSHA256Hex(selectedText),
      occurrence: occurrence
    )
  }

  private func selectedTextMatchCount(text: String, body: String) -> Int {
    var count = 0
    var searchStart = body.startIndex
    while searchStart < body.endIndex,
      let range = body.range(of: text, range: searchStart..<body.endIndex)
    {
      count += 1
      searchStart = range.upperBound
    }
    return count
  }

  private func noteLinkDisplayText(
    request: NotesNoteLinkDisplayTextDraft?,
    targetNoteID: String,
    currentDisplayText: String?,
    currentAltText: String?
  ) -> (displayText: String?, altText: String?) {
    guard let request else {
      return (currentDisplayText, currentAltText)
    }
    switch request.mode {
    case "custom":
      return (request.displayText, request.displayText)
    case "target_title":
      return (notes[targetNoteID]?.title, nil)
    default:
      return (currentDisplayText, currentAltText)
    }
  }

  private func noteLinkDisplayTextChanged(
    request: NotesNoteLinkDisplayTextDraft?,
    oldLink: NotesLinkRecord,
    targetNoteID: String
  ) -> Bool {
    guard let request else {
      return false
    }
    switch request.mode {
    case "custom":
      return [oldLink.displayText, oldLink.altText].compactMap { $0 }.map(testSHA256Hex)
        .contains(request.displayTextSHA256) == false
    case "target_title":
      return oldLink.altText != nil
        || oldLink.displayText.map(testSHA256Hex) != request.displayTextSHA256
        || oldLink.displayText != notes[targetNoteID]?.title
    default:
      return false
    }
  }

  func addNoteLink(_ draft: NotesNoteLinkAddDraft) throws -> NotesNoteLinkAddWriteResult {
    guard notes[draft.sourceNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Source note was not found.", details: ["id": draft.sourceNoteID])
    }
    guard notes[draft.targetNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Target note was not found.", details: ["id": draft.targetNoteID])
    }
    if noteStates[draft.sourceNoteID]?.isPasswordProtected == true
      || noteStates[draft.sourceNoteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes note link source must be editable.",
        details: ["id": draft.sourceNoteID]
      )
    }
    if noteStates[draft.targetNoteID]?.isPasswordProtected == true
      || noteStates[draft.targetNoteID]?.isDeletedOrInTrash == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes note link target must be visible.",
        details: ["id": draft.targetNoteID]
      )
    }

    let next = noteLinkAddDrafts.count + 1
    let display = noteLinkDisplayText(
      request: draft.displayText,
      targetNoteID: draft.targetNoteID,
      currentDisplayText: nil,
      currentAltText: nil
    )
    let record = NotesLinkRecord(
      id: "note-link-added-\(next)",
      kind: "note",
      displayText: display.displayText,
      altText: display.altText,
      urlString: nil,
      urlScheme: "notes",
      urlSHA256: "note-link-url-hash-\(next)",
      tokenContentIdentifierSHA256: "note-link-token-hash-\(next)",
      typeUTI: "com.apple.notes.inlinelink"
    )
    let sourceNote = notes[draft.sourceNoteID]!
    links[draft.sourceNoteID, default: []].append(record)
    backlinks[draft.targetNoteID, default: []].append(
      NotesBacklinkRecord(sourceNote: noteSummary(sourceNote), link: record))
    noteLinkTargets[record.id] = draft.targetNoteID
    noteLinkAddDrafts.append(draft)
    return NotesNoteLinkAddWriteResult(
      sourceNoteID: draft.sourceNoteID,
      targetNoteID: draft.targetNoteID,
      link: record
    )
  }

