  func updateNoteLink(_ draft: NotesNoteLinkUpdateDraft) throws -> NotesNoteLinkUpdateWriteResult {
    guard notes[draft.sourceNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Source note was not found.", details: ["id": draft.sourceNoteID])
    }
    guard notes[draft.targetNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Target note was not found.", details: ["id": draft.targetNoteID])
    }
    if noteStates[draft.sourceNoteID]?.isPasswordProtected == true
      || noteStates[draft.sourceNoteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes note link update target must be editable.",
        details: ["id": draft.sourceNoteID]
      )
    }
    if noteStates[draft.targetNoteID]?.isPasswordProtected == true {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes note link update destination must be readable.",
        details: ["id": draft.targetNoteID]
      )
    }
    guard draft.link.kind == "note",
      draft.link.isParagraphLink == false,
      draft.link.isInternalParagraphLink == false
    else {
      throw CLIError(
        code: .validationError,
        message: "Only ordinary note-to-note link update is currently supported.",
        details: ["id": draft.sourceNoteID]
      )
    }

    let current = links[draft.sourceNoteID] ?? []
    let matches = current.filter { link in
      link.id == draft.link.id
        || link.id == draft.linkID
        || link.id == draft.requestedLinkID
        || (link.tokenContentIdentifierSHA256 != nil
          && link.tokenContentIdentifierSHA256 == draft.link.tokenContentIdentifierSHA256)
    }
    guard let oldLink = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Link selector did not match any link on the note.",
        details: ["link_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Link selector matched multiple links on the note.",
        details: ["link_sha256": "test"]
      )
    }

    let oldTargetNoteID = noteLinkTargets[oldLink.id] ?? "note-2"
    let targetChanged = oldTargetNoteID != draft.targetNoteID
    let displayChanged = noteLinkDisplayTextChanged(
      request: draft.displayText,
      oldLink: oldLink,
      targetNoteID: draft.targetNoteID
    )
    guard targetChanged || displayChanged else {
      throw CLIError(
        code: .validationError,
        message: "Notes note-to-note link update requires a changed target note or display text.",
        details: ["id": draft.sourceNoteID]
      )
    }
    let display = noteLinkDisplayText(
      request: draft.displayText,
      targetNoteID: draft.targetNoteID,
      currentDisplayText: oldLink.displayText,
      currentAltText: oldLink.altText
    )
    let updated = NotesLinkRecord(
      id: oldLink.id,
      kind: "note",
      displayText: display.displayText,
      altText: display.altText,
      urlString: nil,
      urlScheme: "notes",
      urlSHA256: targetChanged
        ? "note-link-updated-url-hash-\(draft.targetNoteID)"
        : oldLink.urlSHA256,
      tokenContentIdentifierSHA256: targetChanged
        ? "note-link-updated-token-hash-\(draft.targetNoteID)"
        : oldLink.tokenContentIdentifierSHA256,
      typeUTI: oldLink.typeUTI,
      createdAt: oldLink.createdAt
    )
    links[draft.sourceNoteID] = current.map { $0.id == oldLink.id ? updated : $0 }
    let sourceNote = notes[draft.sourceNoteID]!
    if targetChanged {
      backlinks[oldTargetNoteID] = (backlinks[oldTargetNoteID] ?? []).filter { backlink in
        !(backlink.sourceNote.id == draft.sourceNoteID
          && (backlink.link.id == oldLink.id
            || backlink.link.tokenContentIdentifierSHA256 == oldLink.tokenContentIdentifierSHA256))
      }
    } else {
      backlinks[draft.targetNoteID] = (backlinks[draft.targetNoteID] ?? []).filter { backlink in
        !(backlink.sourceNote.id == draft.sourceNoteID
          && (backlink.link.id == oldLink.id
            || backlink.link.tokenContentIdentifierSHA256 == oldLink.tokenContentIdentifierSHA256))
      }
    }
    backlinks[draft.targetNoteID, default: []].append(
      NotesBacklinkRecord(sourceNote: noteSummary(sourceNote), link: updated))
    noteLinkTargets[oldLink.id] = draft.targetNoteID
    noteLinkUpdateDrafts.append(draft)
    return NotesNoteLinkUpdateWriteResult(
      sourceNoteID: draft.sourceNoteID,
      oldTargetNoteID: oldTargetNoteID,
      targetNoteID: draft.targetNoteID,
      oldLink: oldLink,
      link: updated,
      changed: true
    )
  }

  func updateParagraphLink(_ draft: NotesParagraphLinkUpdateDraft) throws
    -> NotesParagraphLinkUpdateWriteResult
  {
    guard notes[draft.sourceNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Source note was not found.", details: ["id": draft.sourceNoteID])
    }
    guard notes[draft.targetNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Target note was not found.", details: ["id": draft.targetNoteID])
    }
    if noteStates[draft.sourceNoteID]?.isPasswordProtected == true
      || noteStates[draft.sourceNoteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes paragraph link update source must be editable.",
        details: ["id": draft.sourceNoteID]
      )
    }
    if noteStates[draft.targetNoteID]?.isPasswordProtected == true
      || noteStates[draft.targetNoteID]?.isDeletedOrInTrash == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes paragraph link update target must be visible.",
        details: ["id": draft.targetNoteID]
      )
    }
    guard draft.link.kind == "paragraph"
      || draft.link.kind == "internal_paragraph"
      || draft.link.isParagraphLink
      || draft.link.isInternalParagraphLink
    else {
      throw CLIError(
        code: .validationError,
        message: "Only paragraph note-link update is currently supported by this command.",
        details: ["id": draft.sourceNoteID]
      )
    }

    let current = links[draft.sourceNoteID] ?? []
    let matches = current.filter { link in
      link.id == draft.link.id
        || link.id == draft.linkID
        || link.id == draft.requestedLinkID
        || (link.tokenContentIdentifierSHA256 != nil
          && link.tokenContentIdentifierSHA256 == draft.link.tokenContentIdentifierSHA256)
    }
    guard let oldLink = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Link selector did not match any link on the note.",
        details: ["link_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Link selector matched multiple links on the note.",
        details: ["link_sha256": "test"]
      )
    }

    let oldTarget = paragraphLinkTargets[oldLink.id] ?? (
      noteID: "note-2",
      paragraphIDSHA256: "archive-paragraph-anchor-hash",
      tokenSHA256: oldLink.tokenContentIdentifierSHA256 ?? "paragraph-link-token-hash"
    )
    let targetTokenSHA256 =
      oldTarget.noteID == draft.targetNoteID && oldTarget.paragraphIDSHA256 == draft.targetParagraphIDSHA256
      ? oldTarget.tokenSHA256
      : "paragraph-link-updated-token-hash-\(draft.targetNoteID)-\(draft.targetParagraphIDSHA256)"
    guard oldTarget.tokenSHA256 != targetTokenSHA256 else {
      throw CLIError(
        code: .validationError,
        message: "Notes paragraph link update requires a changed target paragraph.",
        details: ["id": draft.sourceNoteID]
      )
    }
    let updated = NotesLinkRecord(
      id: oldLink.id,
      kind: "paragraph",
      displayText: oldLink.displayText,
      altText: oldLink.altText,
      urlString: nil,
      urlScheme: "notes",
      urlSHA256: "paragraph-link-updated-url-hash-\(draft.targetNoteID)-\(draft.targetParagraphIDSHA256)",
      tokenContentIdentifierSHA256: targetTokenSHA256,
      typeUTI: oldLink.typeUTI,
      createdAt: oldLink.createdAt,
      isParagraphLink: true,
      isInternalParagraphLink: oldLink.isInternalParagraphLink
    )
    links[draft.sourceNoteID] = current.map { $0.id == oldLink.id ? updated : $0 }
    backlinks[oldTarget.noteID] = (backlinks[oldTarget.noteID] ?? []).filter { backlink in
      !(backlink.sourceNote.id == draft.sourceNoteID
        && (backlink.link.id == oldLink.id
          || backlink.link.tokenContentIdentifierSHA256 == oldLink.tokenContentIdentifierSHA256))
    }
    let sourceNote = notes[draft.sourceNoteID]!
    backlinks[draft.targetNoteID, default: []].append(
      NotesBacklinkRecord(sourceNote: noteSummary(sourceNote), link: updated))
    paragraphLinkTargets[oldLink.id] = (
      noteID: draft.targetNoteID,
      paragraphIDSHA256: draft.targetParagraphIDSHA256,
      tokenSHA256: targetTokenSHA256
    )
    paragraphLinkUpdateDrafts.append(draft)
    return NotesParagraphLinkUpdateWriteResult(
      sourceNoteID: draft.sourceNoteID,
      oldTargetNoteID: oldTarget.noteID,
      targetNoteID: draft.targetNoteID,
      oldTargetParagraphIDSHA256: oldTarget.paragraphIDSHA256,
      targetParagraphIDSHA256: draft.targetParagraphIDSHA256,
      oldTokenContentIdentifierSHA256: oldTarget.tokenSHA256,
      targetTokenContentIdentifierSHA256: targetTokenSHA256,
      oldLink: oldLink,
      link: updated,
      changed: true
    )
  }

