  func listSmartFolders(account: String?, limit: Int) throws -> [NotesSmartFolderRecord] {
    smartFolders
      .filter { account == nil || $0.accountName.localizedCaseInsensitiveCompare(account ?? "") == .orderedSame }
      .prefix(limit)
      .map { $0 }
  }

  func listSmartFolderNotes(smartFolderID: String, limit: Int) throws -> [NotesNoteSummary] {
    smartFolderNoteLookups.append(smartFolderID)
    let noteIDs = try smartFolderNoteIDs(for: smartFolderID)

    return noteIDs
      .compactMap { notes[$0] }
      .map(noteSummary)
      .prefix(limit)
      .map { $0 }
  }

  func exportSmartFolderCriteria(smartFolderID: String) throws -> NotesSmartFolderCriteriaExportSource {
    guard let smartFolder = smartFolders.first(where: { $0.id == smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder selector did not match any Notes Smart Folder.",
        details: ["smart_folder_id_sha256": "unmatched-smart-folder"]
      )
    }
    guard let queryJSON = smartFolderCriteriaJSON[smartFolderID] else {
      throw CLIError(
        code: .unsupportedOperation,
        message: "Smart Folder raw criteria JSON is unavailable.",
        details: ["smart_folder_id_sha256": testSHA256Hex(smartFolderID)]
      )
    }
    return NotesSmartFolderCriteriaExportSource(smartFolder: smartFolder, data: Data(queryJSON.utf8))
  }

  func createSmartFolder(_ draft: NotesSmartFolderCreateDraft) throws -> NotesSmartFolderCreateWriteResult {
    let id =
      smartFolderCreateDrafts.isEmpty
      ? "smart-folder-created"
      : "smart-folder-created-\(smartFolderCreateDrafts.count + 1)"
    smartFolderCreateDrafts.append(draft)
    let tag = tagRecord(tag: draft.tagDisplayText, accountName: draft.accountName)
    let tagIDs = draft.tagStandardizedContents.map { "tag-\($0)" }.sorted()
    let tagDisplayTexts = draft.tagDisplayTexts.sorted()
    let smartFolder = NotesSmartFolderRecord(
      id: id,
      name: draft.name,
      accountName: draft.accountName,
      description: "Notes tagged \(draft.tagDisplayTexts.joined(separator: ","))",
      shortDescription: draft.tagDisplayTexts.joined(separator: ","),
      queryPresent: true,
      queryJSONLength: 36,
      querySHA256: "created-smart-query-hash",
      criteria: NotesSmartFolderCriteriaSummary(
        queryKind: "tag_selection",
        canBeEdited: true,
        minimumSupportedVersion: 1,
        entityName: "note",
        predicatePresent: true,
        predicateFormatLength: 13,
        predicateFormatSHA256: "created-predicate-hash",
        filterCount: 0,
        tagSelection: NotesSmartFolderTagCriteria(
          selectedTagCount: draft.matchedTagCount,
          includedTagCount: draft.matchedTagCount,
          excludedTagCount: 0,
          tagOperator: draft.tagOperator,
          mode: 1,
          allowsRecentlyDeleted: false,
          tagIdentifiersSHA256: testSHA256Hex(tagIDs.joined(separator: "\0")),
          displayTextsSHA256: testSHA256Hex(tagDisplayTexts.joined(separator: "\0")),
          tagIdentifiers: tagIDs,
          displayTexts: tagDisplayTexts,
          includedTagIdentifiers: tagIDs,
          includedDisplayTexts: tagDisplayTexts
        )
      ),
      visibleNoteCount: draft.matchingNoteCount,
      isEditable: true,
      isDeletable: true
    )
    smartFolders.append(smartFolder)
    smartFolderNoteIDs[id] = Array(notes.values
      .filter { note in
        note.accountName.localizedCaseInsensitiveCompare(draft.accountName) == .orderedSame
          && smartFolderTagSelectionMatches(note: note, draft: draft)
      }
      .map(\.id)
      .prefix(draft.matchingNoteCount))
    return NotesSmartFolderCreateWriteResult(changed: true, smartFolder: smartFolder, tag: tag)
  }

  private func smartFolderTagSelectionMatches(note: NotesNoteDetail, draft: NotesSmartFolderCreateDraft) -> Bool {
    if draft.tagOperator == notesSmartFolderTagSelectionOperatorAny {
      return draft.tagStandardizedContents.contains { tag in
        note.tags.contains { testTagMatches($0, tag) }
      }
    }
    return draft.tagStandardizedContents.allSatisfy { tag in
      note.tags.contains { testTagMatches($0, tag) }
    }
  }

  private func smartFolderTagSelectionMatches(note: NotesNoteDetail, draft: NotesSmartFolderUpdateDraft) -> Bool {
    if draft.tagOperator == notesSmartFolderTagSelectionOperatorAny {
      return draft.tagStandardizedContents.contains { tag in
        note.tags.contains { testTagMatches($0, tag) }
      }
    }
    return draft.tagStandardizedContents.allSatisfy { tag in
      note.tags.contains { testTagMatches($0, tag) }
    }
  }

  func updateSmartFolder(_ draft: NotesSmartFolderUpdateDraft) throws -> NotesSmartFolderUpdateWriteResult {
    smartFolderUpdateDrafts.append(draft)
    guard let index = smartFolders.firstIndex(where: { $0.id == draft.smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder was not found.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }
    guard smartFolders[index].isEditable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes Smart Folder cannot be updated.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }

    let tag = tagRecord(tag: draft.tagDisplayText, accountName: draft.accountName)
    let tagIDs = draft.tagStandardizedContents.map { "tag-\($0)" }.sorted()
    let tagDisplayTexts = draft.tagDisplayTexts.sorted()
    smartFolders[index].description = "Notes tagged \(draft.tagDisplayTexts.joined(separator: ","))"
    smartFolders[index].shortDescription = draft.tagDisplayTexts.joined(separator: ",")
    smartFolders[index].queryPresent = true
    smartFolders[index].queryJSONLength = 44
    smartFolders[index].querySHA256 = "updated-smart-query-hash"
    smartFolders[index].criteria = NotesSmartFolderCriteriaSummary(
      queryKind: "tag_selection",
      canBeEdited: true,
      minimumSupportedVersion: 1,
      entityName: "note",
      predicatePresent: true,
      predicateFormatLength: 13,
      predicateFormatSHA256: "updated-predicate-hash",
      filterCount: 0,
      tagSelection: NotesSmartFolderTagCriteria(
        selectedTagCount: draft.matchedTagCount,
        includedTagCount: draft.matchedTagCount,
        excludedTagCount: 0,
        tagOperator: draft.tagOperator,
        mode: 1,
        allowsRecentlyDeleted: false,
        tagIdentifiersSHA256: testSHA256Hex(tagIDs.joined(separator: "\0")),
        displayTextsSHA256: testSHA256Hex(tagDisplayTexts.joined(separator: "\0")),
        tagIdentifiers: tagIDs,
        displayTexts: tagDisplayTexts,
        includedTagIdentifiers: tagIDs,
        includedDisplayTexts: tagDisplayTexts
      )
    )
    smartFolders[index].visibleNoteCount = draft.matchingNoteCount
    smartFolderNoteIDs[draft.smartFolderID] = Array(notes.values
      .filter { note in
        note.accountName.localizedCaseInsensitiveCompare(draft.accountName) == .orderedSame
          && smartFolderTagSelectionMatches(note: note, draft: draft)
      }
      .map(\.id)
      .prefix(draft.matchingNoteCount))
    return NotesSmartFolderUpdateWriteResult(changed: true, smartFolder: smartFolders[index], tag: tag)
  }

  func createSmartFolderBuiltInCriteria(_ draft: NotesSmartFolderBuiltInCriteriaCreateDraft) throws
    -> NotesSmartFolderBuiltInCriteriaCreateWriteResult
  {
    let id =
      smartFolderBuiltInCriteriaCreateDrafts.isEmpty
      ? "smart-folder-built-in"
      : "smart-folder-built-in-\(smartFolderBuiltInCriteriaCreateDrafts.count + 1)"
    smartFolderBuiltInCriteriaCreateDrafts.append(draft)
    let noteIDs = builtInCriteriaNoteIDs(
      kinds: draft.criteriaKinds,
      accountName: draft.accountName,
      dateCriteria: draft.dateCriteria,
      folderCriteria: draft.folderCriteria,
      folderCriteriaByKind: draft.folderCriteriaByKind,
      participantCriteria: draft.participantCriteria,
      joinOperator: draft.joinOperator
    )
    let smartFolder = NotesSmartFolderRecord(
      id: id,
      name: draft.name,
      accountName: draft.accountName,
      description: "Built-in \(draft.criteriaKind) criteria",
      shortDescription: draft.criteriaKind,
      queryPresent: true,
      queryJSONLength: 52,
      querySHA256: "built-in-\(draft.criteriaKind)-query-hash",
      criteria: builtInCriteriaSummary(
        kinds: draft.criteriaKinds,
        includeRecentlyDeleted: draft.includeRecentlyDeleted,
        dateCriteria: draft.dateCriteria,
        folderCriteria: draft.folderCriteria,
        folderCriteriaByKind: draft.folderCriteriaByKind,
        participantCriteria: draft.participantCriteria,
        joinOperator: draft.joinOperator
      ),
