    smartFolders.append(smartFolder)
    smartFolderNoteIDs[id] = noteIDs
    return NotesSmartFolderBuiltInCriteriaCreateWriteResult(changed: true, smartFolder: smartFolder)
  }

  func updateSmartFolderBuiltInCriteria(_ draft: NotesSmartFolderBuiltInCriteriaUpdateDraft) throws
    -> NotesSmartFolderBuiltInCriteriaUpdateWriteResult
  {
    smartFolderBuiltInCriteriaUpdateDrafts.append(draft)
    guard let index = smartFolders.firstIndex(where: { $0.id == draft.smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder was not found.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }
    guard smartFolders[index].isEditable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes Smart Folder cannot be updated with built-in criteria.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }

    let noteIDs = builtInCriteriaNoteIDs(
      kinds: draft.criteriaKinds,
      accountName: draft.accountName,
      dateCriteria: draft.dateCriteria,
      folderCriteria: draft.folderCriteria,
      folderCriteriaByKind: draft.folderCriteriaByKind,
      participantCriteria: draft.participantCriteria,
      joinOperator: draft.joinOperator
    )
    smartFolders[index].description = "Built-in \(draft.criteriaKind) criteria"
    smartFolders[index].shortDescription = draft.criteriaKind
    smartFolders[index].queryPresent = true
    smartFolders[index].queryJSONLength = 52
    smartFolders[index].querySHA256 = "built-in-\(draft.criteriaKind)-query-hash"
    smartFolders[index].criteria = builtInCriteriaSummary(
      kinds: draft.criteriaKinds,
      includeRecentlyDeleted: draft.includeRecentlyDeleted,
      dateCriteria: draft.dateCriteria,
      folderCriteria: draft.folderCriteria,
      folderCriteriaByKind: draft.folderCriteriaByKind,
      participantCriteria: draft.participantCriteria,
      joinOperator: draft.joinOperator
    )
    smartFolders[index].visibleNoteCount = noteIDs.count
    smartFolderNoteIDs[draft.smartFolderID] = noteIDs
    return NotesSmartFolderBuiltInCriteriaUpdateWriteResult(changed: true, smartFolder: smartFolders[index])
  }

  func duplicateSmartFolder(_ draft: NotesSmartFolderDuplicateDraft) throws -> NotesSmartFolderDuplicateWriteResult {
    smartFolderDuplicateDrafts.append(draft)
    guard let source = smartFolders.first(where: { $0.id == draft.sourceSmartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder was not found.",
        details: ["smart_folder": draft.sourceSmartFolderID]
      )
    }

    let id =
      smartFolderDuplicateDrafts.count == 1
      ? "smart-folder-duplicate"
      : "smart-folder-duplicate-\(smartFolderDuplicateDrafts.count)"
    let smartFolder = NotesSmartFolderRecord(
      id: id,
      name: draft.name,
      accountName: draft.accountName,
      description: source.description,
      shortDescription: source.shortDescription,
      queryPresent: source.queryPresent,
      queryJSONLength: source.queryJSONLength,
      querySHA256: source.querySHA256,
      criteria: source.criteria,
      visibleNoteCount: draft.sourceMatchingNoteCount,
      isEditable: true,
      isDeletable: true
    )
    smartFolders.append(smartFolder)
    smartFolderNoteIDs[id] = try smartFolderNoteIDs(for: draft.sourceSmartFolderID)
    return NotesSmartFolderDuplicateWriteResult(
      changed: true,
      smartFolder: smartFolder,
      sourceSmartFolder: source
    )
  }

  func copySmartFolderCriteria(_ draft: NotesSmartFolderCriteriaCopyDraft) throws
    -> NotesSmartFolderCriteriaCopyWriteResult
  {
    smartFolderCriteriaCopyDrafts.append(draft)
    guard let source = smartFolders.first(where: { $0.id == draft.sourceSmartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Source Smart Folder was not found.",
        details: ["smart_folder": draft.sourceSmartFolderID]
      )
    }
    guard let targetIndex = smartFolders.firstIndex(where: { $0.id == draft.targetSmartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Target Smart Folder was not found.",
        details: ["smart_folder": draft.targetSmartFolderID]
      )
    }
    guard smartFolders[targetIndex].isEditable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes Smart Folder criteria cannot be copied to this target.",
        details: ["smart_folder": draft.targetSmartFolderID]
      )
    }

    smartFolders[targetIndex].description = source.description
    smartFolders[targetIndex].shortDescription = source.shortDescription
    smartFolders[targetIndex].queryPresent = source.queryPresent
    smartFolders[targetIndex].queryJSONLength = source.queryJSONLength
    smartFolders[targetIndex].querySHA256 = source.querySHA256
    smartFolders[targetIndex].criteria = source.criteria
    smartFolders[targetIndex].visibleNoteCount = draft.sourceMatchingNoteCount
    smartFolderNoteIDs[draft.targetSmartFolderID] = try smartFolderNoteIDs(for: draft.sourceSmartFolderID)
    return NotesSmartFolderCriteriaCopyWriteResult(
      changed: true,
      smartFolder: smartFolders[targetIndex],
      sourceSmartFolder: source
    )
  }

  func importSmartFolderCriteria(_ draft: NotesSmartFolderCriteriaImportDraft) throws
    -> NotesSmartFolderCriteriaImportWriteResult
  {
    smartFolderCriteriaImportDrafts.append(draft)
    guard let targetIndex = smartFolders.firstIndex(where: { $0.id == draft.smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Target Smart Folder was not found.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }
    guard smartFolders[targetIndex].isEditable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes Smart Folder criteria cannot be imported to this target.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }

    smartFolderCriteriaJSON[draft.smartFolderID] = draft.queryJSON
    smartFolders[targetIndex].description = "Imported Smart Folder criteria"
    smartFolders[targetIndex].shortDescription = "Imported"
    smartFolders[targetIndex].queryPresent = true
    smartFolders[targetIndex].queryJSONLength = draft.sourceByteCount
    smartFolders[targetIndex].querySHA256 = draft.sourceSHA256
    smartFolders[targetIndex].criteria = NotesSmartFolderCriteriaSummary(
      queryKind: "query_json_import",
      canBeEdited: true,
      minimumSupportedVersion: 1,
      entityName: "note",
      predicatePresent: true,
      predicateFormatLength: draft.sourceByteCount,
      predicateFormatSHA256: draft.sourceSHA256,
      joinOperator: 1,
      includeRecentlyDeleted: false,
      isValid: true,
      filterCount: 1,
      filters: [
        NotesSmartFolderCriteriaFilter(
          kind: "imported_raw_json",
          isEmpty: false,
          isValid: true,
          rawValuePresent: true,
          rawValueLength: draft.sourceByteCount,
          rawValueSHA256: draft.sourceSHA256
        )
      ]
    )
    smartFolders[targetIndex].visibleNoteCount = smartFolderNoteIDs[draft.smartFolderID]?.count
    return NotesSmartFolderCriteriaImportWriteResult(changed: true, smartFolder: smartFolders[targetIndex])
  }

  func renameSmartFolder(_ draft: NotesSmartFolderRenameDraft) throws -> NotesSmartFolderRecord {
    smartFolderRenameDrafts.append(draft)
    guard let index = smartFolders.firstIndex(where: { $0.id == draft.smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder was not found.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }
    smartFolders[index].name = draft.newName
    return smartFolders[index]
  }

  func deleteSmartFolder(_ draft: NotesSmartFolderDeleteDraft) throws -> Bool {
    smartFolderDeleteDrafts.append(draft)
    guard let index = smartFolders.firstIndex(where: { $0.id == draft.smartFolderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Smart Folder was not found.",
        details: ["smart_folder": draft.smartFolderID]
      )
    }
    smartFolders.remove(at: index)
    smartFolderNoteIDs[draft.smartFolderID] = nil
    return true
  }

  func convertFolderToSmartFolder(_ draft: NotesSmartFolderFolderConversionDraft) throws
    -> NotesSmartFolderFolderConversionWriteResult
  {
    smartFolderFolderConversionDrafts.append(draft)
    guard let sourceFolderIndex = folders.firstIndex(where: { $0.id == draft.folderID }) else {
      throw CLIError(
        code: .notFound,
        message: "Source folder was not found.",
        details: ["folder": draft.folderID]
      )
    }
    guard let targetFolder = folders.first(where: {
      $0.accountName.localizedCaseInsensitiveCompare(draft.accountName) == .orderedSame
        && $0.isDefault == true
    }) else {
      throw CLIError(
        code: .notFound,
        message: "Default target folder was not found.",
        details: ["account": draft.accountName]
      )
    }

    let tag = tagRecord(tag: draft.tagDisplayText, accountName: draft.accountName)
    for noteID in draft.noteIDs {
      guard var note = notes[noteID] else {
        continue
      }
      if !note.tags.contains(where: { testTagMatches($0, draft.tagStandardizedContent) }) {
        note.tags.append(tag)
      }
      note.folderName = targetFolder.name
      note.accountName = draft.accountName
      notes[noteID] = note

      if var state = noteStates[noteID] {
        state.folderID = targetFolder.id
        state.folderIsDefault = true
        state.folderIsSharedViaICloud = false
        state.folderIsSharedReadOnly = false
        noteStates[noteID] = state
      }
    }

    folders.remove(at: sourceFolderIndex)
    let smartFolder = NotesSmartFolderRecord(
      id: "smart-folder-converted",
      name: draft.folderName,
      accountName: draft.accountName,
      description: "Notes tagged \(draft.tagDisplayText)",
      shortDescription: draft.tagDisplayText,
      queryPresent: true,
      queryJSONLength: 41,
      querySHA256: "converted-smart-query-hash",
      criteria: NotesSmartFolderCriteriaSummary(
        queryKind: "tag_selection",
        canBeEdited: true,
        minimumSupportedVersion: 1,
        entityName: "note",
        predicatePresent: true,
        predicateFormatLength: 16,
        predicateFormatSHA256: "converted-predicate-hash",
        filterCount: 0,
        tagSelection: NotesSmartFolderTagCriteria(
          selectedTagCount: 1,
          includedTagCount: 1,
          excludedTagCount: 0,
          tagOperator: 1,
          mode: 1,
          allowsRecentlyDeleted: false,
          tagIdentifiersSHA256: testSHA256Hex(tag.id),
          displayTextsSHA256: testSHA256Hex(tag.displayText)
        )
      ),
      visibleNoteCount: draft.noteIDs.count,
      isEditable: true,
      isDeletable: true
    )
    smartFolders.append(smartFolder)
    smartFolderNoteIDs[smartFolder.id] = draft.noteIDs
    return NotesSmartFolderFolderConversionWriteResult(
      changed: true,
      smartFolder: smartFolder,
      sourceFolderID: draft.folderID,
      sourceFolderName: draft.folderName,
      targetFolderID: targetFolder.id,
      targetFolderName: targetFolder.name,
      tag: tag,
      movedNoteCount: draft.noteIDs.count,
      taggedNoteCount: draft.noteIDs.count,
      noteIDHashes: draft.noteIDHashes
    )
  }

  private func builtInCriteriaSummary(
    kind: String,
    includeRecentlyDeleted: Bool,
    dateCriteria: NotesSmartFolderDateCriteriaParameters? = nil,
    folderCriteria: NotesSmartFolderFolderCriteriaParameters? = nil,
    folderCriteriaByKind: [String: NotesSmartFolderFolderCriteriaParameters] = [:],
    participantCriteria: NotesSmartFolderParticipantCriteriaParameters? = nil,
    joinOperator: Int = 1
  ) -> NotesSmartFolderCriteriaSummary {
    builtInCriteriaSummary(
      kinds: [kind],
      includeRecentlyDeleted: includeRecentlyDeleted,
      dateCriteria: dateCriteria,
      folderCriteria: folderCriteria,
      folderCriteriaByKind: folderCriteriaByKind,
      participantCriteria: participantCriteria,
      joinOperator: joinOperator
    )
  }

  private func builtInCriteriaSummary(
    kinds: [String],
    includeRecentlyDeleted: Bool,
    dateCriteria: NotesSmartFolderDateCriteriaParameters? = nil,
    folderCriteria: NotesSmartFolderFolderCriteriaParameters? = nil,
    folderCriteriaByKind: [String: NotesSmartFolderFolderCriteriaParameters] = [:],
    participantCriteria: NotesSmartFolderParticipantCriteriaParameters? = nil,
    joinOperator: Int = 1
  ) -> NotesSmartFolderCriteriaSummary {
    if kinds == ["untagged"] {
      return NotesSmartFolderCriteriaSummary(
        queryKind: "tag_selection",
        canBeEdited: true,
        minimumSupportedVersion: 1,
        entityName: "note",
        predicatePresent: true,
        predicateFormatLength: 32,
        predicateFormatSHA256: "built-in-untagged-predicate-hash",
        includeRecentlyDeleted: includeRecentlyDeleted,
        isValid: true,
        filterCount: 0,
        filters: [],
        tagSelection: NotesSmartFolderTagCriteria(
          selectedTagCount: 0,
          includedTagCount: 0,
          excludedTagCount: 0,
          tagOperator: notesSmartFolderTagSelectionOperatorAll,
          mode: notesSmartFolderTagSelectionModeAllUntagged,
          allowsRecentlyDeleted: includeRecentlyDeleted
        )
      )
    }
    let useCombinationExpectations = kinds.count > 1
    let expectations = kinds.compactMap { kind -> (kind: String, expectation: NotesSmartFolderBuiltInCriteriaFilterExpectation)? in
      let criteriaFolderCriteria = smartFolderFolderCriteria(
        for: kind,
        folderCriteria: folderCriteria,
        folderCriteriaByKind: folderCriteriaByKind
      )
      let expectation =
        useCombinationExpectations
        ? smartFolderBuiltInCriteriaCombinationFilterExpectation(
          kind: kind,
          dateCriteria: dateCriteria,
          folderCriteria: criteriaFolderCriteria
        )
        : smartFolderBuiltInCriteriaFilterExpectation(
          kind: kind,
          dateCriteria: dateCriteria,
          folderCriteria: criteriaFolderCriteria
        )
      guard let expectation else { return nil }
      return (kind, expectation)
    }
    let isFilterSelection = expectations.count == kinds.count
    let criteriaKey = kinds.joined(separator: ",")
    return NotesSmartFolderCriteriaSummary(
      queryKind: isFilterSelection ? "filter_selection" : "query",
      canBeEdited: true,
      minimumSupportedVersion: 1,
      entityName: "note",
      predicatePresent: true,
      predicateFormatLength: 32,
      predicateFormatSHA256: "built-in-\(criteriaKey)-predicate-hash",
      joinOperator: isFilterSelection ? joinOperator : nil,
      includeRecentlyDeleted: isFilterSelection ? includeRecentlyDeleted : nil,
      isValid: true,
      filterCount: isFilterSelection ? expectations.count : 0,
      filters: isFilterSelection
        ? expectations.map { pair in
          let rawValueSHA256: String?
          if smartFolderParticipantCriteriaKind(pair.kind) {
            rawValueSHA256 = participantCriteria?.participantUserIDSHA256
          } else if smartFolderFolderCriteriaInclusionType(pair.kind) != nil {
            rawValueSHA256 = smartFolderFolderCriteria(
              for: pair.kind,
              folderCriteria: folderCriteria,
              folderCriteriaByKind: folderCriteriaByKind
            ).map { testSHA256Hex($0.folderIDs.joined(separator: "\0")) }
          } else {
            rawValueSHA256 = testSHA256Hex(pair.kind)
          }
          let criteriaFolderCriteria = smartFolderFolderCriteria(
            for: pair.kind,
            folderCriteria: folderCriteria,
            folderCriteriaByKind: folderCriteriaByKind
          )
          return NotesSmartFolderCriteriaFilter(
            kind: pair.expectation.filterKind,
            isEmpty: false,
            isValid: true,
            selectionType: pair.expectation.selectionType,
            inclusionType: pair.expectation.inclusionType,
            rawValuePresent: true,
            rawValueLength: pair.kind.utf8.count,
            rawValueSHA256: rawValueSHA256,
            count: pair.expectation.count ?? 1,
            hasPrimaryDate: pair.expectation.hasPrimaryDate,
            hasSecondaryDate: pair.expectation.hasSecondaryDate,
            hasRelativeRange: pair.expectation.hasRelativeRange,
            folderID: smartFolderFolderCriteriaInclusionType(pair.kind) != nil ? criteriaFolderCriteria?.folderID : nil,
            primaryDate: smartFolderDateCriteriaDescriptor(pair.kind) != nil ? dateCriteria?.primaryDate : nil,
            secondaryDate: smartFolderDateCriteriaDescriptor(pair.kind) != nil ? dateCriteria?.secondaryDate : nil,
            relativeRangeAmount: smartFolderDateCriteriaDescriptor(pair.kind) != nil ? dateCriteria?.relativeAmount : nil,
            relativeRangeSelectionType: smartFolderDateCriteriaDescriptor(pair.kind) != nil
              ? dateCriteria?.relativeUnitSelectionType.map(Int.init)
              : nil,
            participantUserIDSHA256s: smartFolderParticipantCriteriaKind(pair.kind)
              ? participantCriteria.map { [$0.participantUserIDSHA256] } ?? []
              : []
          )
        }
        : []
    )
  }

  private func builtInCriteriaNoteIDs(
    kinds: [String],
    accountName: String,
    dateCriteria: NotesSmartFolderDateCriteriaParameters? = nil,
    folderCriteria: NotesSmartFolderFolderCriteriaParameters? = nil,
    folderCriteriaByKind: [String: NotesSmartFolderFolderCriteriaParameters] = [:],
    participantCriteria: NotesSmartFolderParticipantCriteriaParameters? = nil,
    joinOperator: Int = 1
  ) -> [String] {
    guard !kinds.isEmpty else {
      return []
    }
    let matchedSets = kinds.map { kind in
      Set(
        builtInCriteriaNoteIDs(
          kind: kind,
          accountName: accountName,
          dateCriteria: dateCriteria,
          folderCriteria: folderCriteria,
          folderCriteriaByKind: folderCriteriaByKind,
          participantCriteria: participantCriteria
        )
      )
    }
    let matched = matchedSets.dropFirst().reduce(matchedSets[0]) { partial, next in
      joinOperator == 0 ? partial.union(next) : partial.intersection(next)
    }
    return notes.values
      .filter { $0.id != "note-convertible" }
      .map(\.id)
      .filter { matched.contains($0) }
  }

  private func builtInCriteriaNoteIDs(
    kind: String,
    accountName: String,
    dateCriteria: NotesSmartFolderDateCriteriaParameters? = nil,
    folderCriteria: NotesSmartFolderFolderCriteriaParameters? = nil,
    folderCriteriaByKind: [String: NotesSmartFolderFolderCriteriaParameters] = [:],
    participantCriteria: NotesSmartFolderParticipantCriteriaParameters? = nil
  ) -> [String] {
    let accountNotes = notes.values.filter {
      $0.id != "note-convertible"
        && $0.accountName.localizedCaseInsensitiveCompare(accountName) == .orderedSame
    }
    switch kind {
    case "pinned":
      return accountNotes.filter { $0.id == "note-1" }.map(\.id)
    case "unpinned":
      return accountNotes.filter { $0.id != "note-1" }.map(\.id)
    case "shared":
      return accountNotes.filter { noteStates[$0.id]?.isSharedViaICloud == true }.map(\.id)
    case "not-shared":
      return accountNotes.filter { noteStates[$0.id]?.isSharedViaICloud != true }.map(\.id)
    case "folder":
      guard let folderCriteria = smartFolderFolderCriteria(
        for: kind,
        folderCriteria: folderCriteria,
        folderCriteriaByKind: folderCriteriaByKind
      ) else {
        return []
      }
      let folderIDs = Set(folderCriteria.folderIDs)
      return accountNotes.filter { note in
        guard let folderID = noteStates[note.id]?.folderID else {
          return false
        }
        return folderIDs.contains(folderID)
      }.map(\.id)
    case "not-folder":
      guard let folderCriteria = smartFolderFolderCriteria(
        for: kind,
        folderCriteria: folderCriteria,
        folderCriteriaByKind: folderCriteriaByKind
      ) else {
        return []
      }
      let folderIDs = Set(folderCriteria.folderIDs)
      return accountNotes.filter { note in
        guard let folderID = noteStates[note.id]?.folderID else {
          return true
        }
        return !folderIDs.contains(folderID)
      }.map(\.id)
    case "untagged":
      return accountNotes.filter { $0.tags.isEmpty }.map(\.id)
    case "participants":
      guard participantCriteria != nil else {
        return []
      }
      return accountNotes.filter { (noteStates[$0.id]?.participantCount ?? 0) > 0 }.map(\.id)
    case "mentions":
      guard participantCriteria != nil else {
        return []
      }
      return accountNotes.filter {
        bodyStructures[$0.id]?.attachmentKindCounts.contains { $0.kind == "mention" && $0.count > 0 } == true
      }.map(\.id)
    case "math":
      return accountNotes.filter {
        noteStates[$0.id]?.isMathNote == true
          || (bodyStructures[$0.id]?.mathAttachmentCount ?? 0) > 0
      }.map(\.id)
    case "call":
      return accountNotes.filter { noteStates[$0.id]?.isCallNote == true }.map(\.id)
    case "system-paper":
      return accountNotes.filter { noteStates[$0.id]?.isSystemPaper == true }.map(\.id)
    case "recently-deleted-math":
      return []
    case "locked":
      return accountNotes.filter {
        noteStates[$0.id]?.isPasswordProtected == true
          || noteStates[$0.id]?.isPasswordProtectedAndLocked == true
      }.map(\.id)
    case "unlocked":
      return accountNotes.filter {
        noteStates[$0.id]?.isPasswordProtected != true
          && noteStates[$0.id]?.isPasswordProtectedAndLocked != true
      }.map(\.id)
    case "quick-notes":
      return accountNotes.filter { $0.id == "note-app" }.map(\.id)
    case "not-quick-notes":
      return accountNotes.filter { $0.id != "note-app" }.map(\.id)
    case "attachments":
      return accountNotes.filter { !attachmentRecords(for: $0.id).isEmpty }.map(\.id)
    case "no-attachments":
      return accountNotes.filter { attachmentRecords(for: $0.id).isEmpty }.map(\.id)
    case "attachment-photo-video":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isPhotoOrVideoAttachment) }.map(\.id)
    case "attachment-scans":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isScanAttachment) }.map(\.id)
    case "attachment-drawings":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isDrawingAttachment) }.map(\.id)
    case "attachment-maps":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isMapAttachment) }.map(\.id)
    case "attachment-websites":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isWebsiteAttachment) }.map(\.id)
    case "attachment-audio":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isAudioAttachment) }.map(\.id)
    case "attachment-documents":
      return accountNotes.filter { noteHasAttachment($0.id, matching: isDocumentAttachment) }.map(\.id)
    case "checklists":
      return accountNotes.filter { (bodyStructures[$0.id]?.checklistItemCount ?? 0) > 0 }.map(\.id)
    case "incomplete-checklists":
      return accountNotes.filter { (bodyStructures[$0.id]?.checklistOpenCount ?? 0) > 0 }.map(\.id)
    case "completed-checklists":
      return accountNotes.filter { (bodyStructures[$0.id]?.checklistDoneCount ?? 0) > 0 }.map(\.id)
    case "no-checklists":
      return accountNotes.filter { (bodyStructures[$0.id]?.checklistItemCount ?? 0) == 0 }.map(\.id)
    default:
      if let dateSelection = smartFolderDateCriteriaDescriptor(kind) {
        return accountNotes.filter {
          noteMatchesDateCriteria($0, dateSelection: dateSelection, dateCriteria: dateCriteria)
        }.map(\.id)
      }
      return []
    }
  }

  private func noteMatchesDateCriteria(
    _ note: NotesNoteDetail,
    dateSelection: NotesSmartFolderDateCriteriaDescriptor,
    dateCriteria: NotesSmartFolderDateCriteriaParameters?
  ) -> Bool {
    let date: Date?
    switch dateSelection.filterKind {
    case "date_created":
      date = note.createdAt
    case "date_edited":
      date = note.updatedAt
    default:
      date = nil
    }
    guard let date else {
      return false
    }
    let now = Date()
    let calendar = Calendar.current
    switch dateSelection.selectionType {
    case 0:
      return calendar.isDateInToday(date)
    case 1:
      return calendar.isDateInYesterday(date)
    case 2:
      return date >= (calendar.date(byAdding: .day, value: -7, to: now) ?? now) && date <= now
    case 3:
      return date >= (calendar.date(byAdding: .day, value: -30, to: now) ?? now) && date <= now
    case 4:
      return date >= (calendar.date(byAdding: .month, value: -3, to: now) ?? now) && date <= now
    case 5:
      return date >= (calendar.date(byAdding: .month, value: -12, to: now) ?? now) && date <= now
    case 6:
      guard let start = dateCriteria?.primaryDate, let end = dateCriteria?.secondaryDate else {
        return false
      }
      return date >= start && date <= end
    case 7:
      guard let amount = dateCriteria?.relativeAmount else {
        return false
      }
      let component: Calendar.Component
      switch dateCriteria?.relativeUnitSelectionType {
      case 1:
        component = .hour
      case 2:
        component = .day
      case 3:
        component = .weekOfYear
      case 4:
        component = .month
      case 5:
        component = .year
      default:
        return false
      }
      return date >= (calendar.date(byAdding: component, value: -amount, to: now) ?? now) && date <= now
    case 8:
      guard let target = dateCriteria?.primaryDate else {
        return false
      }
      return calendar.isDate(date, inSameDayAs: target)
    case 9:
      guard let target = dateCriteria?.primaryDate else {
        return false
      }
      return date < calendar.startOfDay(for: target)
    case 10:
      guard let target = dateCriteria?.primaryDate else {
        return false
      }
      return date > notesSmartFolderCriteriaEndOfDay(target)
    default:
      return false
    }
  }

  private func attachmentRecords(for noteID: String) -> [NotesAttachmentRecord] {
    (attachments[noteID] ?? []).filter { $0.isDeletedOrInTrash != true }
  }

  private func selectedImageDescriptionAttachment(
    noteID: String,
    selector: String
  ) throws -> NotesAttachmentRecord {
    let matches = (attachments[noteID] ?? []).filter { attachment in
      [
        attachment.id,
        attachment.contentIdentifier,
        attachment.mediaFilename,
        attachment.title,
      ].compactMap { $0 }.contains(selector)
    }
    guard let attachment = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Attachment selector matched multiple attachments on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    return attachment
  }

  private func imageDescriptionText(
    noteID: String,
    attachment: NotesAttachmentRecord
  ) -> String? {
    normalizedImageDescription(
      attachmentImageDescriptions[noteID]?[attachment.id]
        ?? attachment.contentIdentifier.flatMap { attachmentImageDescriptions[noteID]?[$0] }
    )
  }

  private func imageClassificationSummary(
    noteID: String,
    attachment: NotesAttachmentRecord
  ) -> String? {
    normalizedImageClassificationSummary(
      attachmentImageClassificationSummaries[noteID]?[attachment.id]
        ?? attachment.contentIdentifier.flatMap { attachmentImageClassificationSummaries[noteID]?[$0] }
    )
  }

  private func normalizedImageClassificationSummary(_ value: String?) -> String? {
    guard let value else { return nil }
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    return trimmed.isEmpty ? nil : trimmed
  }

  private func attachmentWithImageClassificationEvidence(
    _ attachment: NotesAttachmentRecord,
    summary: String?,
    version: Int?
  ) -> NotesAttachmentRecord {
    let normalized = normalizedImageClassificationSummary(summary)
    var updated = attachment
    updated.imageClassificationSummaryPresent = normalized != nil
    updated.imageClassificationSummaryByteCount = normalized.map { $0.utf8.count }
    updated.imageClassificationSummarySHA256 = normalized.map(testSHA256Hex)
    updated.imageClassificationSummaryVersion = version
    updated.imageClassificationSummarySourceKind = "ICAttachment.imageClassificationSummary"
    return updated
  }

  private func normalizedImageDescription(_ value: String?) -> String? {
    guard let value else { return nil }
    return value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : value
  }

  private func attachmentWithImageDescriptionEvidence(
    _ attachment: NotesAttachmentRecord,
    description: String?
  ) -> NotesAttachmentRecord {
    let normalized = normalizedImageDescription(description)
    var updated = attachment
    updated.imageDescriptionPresent = normalized != nil
    updated.imageDescriptionByteCount = normalized.map { $0.utf8.count }
    updated.imageDescriptionSHA256 = normalized.map(testSHA256Hex)
    updated.imageDescriptionSourceKind = "ICInlineAttachment.altText"
    return updated
  }

  private func imageTransformSource(
    from exportSource: NotesAttachmentExportSource
  ) -> NotesAttachmentImageTransformSource {
    NotesAttachmentImageTransformSource(
      noteID: exportSource.noteID,
      attachment: exportSource.attachment,
      dataByteCount: exportSource.data.count,
      dataSHA256: sha256Hex(exportSource.data),
      sourceKind: "ICMedia.decryptedData|data|mediaURL"
    )
  }

  private func imageTransformAttachmentSupported(_ attachment: NotesAttachmentRecord) -> Bool {
    let uti = attachment.typeUTI?.lowercased() ?? ""
    let filename = attachment.mediaFilename?.lowercased() ?? ""
    let title = attachment.title?.lowercased() ?? ""
    let ext = filename.split(separator: ".").last.map(String.init) ?? title.split(separator: ".").last.map(String.init) ?? ""
    return uti.contains("image") || ["heic", "jpeg", "jpg", "png", "gif", "tif", "tiff", "webp"].contains(ext)
  }

  private func updateAttachmentMedia(
    noteID: String,
    attachment: NotesAttachmentRecord,
    data: Data
  ) throws {
    attachmentData[noteID, default: [:]][attachment.id] = data
    if let contentIdentifier = attachment.contentIdentifier {
      attachmentData[noteID, default: [:]][contentIdentifier] = data
    }
    guard var noteAttachments = attachments[noteID],
      let index = noteAttachments.firstIndex(where: { record in
        record.id == attachment.id
          || (attachment.contentIdentifier != nil && record.contentIdentifier == attachment.contentIdentifier)
      })
    else {
      throw CLIError(
        code: .notFound,
        message: "Attachment selector did not match any attachment on the note.",
        details: ["attachment_sha256": "test"]
      )
    }
    var updated = noteAttachments[index]
    updated.fileSizeBytes = Int64(data.count)
    noteAttachments[index] = updated
    attachments[noteID] = noteAttachments
  }

  private func updateAttachmentRecord(
    noteID: String,
    attachmentID: String,
    description: String?
  ) {
    guard var noteAttachments = attachments[noteID],
      let index = noteAttachments.firstIndex(where: { attachment in
      attachment.id == attachmentID || attachment.contentIdentifier == attachmentID
    })
    else {
      return
    }
    noteAttachments[index] = attachmentWithImageDescriptionEvidence(
      noteAttachments[index],
      description: description
    )
    attachments[noteID] = noteAttachments
  }

  private func attachmentSupportsImageDescription(_ attachment: NotesAttachmentRecord) -> Bool {
    guard attachment.isInline else { return false }
    let value = attachmentTypeSearchValue(attachment)
    return value.contains("image")
      || value.contains("photo")
      || value.contains("scan")
      || value.contains("scanned")
      || value.contains("drawing")
      || value.contains("sketch")
  }

  private func noteHasAttachment(
    _ noteID: String,
    matching predicate: (NotesAttachmentRecord) -> Bool
  ) -> Bool {
    attachmentRecords(for: noteID).contains(where: predicate)
  }

  private func isPhotoOrVideoAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    let value = attachmentTypeSearchValue(attachment)
    return value.contains("image")
      || value.contains("photo")
      || value.contains("video")
      || value.contains("movie")
  }

  private func isScanAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    attachmentTypeSearchValue(attachment).contains("scan")
  }

  private func isDrawingAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    let value = attachmentTypeSearchValue(attachment)
    return value.contains("drawing") || value.contains("sketch")
  }

  private func isMapAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    attachmentTypeSearchValue(attachment).contains("map")
  }

  private func isWebsiteAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    let value = attachmentTypeSearchValue(attachment)
    return !isMapAttachment(attachment)
      && (value.contains("url")
      || value.contains("web")
      || value.contains("website"))
  }

  private func isAudioAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    attachmentTypeSearchValue(attachment).contains("audio")
  }

  private func isDocumentAttachment(_ attachment: NotesAttachmentRecord) -> Bool {
    !isPhotoOrVideoAttachment(attachment)
      && !isScanAttachment(attachment)
      && !isDrawingAttachment(attachment)
      && !isMapAttachment(attachment)
      && !isWebsiteAttachment(attachment)
      && !isAudioAttachment(attachment)
  }

  private func attachmentTypeSearchValue(_ attachment: NotesAttachmentRecord) -> String {
    [
      attachment.typeUTI,
      attachment.mediaFilename,
      attachment.title,
    ]
    .compactMap { $0?.localizedLowercase }
    .joined(separator: " ")
  }

  private func smartFolderNoteIDs(for smartFolderID: String) throws -> [String] {
    if let noteIDs = smartFolderNoteIDs[smartFolderID] {
      return noteIDs
    }
    switch smartFolderID {
    case "smart-folder-tags":
      return ["note-1", "note-2", "note-3"]
    case "smart-folder-local":
      return ["note-app"]
    default:
      throw CLIError(
        code: .notFound,
        message: "Smart Folder selector did not match any Notes Smart Folder.",
        details: ["smart_folder_id_sha256": "unmatched-smart-folder"]
      )
    }
  }

