  func readTableCell(noteID id: String, tableOrdinal: Int, row: Int, column: Int) throws
    -> NotesBodyTableCellRecord
  {
    guard bodyStructures[id] != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let tables = bodyTables[id] ?? []
    guard tableOrdinal > 0 && tableOrdinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": id, "ordinal": "\(tableOrdinal)"]
      )
    }
    let table = tables[tableOrdinal - 1]
    if let rowCount = table.rowCount, row > rowCount {
      throw CLIError(
        code: .validationError,
        message: "Notes body table row is outside the selected table.",
        details: ["id": id, "row": "\(row)"]
      )
    }
    if let columnCount = table.columnCount, column > columnCount {
      throw CLIError(
        code: .validationError,
        message: "Notes body table column is outside the selected table.",
        details: ["id": id, "column": "\(column)"]
      )
    }
    let text = bodyTableCells[id]?[bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)] ?? ""
    let formats = bodyTableCellFormats[id]?[bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)] ?? []
    let formatDigest = bodyTableCellFormatDigest(text: text, formats: formats)
    return NotesBodyTableCellRecord(
      tableOrdinal: tableOrdinal,
      tableIDSHA256: table.idSHA256,
      row: row,
      column: column,
      textByteCount: text.utf8.count,
      textSHA256: testSHA256Hex(text),
      formatRunCount: text.isEmpty || formats.isEmpty ? 0 : 1,
      formatSHA256: formatDigest,
      containsBold: formats.contains(.bold),
      containsItalic: formats.contains(.italic),
      containsUnderline: formats.contains(.underline),
      containsStrikethrough: formats.contains(.strikethrough)
    )
	  }

