  func setCollapsibleSectionState(_ draft: NotesBodyCollapsibleSetDraft) throws
    -> NotesBodyCollapsibleSetWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    if structure.isPasswordProtected {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body collapsible section target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    var sections = bodyCollapsibleSections[draft.noteID] ?? []
    let targetIndex: Int?
    if let paragraphIDSHA256 = draft.paragraphIDSHA256 {
      targetIndex = sections.firstIndex { $0.paragraphIDSHA256 == paragraphIDSHA256 }
    } else if let ordinal = draft.ordinal {
      targetIndex = sections.firstIndex { $0.ordinal == ordinal }
    } else {
      targetIndex = nil
    }
    guard let targetIndex else {
      throw CLIError(
        code: .notFound,
        message: "Collapsible section selector did not match any section.",
        details: ["id": draft.noteID]
      )
    }

    bodyCollapsibleSetDrafts.append(draft)
    let current = sections[targetIndex].collapsed
    let desired: Bool
    switch draft.state {
    case .collapsed:
      desired = true
    case .expanded:
      desired = false
    case .toggle:
      desired = !current
    }
    let changed = current != desired
    if changed {
      sections[targetIndex].collapsed = desired
      bodyCollapsibleSections[draft.noteID] = sections
      structure.collapsedSectionCount = sections.filter { $0.collapsed }.count
      bodyStructures[draft.noteID] = structure
    }

    return NotesBodyCollapsibleSetWriteResult(
      changed: changed,
      note: note,
      structure: structure,
      target: sections[targetIndex],
      sections: sections
    )
  }

  func addChecklistItem(_ draft: NotesBodyChecklistAddDraft) throws -> NotesBodyChecklistAddWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist add target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyChecklistAddDrafts.append(draft)
    note.body = [note.body ?? "", draft.text].filter { !$0.isEmpty }.joined(separator: "\n")
    notes[draft.noteID] = note

    let addedLength = draft.text.utf8.count + 1
    structure.plainTextByteCount = (structure.plainTextByteCount ?? 0) + addedLength
    structure.plainTextSHA256 = testSHA256Hex(note.body ?? "")
    structure.richTextLength = (structure.richTextLength ?? 0) + addedLength
    structure.paragraphCount = (structure.paragraphCount ?? 0) + 1
    structure.paragraphStyleRunCount += 1
    structure.checklistItemCount += 1
    if draft.checked {
      structure.checklistDoneCount += 1
    } else {
      structure.checklistOpenCount += 1
    }
    structure.hasChecklist = true
    structure.hasChecklistInProgress = structure.checklistOpenCount > 0
    if let index = structure.styleCounts.firstIndex(where: { $0.style == "checklist" }) {
      structure.styleCounts[index].count += 1
    } else {
      structure.styleCounts.append(NotesBodyStyleCount(style: "checklist", count: 1))
    }
    let ordinal = structure.checklistItemCount
    bodyChecklistStates[draft.noteID, default: [:]][ordinal] = draft.checked
    bodyStructures[draft.noteID] = structure

    return NotesBodyChecklistAddWriteResult(changed: true, note: note, structure: structure)
  }

  func createTable(_ draft: NotesBodyTableCreateDraft) throws -> NotesBodyTableCreateWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table create target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyTableCreateDrafts.append(draft)
    note.body = [note.body ?? "", "[table]"].filter { !$0.isEmpty }.joined(separator: "\n")
    notes[draft.noteID] = note

    structure.tableCount += 1
    structure.inlineAttachmentCount += 1
    structure.plainTextSHA256 = testSHA256Hex(note.body ?? "")
    if let beforeByteCount = structure.plainTextByteCount {
      structure.plainTextByteCount = beforeByteCount + "[table]".utf8.count + 1
    }
    if let beforeLength = structure.richTextLength {
      structure.richTextLength = beforeLength + "[table]".utf8.count + 1
    }
    if let index = structure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      structure.attachmentKindCounts[index].count += 1
    } else {
      structure.attachmentKindCounts.append(NotesBodyAttachmentKindCount(kind: "table", count: 1))
    }
    bodyTables[draft.noteID, default: []].append(
      NotesBodyTableRecord(
        ordinal: bodyTables[draft.noteID, default: []].count + 1,
        idSHA256: testSHA256Hex("table-inline-\(draft.textSHA256)"),
        attachmentIDSHA256: testSHA256Hex("table-attachment-\(draft.textSHA256)"),
        contentIdentifierSHA256: testSHA256Hex("table-content-\(draft.textSHA256)"),
        typeUTISHA256: testSHA256Hex("com.apple.notes.table"),
        rowCount: draft.rowCount,
        columnCount: draft.maxColumnCount,
        isDeletable: true
      ))
    let tableOrdinal = bodyTables[draft.noteID, default: []].count
    bodyTableCells[draft.noteID, default: [:]]
      .merge(parsedBodyTableCells(tableOrdinal: tableOrdinal, text: draft.text)) { _, new in new }
    bodyStructures[draft.noteID] = structure

    return NotesBodyTableCreateWriteResult(changed: true, note: note, structure: structure)
  }

  func importTable(_ draft: NotesBodyTableImportDraft) throws -> NotesBodyTableImportWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
