  func updateTableCell(_ draft: NotesBodyTableUpdateDraft) throws -> NotesBodyTableUpdateWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table update target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let target = tables[draft.ordinal - 1]
    if let rowCount = target.rowCount, draft.row > rowCount {
      throw CLIError(
        code: .validationError,
        message: "Notes body table row is outside the selected table.",
        details: ["id": draft.noteID, "row": "\(draft.row)"]
      )
    }
    if let columnCount = target.columnCount, draft.column > columnCount {
      throw CLIError(
        code: .validationError,
        message: "Notes body table column is outside the selected table.",
        details: ["id": draft.noteID, "column": "\(draft.column)"]
      )
    }

    bodyTableUpdateDrafts.append(draft)
    let key = bodyTableCellKey(tableOrdinal: draft.ordinal, row: draft.row, column: draft.column)
    let previous = bodyTableCells[draft.noteID]?[key] ?? ""
    bodyTableCells[draft.noteID, default: [:]][key] = draft.text
    bodyTableCellFormats[draft.noteID, default: [:]][key] = []
    let formatDigest = bodyTableCellFormatDigest(text: draft.text, formats: [])
    let cell = NotesBodyTableCellRecord(
      tableOrdinal: draft.ordinal,
      tableIDSHA256: target.idSHA256,
      row: draft.row,
      column: draft.column,
      textByteCount: draft.textByteCount,
      textSHA256: draft.textSHA256,
      formatRunCount: 0,
      formatSHA256: formatDigest,
      containsBold: false,
      containsItalic: false,
      containsUnderline: false,
      containsStrikethrough: false
    )
    return NotesBodyTableUpdateWriteResult(
      changed: previous != draft.text,
      note: note,
      structure: structure,
      target: target,
      cell: cell,
      tables: tables
    )
  }

  func convertTableToText(_ draft: NotesBodyTableConvertToTextDraft) throws
    -> NotesBodyTableConvertToTextWriteResult
  {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table conversion target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let target = tables.remove(at: draft.ordinal - 1)
    guard target.isDeletable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table target is not deletable.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    guard let rowCount = target.rowCount, let columnCount = target.columnCount,
      rowCount == draft.rowCount, columnCount == draft.columnCount
    else {
      throw CLIError(
        code: .backendUnavailable,
        message: "Notes body table dimensions changed before conversion.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }

    bodyTableConvertToTextDrafts.append(draft)
    let convertedText = bodyTableConvertedText(
      noteID: draft.noteID,
      tableOrdinal: draft.ordinal,
      rowCount: rowCount,
      columnCount: columnCount
    )
    note.body = replacingBodyTableMarker(
      in: note.body ?? "",
      ordinal: draft.ordinal,
      replacement: convertedText
    )
    notes[draft.noteID] = note

    structure.tableCount = max(0, structure.tableCount - 1)
    structure.inlineAttachmentCount = max(0, structure.inlineAttachmentCount - 1)
    structure.plainTextByteCount = note.body?.utf8.count
    structure.plainTextSHA256 = testSHA256Hex(note.body ?? "")
    structure.richTextLength = note.body?.utf8.count
    if let index = structure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      let nextCount = max(0, structure.attachmentKindCounts[index].count - 1)
      if nextCount == 0 {
        structure.attachmentKindCounts.remove(at: index)
      } else {
        structure.attachmentKindCounts[index].count = nextCount
      }
    }
    tables = tables.enumerated().map { index, table in
      var table = table
      table.ordinal = index + 1
      return table
    }
    var nextCells: [String: String] = [:]
    for (key, value) in bodyTableCells[draft.noteID] ?? [:] {
      let parts = key.split(separator: ":").compactMap { Int($0) }
      guard parts.count == 3 else {
        continue
      }
      let tableOrdinal = parts[0]
      if tableOrdinal < draft.ordinal {
        nextCells[key] = value
      } else if tableOrdinal > draft.ordinal {
        nextCells[
          bodyTableCellKey(tableOrdinal: tableOrdinal - 1, row: parts[1], column: parts[2])
        ] = value
      }
    }
    bodyTableCells[draft.noteID] = nextCells
    bodyTables[draft.noteID] = tables
    bodyStructures[draft.noteID] = structure

    return NotesBodyTableConvertToTextWriteResult(
      changed: true,
      note: note,
      structure: structure,
      target: target,
      tables: tables,
      convertedText: convertedText,
      rowCount: rowCount,
      columnCount: columnCount
    )
  }

  func convertTextToTable(_ draft: NotesBodyTableConvertFromTextDraft) throws
    -> NotesBodyTableConvertFromTextWriteResult
  {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes text-to-table conversion target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard let sourceAnchor = structure.paragraphAnchors.first(where: { $0.idSHA256 == draft.paragraphIDSHA256 }) else {
      throw CLIError(
        code: .notFound,
        message: "Notes body paragraph selector did not match any paragraph anchor.",
        details: ["id": draft.noteID, "paragraph_sha256": draft.paragraphIDSHA256]
      )
    }
    guard !sourceAnchor.isHeader, !sourceAnchor.isList, !sourceAnchor.isChecklist, !sourceAnchor.isBlockQuote else {
      throw CLIError(
        code: .validationError,
        message: "Notes text-to-table conversion currently requires an ordinary body paragraph.",
        details: ["id": draft.noteID, "paragraph_sha256": draft.paragraphIDSHA256]
      )
    }
    let sourceText = paragraphAnchors[draft.noteID]?
      .first { $0.anchor.idSHA256 == draft.paragraphIDSHA256 }?
      .title
      ?? note.body
      ?? ""
    let normalized = try normalizedBodyTableText(sourceText)

    bodyTableConvertFromTextDrafts.append(draft)
    note.body = replacingFirstOccurrence(in: note.body ?? "", target: sourceText, replacement: "[table]")
    notes[draft.noteID] = note

    structure.tableCount += 1
    structure.inlineAttachmentCount += 1
    structure.paragraphCount = structure.paragraphCount.map { max(0, $0 - 1) }
    structure.paragraphStyleRunCount = max(0, structure.paragraphStyleRunCount - 1)
    structure.plainTextByteCount = note.body?.utf8.count
    structure.plainTextSHA256 = testSHA256Hex(note.body ?? "")
    structure.richTextLength = note.body?.utf8.count
    if let index = structure.styleCounts.firstIndex(where: { $0.style == sourceAnchor.style }) {
      let count = max(0, structure.styleCounts[index].count - 1)
      if count == 0 {
        structure.styleCounts.remove(at: index)
      } else {
        structure.styleCounts[index].count = count
      }
    }
    if let index = structure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      structure.attachmentKindCounts[index].count += 1
    } else {
      structure.attachmentKindCounts.append(NotesBodyAttachmentKindCount(kind: "table", count: 1))
    }
    structure.paragraphAnchors = structure.paragraphAnchors
      .filter { $0.idSHA256 != draft.paragraphIDSHA256 }
      .enumerated()
      .map { index, anchor in
        var anchor = anchor
        anchor.ordinal = index + 1
        return anchor
      }
    bodyStructures[draft.noteID] = structure
    paragraphAnchors[draft.noteID] = (paragraphAnchors[draft.noteID] ?? [])
      .filter { $0.anchor.idSHA256 != draft.paragraphIDSHA256 }
      .enumerated()
      .map { index, resolution in
        var anchor = resolution.anchor
        anchor.ordinal = index + 1
        return NotesParagraphAnchorResolution(anchor: anchor, paragraphID: resolution.paragraphID, title: resolution.title)
      }

    let targetOrdinal = (bodyTables[draft.noteID] ?? []).count + 1
    let target = NotesBodyTableRecord(
      ordinal: targetOrdinal,
      idSHA256: testSHA256Hex("table-from-text-\(draft.noteID)-\(targetOrdinal)-\(normalized.text)"),
      attachmentIDSHA256: testSHA256Hex("table-from-text-attachment-\(draft.noteID)-\(targetOrdinal)"),
      contentIdentifierSHA256: testSHA256Hex("table-from-text-content-\(draft.noteID)-\(targetOrdinal)"),
      typeUTISHA256: testSHA256Hex("com.apple.notes.table"),
      rowCount: normalized.rowCount,
      columnCount: normalized.maxColumnCount,
      isDeletable: true
    )
    bodyTables[draft.noteID, default: []].append(target)
    bodyTableCells[draft.noteID, default: [:]]
      .merge(parsedBodyTableCells(tableOrdinal: targetOrdinal, text: normalized.text)) { _, new in new }

    return NotesBodyTableConvertFromTextWriteResult(
      changed: true,
      note: note,
      structure: structure,
      target: target,
      tables: bodyTables[draft.noteID] ?? [],
      sourceParagraphIDSHA256: draft.paragraphIDSHA256,
      sourceText: normalized.text,
      rowCount: normalized.rowCount,
      columnCount: normalized.maxColumnCount
    )
  }

  func copyTable(_ draft: NotesBodyTableCopyDraft) throws -> NotesBodyTableCopyWriteResult {
    guard notes[draft.sourceNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Source note was not found.", details: ["id": draft.sourceNoteID])
    }
    guard var targetNote = notes[draft.targetNoteID] else {
      throw CLIError(code: .notFound, message: "Target note was not found.", details: ["id": draft.targetNoteID])
    }
    if noteStates[draft.targetNoteID]?.isPasswordProtected == true
      || noteStates[draft.targetNoteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table copy target must be editable.",
        details: ["id": draft.targetNoteID]
      )
    }
    guard bodyStructures[draft.sourceNoteID] != nil else {
      throw CLIError(code: .notFound, message: "Source note body structure was not found.", details: ["id": draft.sourceNoteID])
    }
    guard var targetStructure = bodyStructures[draft.targetNoteID] else {
      throw CLIError(code: .notFound, message: "Target note body structure was not found.", details: ["id": draft.targetNoteID])
    }
    let sourceTablesBefore = bodyTables[draft.sourceNoteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= sourceTablesBefore.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.sourceNoteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let sourceTable = sourceTablesBefore[draft.ordinal - 1]
    guard let rowCount = sourceTable.rowCount, let columnCount = sourceTable.columnCount,
      rowCount == draft.rowCount, columnCount == draft.columnCount
    else {
      throw CLIError(
        code: .backendUnavailable,
        message: "Notes body table dimensions changed before copy.",
        details: ["id": draft.sourceNoteID, "ordinal": "\(draft.ordinal)"]
      )
    }

    bodyTableCopyDrafts.append(draft)
    let copiedText = bodyTableConvertedText(
      noteID: draft.sourceNoteID,
      tableOrdinal: draft.ordinal,
      rowCount: rowCount,
      columnCount: columnCount
    )
    targetNote.body = [targetNote.body ?? "", "[table]"].filter { !$0.isEmpty }.joined(separator: "\n")
    notes[draft.targetNoteID] = targetNote

    targetStructure.tableCount += 1
    targetStructure.inlineAttachmentCount += 1
    targetStructure.plainTextByteCount = targetNote.body?.utf8.count
    targetStructure.plainTextSHA256 = testSHA256Hex(targetNote.body ?? "")
    targetStructure.richTextLength = targetNote.body?.utf8.count
    if let index = targetStructure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      targetStructure.attachmentKindCounts[index].count += 1
    } else {
      targetStructure.attachmentKindCounts.append(NotesBodyAttachmentKindCount(kind: "table", count: 1))
    }

    var targetTables = bodyTables[draft.targetNoteID] ?? []
    let targetOrdinal = targetTables.count + 1
    let targetTable = NotesBodyTableRecord(
      ordinal: targetOrdinal,
      idSHA256: testSHA256Hex(
        "table-copy-\(draft.targetNoteID)-\(targetOrdinal)-\(draft.sourceNoteID)-\(draft.ordinal)-\(testSHA256Hex(copiedText))"
      ),
      attachmentIDSHA256: testSHA256Hex("table-copy-attachment-\(draft.targetNoteID)-\(targetOrdinal)"),
      contentIdentifierSHA256: testSHA256Hex("table-copy-content-\(draft.targetNoteID)-\(targetOrdinal)"),
      typeUTISHA256: testSHA256Hex("com.apple.notes.table"),
      rowCount: rowCount,
      columnCount: columnCount,
      isDeletable: true
    )
    targetTables.append(targetTable)
    bodyTables[draft.targetNoteID] = targetTables
	    for row in 1...rowCount {
	      for column in 1...columnCount {
	        let sourceKey = bodyTableCellKey(
	          tableOrdinal: draft.ordinal,
	          row: row,
	          column: column
	        )
	        let targetKey = bodyTableCellKey(
	          tableOrdinal: targetOrdinal,
	          row: row,
	          column: column
	        )
	        bodyTableCells[draft.targetNoteID, default: [:]][targetKey] =
	          bodyTableCells[draft.sourceNoteID]?[sourceKey] ?? ""
	        bodyTableCellFormats[draft.targetNoteID, default: [:]][targetKey] =
	          bodyTableCellFormats[draft.sourceNoteID]?[sourceKey] ?? []
	      }
	    }
    bodyStructures[draft.targetNoteID] = targetStructure

    let sourceNote = notes[draft.sourceNoteID] ?? targetNote
    let sourceStructure = bodyStructures[draft.sourceNoteID] ?? targetStructure
    let sourceTables = bodyTables[draft.sourceNoteID] ?? []
    return NotesBodyTableCopyWriteResult(
      changed: true,
      sourceNote: sourceNote,
      targetNote: targetNote,
      sourceStructure: sourceStructure,
      targetStructure: targetStructure,
      sourceTable: sourceTable,
      targetTable: targetTable,
      sourceTables: sourceTables,
      targetTables: targetTables,
      copiedText: copiedText,
      rowCount: rowCount,
      columnCount: columnCount
    )
  }

  func moveTable(_ draft: NotesBodyTableMoveDraft) throws -> NotesBodyTableMoveWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table move target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    guard draft.targetOrdinal > 0 && draft.targetOrdinal <= tables.count else {
      throw CLIError(
        code: .validationError,
        message: "Notes body table move destination is outside table order.",
        details: ["id": draft.noteID, "to_ordinal": "\(draft.targetOrdinal)"]
      )
    }
    guard draft.ordinal != draft.targetOrdinal else {
      throw CLIError(
        code: .validationError,
        message: "Notes body table move source and destination must differ.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)", "to_ordinal": "\(draft.targetOrdinal)"]
      )
    }

    bodyTableMoveDrafts.append(draft)
    let beforeTables = tables
    let beforeTarget = tables.remove(at: draft.ordinal - 1)
    tables.insert(beforeTarget, at: draft.targetOrdinal - 1)
    tables = tables.enumerated().map { index, table in
      var table = table
      table.ordinal = index + 1
      return table
    }

	    let newOrdinalByOldOrdinal: [Int: Int] = Dictionary(uniqueKeysWithValues: beforeTables.enumerated().compactMap { pair in
	      let (oldIndex, beforeTable) = pair
	      guard let newIndex = tables.firstIndex(where: { $0.idSHA256 == beforeTable.idSHA256 }) else {
	        return nil
	      }
	      return (oldIndex + 1, newIndex + 1)
	    })
	    var nextCells: [String: String] = [:]
	    var nextFormats: [String: Set<NotesBodyInlineFormat>] = [:]
	    for (key, value) in bodyTableCells[draft.noteID] ?? [:] {
	      let parts = key.split(separator: ":").compactMap { Int($0) }
	      guard parts.count == 3, let newOrdinal = newOrdinalByOldOrdinal[parts[0]] else {
	        continue
	      }
	      let nextKey = bodyTableCellKey(tableOrdinal: newOrdinal, row: parts[1], column: parts[2])
	      nextCells[nextKey] = value
	      nextFormats[nextKey] = bodyTableCellFormats[draft.noteID]?[key] ?? []
	    }
	    bodyTableCells[draft.noteID] = nextCells
	    bodyTableCellFormats[draft.noteID] = nextFormats
	    bodyTables[draft.noteID] = tables
    let target = tables[draft.targetOrdinal - 1]
    return NotesBodyTableMoveWriteResult(
      changed: true,
      note: note,
      structure: structure,
      beforeTarget: beforeTarget,
      target: target,
      tables: tables
    )
  }

  func changeTableStructure(_ draft: NotesBodyTableStructureDraft) throws -> NotesBodyTableStructureWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table structure target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let beforeTarget = tables[draft.ordinal - 1]
    let dimension = try tableDimension(beforeTarget, axis: draft.axis, draft: draft)
    try validateTableStructureRange(dimension: dimension, draft: draft)

    bodyTableStructureDrafts.append(draft)
    var target = beforeTarget
    switch (draft.axis, draft.action) {
    case (.row, .insert):
      target.rowCount = dimension + draft.count
    case (.row, .delete):
      target.rowCount = dimension - draft.count
    case (.row, .move):
      target.rowCount = dimension
    case (.row, .copy):
      target.rowCount = dimension + draft.count
    case (.row, .clear):
      target.rowCount = dimension
    case (.column, .insert):
      target.columnCount = dimension + draft.count
    case (.column, .delete):
      target.columnCount = dimension - draft.count
    case (.column, .move):
      target.columnCount = dimension
    case (.column, .copy):
      target.columnCount = dimension + draft.count
    case (.column, .clear):
      target.columnCount = dimension
    }
    let movedSliceDigest = tableMoveSliceDigest(draft: draft, target: beforeTarget)
    let copiedSliceDigest = tableCopySliceDigest(draft: draft, target: beforeTarget)
    let clearedSliceDigest = tableClearSliceDigest(draft: draft, target: beforeTarget)
    tables[draft.ordinal - 1] = target
    bodyTables[draft.noteID] = tables
    shiftTableCells(for: draft)

    return NotesBodyTableStructureWriteResult(
      changed: true,
      note: note,
      structure: structure,
      beforeTarget: beforeTarget,
      target: target,
      tables: tables,
      movedSliceCellCount: movedSliceDigest?.cellCount,
      movedSliceSHA256: movedSliceDigest?.sha256,
      copiedSliceCellCount: copiedSliceDigest?.cellCount,
      copiedSliceSHA256: copiedSliceDigest?.sha256,
      clearedSliceCellCount: clearedSliceDigest?.cellCount,
      clearedSliceSHA256: clearedSliceDigest?.sha256
    )
  }

  func formatTableRange(_ draft: NotesBodyTableFormatDraft) throws -> NotesBodyTableFormatWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table format target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let target = tables[draft.ordinal - 1]
    try validateTableFormatRange(table: target, draft: draft)
    let beforeCells = try bodyTableSelectedCells(draft: draft, target: target)
    let beforeTextDigest = bodyTableTextSliceDigest(beforeCells)
    let beforeFormatDigest = bodyTableFormatSliceDigest(beforeCells)
    let expectedChanged = beforeCells.contains { cell in
      cell.textByteCount > 0 && testTableCell(cell, contains: draft.format) != draft.enabled
    }

    bodyTableFormatDrafts.append(draft)
    for key in bodyTableSelectedCellKeys(draft: draft, target: target) {
      let text = bodyTableCells[draft.noteID]?[key] ?? ""
      guard text.isEmpty == false else {
        continue
      }
      var formats = bodyTableCellFormats[draft.noteID]?[key] ?? []
      if draft.enabled {
        formats.insert(draft.format)
      } else {
        formats.remove(draft.format)
      }
      bodyTableCellFormats[draft.noteID, default: [:]][key] = formats
    }

    let cells = try bodyTableSelectedCells(draft: draft, target: target)
    return NotesBodyTableFormatWriteResult(
      changed: expectedChanged,
      note: note,
      structure: structure,
      beforeTarget: target,
      target: target,
      cells: cells,
      tables: tables,
      beforeTextSliceSHA256: beforeTextDigest,
      afterTextSliceSHA256: bodyTableTextSliceDigest(cells),
      beforeFormatSliceSHA256: beforeFormatDigest,
      afterFormatSliceSHA256: bodyTableFormatSliceDigest(cells)
    )
  }

  private func tableDimension(
    _ table: NotesBodyTableRecord,
    axis: NotesBodyTableStructureAxis,
    draft: NotesBodyTableStructureDraft
  ) throws -> Int {
    let dimension = axis == .row ? table.rowCount : table.columnCount
    guard let dimension else {
      throw CLIError(
        code: .backendUnavailable,
        message: "Notes body table dimension is unavailable.",
        details: ["id": draft.noteID, "axis": axis.rawValue]
      )
    }
    return dimension
  }

  private func validateTableStructureRange(dimension: Int, draft: NotesBodyTableStructureDraft) throws {
    guard draft.index > 0 && draft.count > 0 else {
      throw CLIError(
        code: .validationError,
        message: "Notes body table index and count must be positive.",
        details: ["id": draft.noteID]
      )
    }
    switch draft.action {
    case .insert:
      guard draft.index <= dimension + 1 else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table insert index is outside the selected table.",
          details: ["id": draft.noteID, "index": "\(draft.index)"]
        )
      }
    case .delete:
      guard draft.index + draft.count - 1 <= dimension else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table delete range is outside the selected table.",
          details: ["id": draft.noteID, "index": "\(draft.index)", "count": "\(draft.count)"]
        )
      }
      guard dimension - draft.count >= 1 else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table delete must leave at least one row or column.",
          details: ["id": draft.noteID, "axis": draft.axis.rawValue]
        )
      }
    case .move:
      guard draft.count == 1, let toIndex = draft.toIndex, toIndex > 0 else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table move destination must be positive.",
          details: ["id": draft.noteID, "axis": draft.axis.rawValue]
        )
      }
      guard draft.index <= dimension, toIndex <= dimension else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table move source or destination is outside the selected table.",
          details: ["id": draft.noteID, "index": "\(draft.index)", "to": "\(toIndex)"]
        )
      }
      guard draft.index != toIndex else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table move source and destination must differ.",
          details: ["id": draft.noteID, "index": "\(draft.index)", "to": "\(toIndex)"]
        )
      }
    case .copy:
      guard draft.count == 1, let toIndex = draft.toIndex, toIndex > 0 else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table copy destination must be positive.",
          details: ["id": draft.noteID, "axis": draft.axis.rawValue]
        )
      }
      guard draft.index <= dimension, toIndex <= dimension + 1 else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table copy source or destination is outside the selected table.",
          details: ["id": draft.noteID, "index": "\(draft.index)", "to": "\(toIndex)"]
        )
      }
    case .clear:
      guard draft.index + draft.count - 1 <= dimension else {
        throw CLIError(
          code: .validationError,
          message: "Notes body table clear range is outside the selected table.",
          details: ["id": draft.noteID, "index": "\(draft.index)", "count": "\(draft.count)"]
        )
      }
    }
  }

  private func validateTableFormatRange(table: NotesBodyTableRecord, draft: NotesBodyTableFormatDraft) throws {
    let selectedDimension = draft.axis == .row ? table.rowCount : table.columnCount
    let otherDimension = draft.axis == .row ? table.columnCount : table.rowCount
    guard let selectedDimension, let otherDimension, selectedDimension > 0, otherDimension > 0 else {
      throw CLIError(
        code: .backendUnavailable,
        message: "Notes body table format requires table dimensions.",
        details: ["id": draft.noteID, "axis": draft.axis.rawValue]
      )
    }
    guard draft.index > 0, draft.count > 0, draft.index + draft.count - 1 <= selectedDimension else {
      throw CLIError(
        code: .validationError,
        message: "Notes body table format range is outside the selected table.",
        details: ["id": draft.noteID, "index": "\(draft.index)", "count": "\(draft.count)"]
      )
    }
    guard draft.selectedCellCount == draft.count * otherDimension else {
      throw CLIError(
        code: .validationError,
        message: "Notes body table format selected-cell count does not match table dimensions.",
        details: ["id": draft.noteID, "selected_cell_count": "\(draft.selectedCellCount)"]
      )
    }
  }

  private func bodyTableSelectedCells(
    draft: NotesBodyTableFormatDraft,
    target: NotesBodyTableRecord
  ) throws -> [NotesBodyTableCellRecord] {
    try bodyTableSelectedCellCoordinates(draft: draft, target: target).map { row, column in
      try readTableCell(noteID: draft.noteID, tableOrdinal: draft.ordinal, row: row, column: column)
    }
  }

  private func bodyTableSelectedCellKeys(
    draft: NotesBodyTableFormatDraft,
    target: NotesBodyTableRecord
  ) -> [String] {
    bodyTableSelectedCellCoordinates(draft: draft, target: target).map { row, column in
      bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: column)
    }
  }

  private func bodyTableSelectedCellCoordinates(
    draft: NotesBodyTableFormatDraft,
    target: NotesBodyTableRecord
  ) -> [(row: Int, column: Int)] {
    switch draft.axis {
    case .row:
      let columnCount = target.columnCount ?? 0
      guard columnCount > 0 else {
        return []
      }
      return (draft.index..<(draft.index + draft.count)).flatMap { row in
        (1...columnCount).map { column in (row: row, column: column) }
      }
    case .column:
      let rowCount = target.rowCount ?? 0
      guard rowCount > 0 else {
        return []
      }
      return (draft.index..<(draft.index + draft.count)).flatMap { column in
        (1...rowCount).map { row in (row: row, column: column) }
      }
    }
  }

  private func bodyTableTextSliceDigest(_ cells: [NotesBodyTableCellRecord]) -> String {
    testSHA256Hex(cells.map { "\($0.textByteCount):\($0.textSHA256)" }.joined(separator: "|"))
  }

  private func bodyTableFormatSliceDigest(_ cells: [NotesBodyTableCellRecord]) -> String {
    testSHA256Hex(cells.map { "\($0.formatRunCount ?? -1):\($0.formatSHA256 ?? "")" }.joined(separator: "|"))
  }

  private func testTableCell(_ cell: NotesBodyTableCellRecord, contains format: NotesBodyInlineFormat) -> Bool {
    switch format {
    case .bold:
      return cell.containsBold == true
    case .italic:
      return cell.containsItalic == true
    case .underline:
      return cell.containsUnderline == true
    case .strikethrough:
      return cell.containsStrikethrough == true
    }
  }

	  private func shiftTableCells(for draft: NotesBodyTableStructureDraft) {
	    var nextCells: [String: String] = [:]
	    var nextFormats: [String: Set<NotesBodyInlineFormat>] = [:]
	    let originalFormats = bodyTableCellFormats[draft.noteID] ?? [:]
	    for (key, value) in bodyTableCells[draft.noteID] ?? [:] {
	      let parts = key.split(separator: ":").compactMap { Int($0) }
	      guard parts.count == 3 else {
	        continue
      }
      let tableOrdinal = parts[0]
	      var row = parts[1]
	      var column = parts[2]
	      guard tableOrdinal == draft.ordinal else {
	        nextCells[key] = value
	        nextFormats[key] = originalFormats[key] ?? []
	        continue
	      }

      switch (draft.axis, draft.action) {
      case (.row, .insert):
        if row >= draft.index {
          row += draft.count
        }
      case (.row, .delete):
        if row >= draft.index && row < draft.index + draft.count {
          continue
        }
        if row >= draft.index + draft.count {
          row -= draft.count
        }
      case (.column, .insert):
        if column >= draft.index {
          column += draft.count
        }
      case (.column, .delete):
        if column >= draft.index && column < draft.index + draft.count {
          continue
        }
        if column >= draft.index + draft.count {
          column -= draft.count
        }
      case (.row, .move):
        row = movedTableIndex(row, source: draft.index, destination: draft.toIndex ?? draft.index)
      case (.column, .move):
        column = movedTableIndex(column, source: draft.index, destination: draft.toIndex ?? draft.index)
      case (.row, .copy):
        if row >= (draft.toIndex ?? draft.index) {
          row += 1
        }
      case (.column, .copy):
        if column >= (draft.toIndex ?? draft.index) {
          column += 1
        }
	      case (.row, .clear):
	        if row >= draft.index && row < draft.index + draft.count {
	          let nextKey = bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)
	          nextCells[nextKey] = ""
	          nextFormats[nextKey] = []
	          continue
	        }
	      case (.column, .clear):
	        if column >= draft.index && column < draft.index + draft.count {
	          let nextKey = bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)
	          nextCells[nextKey] = ""
	          nextFormats[nextKey] = []
	          continue
	        }
	      }
	      let nextKey = bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)
	      nextCells[nextKey] = value
	      nextFormats[nextKey] = originalFormats[key] ?? []
	    }
	    if draft.action == .copy, let toIndex = draft.toIndex {
	      let originalCells = bodyTableCells[draft.noteID] ?? [:]
      switch draft.axis {
      case .row:
        let columnCount = bodyTables[draft.noteID]?[draft.ordinal - 1].columnCount ?? 0
	        if columnCount > 0 {
	          for column in 1...columnCount {
	            let sourceKey = bodyTableCellKey(tableOrdinal: draft.ordinal, row: draft.index, column: column)
	            let targetKey = bodyTableCellKey(tableOrdinal: draft.ordinal, row: toIndex, column: column)
	            nextCells[targetKey] = originalCells[sourceKey] ?? ""
	            nextFormats[targetKey] = originalFormats[sourceKey] ?? []
	          }
	        }
	      case .column:
	        let rowCount = bodyTables[draft.noteID]?[draft.ordinal - 1].rowCount ?? 0
	        if rowCount > 0 {
	          for row in 1...rowCount {
	            let sourceKey = bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: draft.index)
	            let targetKey = bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: toIndex)
	            nextCells[targetKey] = originalCells[sourceKey] ?? ""
	            nextFormats[targetKey] = originalFormats[sourceKey] ?? []
	          }
	        }
	      }
	    }
	    bodyTableCells[draft.noteID] = nextCells
	    bodyTableCellFormats[draft.noteID] = nextFormats
	  }

  private func bodyTableConvertedText(
    noteID: String,
    tableOrdinal: Int,
    rowCount: Int,
    columnCount: Int
  ) -> String {
    guard rowCount > 0, columnCount > 0 else {
      return ""
    }
    return (1...rowCount).map { row in
      (1...columnCount).map { column in
        bodyTableCells[noteID]?[bodyTableCellKey(tableOrdinal: tableOrdinal, row: row, column: column)] ?? ""
      }
      .joined(separator: "\t")
    }
    .joined(separator: "\n")
  }

  private func replacingBodyTableMarker(in body: String, ordinal: Int, replacement: String) -> String {
    var seen = 0
    var searchStart = body.startIndex
    while let range = body.range(of: "[table]", range: searchStart..<body.endIndex) {
      seen += 1
      if seen == ordinal {
        var updated = body
        updated.replaceSubrange(range, with: replacement)
        return updated
      }
      searchStart = range.upperBound
    }
    return [body, replacement].filter { !$0.isEmpty }.joined(separator: "\n")
  }

  private func movedTableIndex(_ value: Int, source: Int, destination: Int) -> Int {
    if value == source {
      return destination
    }
    if source < destination, value > source, value <= destination {
      return value - 1
    }
    if source > destination, value >= destination, value < source {
      return value + 1
    }
    return value
  }

  private func tableMoveSliceDigest(
    draft: NotesBodyTableStructureDraft,
    target: NotesBodyTableRecord
  ) -> (cellCount: Int, sha256: String)? {
    guard draft.action == .move else {
      return nil
    }
    let texts: [String]
    switch draft.axis {
    case .row:
      let columnCount = target.columnCount ?? 0
      texts = (1...columnCount).map { column in
        bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: draft.index, column: column)] ?? ""
      }
    case .column:
      let rowCount = target.rowCount ?? 0
      texts = (1...rowCount).map { row in
        bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: draft.index)] ?? ""
      }
    }
    return (
      texts.count,
      sha256Hex(texts.map { "\($0.utf8.count):\(sha256Hex($0))" }.joined(separator: "|"))
    )
  }

  private func tableClearSliceDigest(
    draft: NotesBodyTableStructureDraft,
    target: NotesBodyTableRecord
  ) -> (cellCount: Int, sha256: String)? {
    guard draft.action == .clear else {
      return nil
    }
    let texts: [String]
    switch draft.axis {
    case .row:
      let columnCount = target.columnCount ?? 0
      texts = (draft.index..<(draft.index + draft.count)).flatMap { row in
        (1...columnCount).map { column in
          bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: column)] ?? ""
        }
      }
    case .column:
      let rowCount = target.rowCount ?? 0
      texts = (draft.index..<(draft.index + draft.count)).flatMap { column in
        (1...rowCount).map { row in
          bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: column)] ?? ""
        }
      }
    }
    return (
      texts.count,
      sha256Hex(texts.map { "\($0.utf8.count):\(sha256Hex($0))" }.joined(separator: "|"))
    )
  }

  private func tableCopySliceDigest(
    draft: NotesBodyTableStructureDraft,
    target: NotesBodyTableRecord
  ) -> (cellCount: Int, sha256: String)? {
    guard draft.action == .copy else {
      return nil
    }
    let texts: [String]
    switch draft.axis {
    case .row:
      let columnCount = target.columnCount ?? 0
      texts = (1...columnCount).map { column in
        bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: draft.index, column: column)] ?? ""
      }
    case .column:
      let rowCount = target.rowCount ?? 0
      texts = (1...rowCount).map { row in
        bodyTableCells[draft.noteID]?[bodyTableCellKey(tableOrdinal: draft.ordinal, row: row, column: draft.index)] ?? ""
      }
    }
    return (
      texts.count,
      sha256Hex(texts.map { "\($0.utf8.count):\(sha256Hex($0))" }.joined(separator: "|"))
    )
  }

  func updateMathResult(_ draft: NotesBodyMathUpdateDraft) throws -> NotesBodyMathUpdateWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body math update target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var results = bodyMathResults[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= results.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body math result selector did not match any result.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }

    bodyMathUpdateDrafts.append(draft)
    var target = results[draft.ordinal - 1]
    let changed = target.resultSHA256 != draft.resultSHA256 || target.resultByteCount != draft.resultByteCount
    target.resultByteCount = draft.resultByteCount
    target.resultSHA256 = draft.resultSHA256
    target.isValid = true
    results[draft.ordinal - 1] = target
    bodyMathResults[draft.noteID] = results

    return NotesBodyMathUpdateWriteResult(
      changed: changed,
      note: note,
      structure: structure,
      target: target,
      results: results
    )
  }

  func setMathVariable(_ draft: NotesBodyMathVariableSetDraft) throws -> NotesBodyMathVariableSetWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body math variable set target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyMathVariableSetDrafts.append(draft)
    var results = bodyMathResults[draft.noteID] ?? []
    let definitionOrdinal = results.count + 1
    let dependentOrdinal = results.count + 2
    let definitionResultText = "variable-definition-result-\(definitionOrdinal)"
    let dependentResultText = "dependent-result-\(dependentOrdinal)"
    let definition = NotesBodyMathResultRecord(
      ordinal: definitionOrdinal,
      idSHA256: testSHA256Hex("math-variable-definition-inline-attachment-\(definitionOrdinal)"),
      attachmentIDSHA256: testSHA256Hex("math-variable-definition-attachment-\(definitionOrdinal)"),
      contentIdentifierSHA256: testSHA256Hex("math-variable-definition-content-\(definitionOrdinal)"),
      typeUTISHA256: testSHA256Hex("com.apple.notes.calculate-result"),
      resultByteCount: definitionResultText.utf8.count,
      resultSHA256: testSHA256Hex(definitionResultText),
      expressionByteCount: draft.variableDefinitionExpressionByteCount,
      expressionSHA256: draft.variableDefinitionExpressionSHA256,
      isValid: true,
      isRightToLeft: false
    )
    let dependent = NotesBodyMathResultRecord(
      ordinal: dependentOrdinal,
      idSHA256: testSHA256Hex("math-variable-dependent-inline-attachment-\(dependentOrdinal)"),
      attachmentIDSHA256: testSHA256Hex("math-variable-dependent-attachment-\(dependentOrdinal)"),
      contentIdentifierSHA256: testSHA256Hex("math-variable-dependent-content-\(dependentOrdinal)"),
      typeUTISHA256: testSHA256Hex("com.apple.notes.calculate-result"),
      resultByteCount: dependentResultText.utf8.count,
      resultSHA256: testSHA256Hex(dependentResultText),
      expressionByteCount: draft.dependentExpressionByteCount,
      expressionSHA256: draft.dependentExpressionSHA256,
      isValid: true,
      isRightToLeft: false
    )
    results.append(contentsOf: [definition, dependent])
    bodyMathResults[draft.noteID] = results
    structure.inlineAttachmentCount += 2
    structure.mathAttachmentCount += 2
    structure.isMathNote = true
    bodyStructures[draft.noteID] = structure
    let insertedBody = "\(draft.variableDefinitionExpression)\n\(draft.dependentExpression)"
    if note.body?.isEmpty == false {
      note.body? += "\n\(insertedBody)"
    } else {
      note.body = insertedBody
    }
    notes[draft.noteID] = note

    return NotesBodyMathVariableSetWriteResult(
      changed: true,
      note: note,
      structure: structure,
      variableDefinitionResult: definition,
      dependentResult: dependent,
      results: results
    )
  }

  func updateMathVariable(_ draft: NotesBodyMathVariableUpdateDraft) throws
    -> NotesBodyMathVariableUpdateWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body math variable update target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard let structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var results = bodyMathResults[draft.noteID] ?? []
    guard draft.definitionOrdinal > 0 && draft.definitionOrdinal <= results.count,
      draft.dependentOrdinal > 0 && draft.dependentOrdinal <= results.count
    else {
      throw CLIError(
        code: .notFound,
        message: "Notes body math variable selector did not match both results.",
        details: [
          "id": draft.noteID,
          "definition_ordinal": "\(draft.definitionOrdinal)",
          "dependent_ordinal": "\(draft.dependentOrdinal)",
        ]
      )
    }

    bodyMathVariableUpdateDrafts.append(draft)
    let beforeDefinition = results[draft.definitionOrdinal - 1]
    let beforeDependent = results[draft.dependentOrdinal - 1]
    var afterDefinition = beforeDefinition
    let updatedDefinitionExpression = "updated-definition-\(draft.variableValueSHA256)"
    afterDefinition.expressionByteCount = updatedDefinitionExpression.utf8.count
    afterDefinition.expressionSHA256 = testSHA256Hex(updatedDefinitionExpression)
    afterDefinition.resultSHA256 = testSHA256Hex("updated-definition-result-\(draft.variableValueSHA256)")
    afterDefinition.resultByteCount = "updated-definition-result-\(draft.variableValueSHA256)".utf8.count
    var afterDependent = beforeDependent
    let dependentResultText = "dependent-result-after-\(draft.variableValueSHA256)"
    afterDependent.resultByteCount = dependentResultText.utf8.count
    afterDependent.resultSHA256 = testSHA256Hex(dependentResultText)
    results[draft.definitionOrdinal - 1] = afterDefinition
    results[draft.dependentOrdinal - 1] = afterDependent
    bodyMathResults[draft.noteID] = results

    return NotesBodyMathVariableUpdateWriteResult(
      changed: true,
      note: note,
      structure: structure,
      beforeDefinition: beforeDefinition,
      afterDefinition: afterDefinition,
      beforeDependent: beforeDependent,
      afterDependent: afterDependent,
      results: results
    )
  }

  func setMathResultsPreference(_ draft: NotesBodyMathResultsPreferenceDraft) throws
    -> NotesBodyMathResultsPreferenceWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body math results preference target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard bodyStructures[draft.noteID] != nil else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyMathResultsPreferenceDrafts.append(draft)
    let before = try readMathResultsPreference(noteID: draft.noteID)
    let after = Self.mathPreferenceRecord(mode: draft.mode, rawValue: draft.rawValue, noteID: draft.noteID)
    bodyMathPreferences[draft.noteID] = after
    return NotesBodyMathResultsPreferenceWriteResult(
      changed: before.rawValue != draft.rawValue,
      note: note,
      before: before,
      after: after
    )
  }

  func insertMathResult(_ draft: NotesBodyMathInsertDraft) throws -> NotesBodyMathInsertWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body math insert target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyMathInsertDrafts.append(draft)
    var results = bodyMathResults[draft.noteID] ?? []
    let ordinal = results.count + 1
    let generatedResult = "generated-result-\(ordinal)"
    let target = NotesBodyMathResultRecord(
      ordinal: ordinal,
      idSHA256: testSHA256Hex("math-result-inline-attachment-\(ordinal + 1)"),
      attachmentIDSHA256: testSHA256Hex("math-result-attachment-\(ordinal + 1)"),
      contentIdentifierSHA256: testSHA256Hex("math-result-content-\(ordinal + 1)"),
      typeUTISHA256: testSHA256Hex("com.apple.notes.calculate-result"),
      resultByteCount: generatedResult.utf8.count,
      resultSHA256: testSHA256Hex(generatedResult),
      expressionByteCount: draft.expressionByteCount,
      expressionSHA256: draft.expressionSHA256,
      isValid: true,
      isRightToLeft: false
    )
    results.append(target)
    bodyMathResults[draft.noteID] = results
    structure.inlineAttachmentCount += 1
    structure.mathAttachmentCount += 1
    structure.isMathNote = true
    bodyStructures[draft.noteID] = structure
    if note.body?.isEmpty == false {
      note.body? += "\n\(draft.expression)"
    } else {
      note.body = draft.expression
    }
    notes[draft.noteID] = note

    return NotesBodyMathInsertWriteResult(
      changed: true,
      note: note,
      structure: structure,
      target: target,
      results: results
    )
  }

  func deleteTable(_ draft: NotesBodyTableDeleteDraft) throws -> NotesBodyTableDeleteWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table delete target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    var tables = bodyTables[draft.noteID] ?? []
    guard draft.ordinal > 0 && draft.ordinal <= tables.count else {
      throw CLIError(
        code: .notFound,
        message: "Notes body table selector did not match any table.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }
    let target = tables.remove(at: draft.ordinal - 1)
    guard target.isDeletable != false else {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body table target is not deletable.",
        details: ["id": draft.noteID, "ordinal": "\(draft.ordinal)"]
      )
    }

    bodyTableDeleteDrafts.append(draft)
    if var body = note.body {
      if let range = body.range(of: "\n[table]") {
        body.removeSubrange(range)
      } else if let range = body.range(of: "[table]\n") {
        body.removeSubrange(range)
      } else if let range = body.range(of: "[table]") {
        body.removeSubrange(range)
      }
      note.body = body
      notes[draft.noteID] = note
      structure.plainTextSHA256 = testSHA256Hex(body)
    }

    structure.tableCount = max(0, structure.tableCount - 1)
    structure.inlineAttachmentCount = max(0, structure.inlineAttachmentCount - 1)
    if let index = structure.attachmentKindCounts.firstIndex(where: { $0.kind == "table" }) {
      let nextCount = max(0, structure.attachmentKindCounts[index].count - 1)
      if nextCount == 0 {
        structure.attachmentKindCounts.remove(at: index)
      } else {
        structure.attachmentKindCounts[index].count = nextCount
      }
    }
    tables = tables.enumerated().map { index, table in
      var table = table
      table.ordinal = index + 1
      return table
    }
    var nextCells: [String: String] = [:]
    for (key, value) in bodyTableCells[draft.noteID] ?? [:] {
      let parts = key.split(separator: ":").compactMap { Int($0) }
      guard parts.count == 3 else {
        continue
      }
      let tableOrdinal = parts[0]
      if tableOrdinal < draft.ordinal {
        nextCells[key] = value
      } else if tableOrdinal > draft.ordinal {
        nextCells[
          bodyTableCellKey(tableOrdinal: tableOrdinal - 1, row: parts[1], column: parts[2])
        ] = value
      }
    }
    bodyTableCells[draft.noteID] = nextCells
    bodyTables[draft.noteID] = tables
    bodyStructures[draft.noteID] = structure

    return NotesBodyTableDeleteWriteResult(
      changed: true,
      note: note,
      structure: structure,
      target: target,
      tables: tables
    )
  }

  func setChecklistItemState(_ draft: NotesBodyChecklistSetDraft) throws -> NotesBodyChecklistSetWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist set target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    let ordinal = try checklistOrdinal(for: draft, structure: structure)
    var states = bodyChecklistStates[draft.noteID] ?? [:]
    guard let currentChecked = states[ordinal] else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any checklist item.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistSetDrafts.append(draft)
    let changed = currentChecked != draft.checked
    if changed {
      states[ordinal] = draft.checked
      bodyChecklistStates[draft.noteID] = states
      if draft.checked {
        structure.checklistDoneCount += 1
        structure.checklistOpenCount -= 1
      } else {
        structure.checklistDoneCount -= 1
        structure.checklistOpenCount += 1
      }
      structure.hasChecklistInProgress = structure.checklistOpenCount > 0
      syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
      bodyStructures[draft.noteID] = structure
      reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)
    }

    return NotesBodyChecklistSetWriteResult(changed: changed, note: note, structure: structure)
  }

  func setAllChecklistItemStates(_ draft: NotesBodyChecklistSetAllDraft) throws
    -> NotesBodyChecklistSetAllWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist set-all target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard structure.checklistItemCount > 0 else {
      throw CLIError(
        code: .notFound,
        message: "No checklist items were found on the target note.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistSetAllDrafts.append(draft)
    var states = bodyChecklistStates[draft.noteID] ?? [:]
    let changed = states.values.contains { $0 != draft.checked }
    if changed {
      for ordinal in 1...structure.checklistItemCount {
        states[ordinal] = draft.checked
      }
      bodyChecklistStates[draft.noteID] = states
      structure.checklistDoneCount = draft.checked ? structure.checklistItemCount : 0
      structure.checklistOpenCount = draft.checked ? 0 : structure.checklistItemCount
      structure.hasChecklistInProgress = structure.checklistOpenCount > 0
      syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
      bodyStructures[draft.noteID] = structure
      reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)
    }

    return NotesBodyChecklistSetAllWriteResult(changed: changed, note: note, structure: structure)
  }

  func sortChecklistItems(_ draft: NotesBodyChecklistSortDraft) throws -> NotesBodyChecklistSortWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist sort target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let checklistAnchors = structure.paragraphAnchors.filter { $0.isChecklist }
    guard !checklistAnchors.isEmpty else {
      throw CLIError(
        code: .notFound,
        message: "No checklist items were found on the target note.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistSortDrafts.append(draft)
    let sortedChecklistAnchors = stableSortedChecklistAnchors(checklistAnchors)
    let changed = sortedChecklistAnchors.map(\.idSHA256) != checklistAnchors.map(\.idSHA256)
    guard changed else {
      return NotesBodyChecklistSortWriteResult(changed: false, note: note, structure: structure)
    }

    var remainingChecklistAnchors = sortedChecklistAnchors
    structure.paragraphAnchors = structure.paragraphAnchors.map { anchor in
      guard anchor.isChecklist else {
        return anchor
      }
      var next = remainingChecklistAnchors.removeFirst()
      next.ordinal = anchor.ordinal
      return next
    }

    var newOrdinalMap: [String: Int] = [:]
    var newStates: [Int: Bool] = [:]
    for (index, anchor) in sortedChecklistAnchors.enumerated() {
      let newOrdinal = index + 1
      newOrdinalMap[anchor.idSHA256] = newOrdinal
      newStates[newOrdinal] = anchor.checklistDone == true
    }
    bodyChecklistParagraphOrdinals[draft.noteID] = newOrdinalMap
    bodyChecklistStates[draft.noteID] = newStates
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistSortWriteResult(changed: true, note: note, structure: structure)
  }

  func convertParagraphToChecklistItem(_ draft: NotesBodyChecklistConvertDraft) throws
    -> NotesBodyChecklistConvertWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist convert target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard let anchorIndex = checklistConvertAnchorIndex(for: draft, structure: structure) else {
      throw CLIError(
        code: .notFound,
        message: "Paragraph selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }
    guard !structure.paragraphAnchors[anchorIndex].isChecklist else {
      throw CLIError(
        code: .validationError,
        message: "Selected paragraph is already a checklist item; use `body checklist set` to change its state.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistConvertDrafts.append(draft)
    let oldStyle = structure.paragraphAnchors[anchorIndex].style
    structure.paragraphAnchors[anchorIndex].style = "checklist"
    structure.paragraphAnchors[anchorIndex].isHeader = false
    structure.paragraphAnchors[anchorIndex].isList = true
    structure.paragraphAnchors[anchorIndex].isChecklist = true
    structure.paragraphAnchors[anchorIndex].isBlockQuote = false
    structure.paragraphAnchors[anchorIndex].indentationLevel = 0
    structure.paragraphAnchors[anchorIndex].canIndent = true
    structure.paragraphAnchors[anchorIndex].checklistDone = draft.checked
    structure.listItemCount += 1
    structure.checklistItemCount += 1
    if draft.checked {
      structure.checklistDoneCount += 1
    } else {
      structure.checklistOpenCount += 1
    }
    structure.hasChecklist = true
    structure.hasChecklistInProgress = structure.checklistOpenCount > 0
    if let index = structure.styleCounts.firstIndex(where: { $0.style == oldStyle }) {
      structure.styleCounts[index].count -= 1
      if structure.styleCounts[index].count <= 0 {
        structure.styleCounts.remove(at: index)
      }
    }
    if let index = structure.styleCounts.firstIndex(where: { $0.style == "checklist" }) {
      structure.styleCounts[index].count += 1
    } else {
      structure.styleCounts.append(NotesBodyStyleCount(style: "checklist", count: 1))
    }

    let checklistOrdinal = structure.checklistItemCount
    bodyChecklistStates[draft.noteID, default: [:]][checklistOrdinal] = draft.checked
    bodyChecklistParagraphOrdinals[draft.noteID, default: [:]][structure.paragraphAnchors[anchorIndex].idSHA256] =
      checklistOrdinal
    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistConvertWriteResult(changed: true, note: note, structure: structure)
  }

  func convertParagraphRangeToChecklistItems(_ draft: NotesBodyChecklistConvertRangeDraft) throws
    -> NotesBodyChecklistConvertRangeWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist convert-range target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    let orderedAnchors = structure.paragraphAnchors.sorted { $0.ordinal < $1.ordinal }
    guard draft.fromOrdinal > 0, draft.fromOrdinal <= draft.toOrdinal,
      draft.toOrdinal <= orderedAnchors.count
    else {
      throw CLIError(
        code: .validationError,
        message: "`--from-ordinal` and `--to-ordinal` must select an existing paragraph range.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchors = Array(orderedAnchors[(draft.fromOrdinal - 1)...(draft.toOrdinal - 1)])
    if selectedAnchors.contains(where: \.isChecklist) {
      throw CLIError(
        code: .validationError,
        message: "Checklist range convert requires non-checklist paragraph anchors.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistConvertRangeDrafts.append(draft)
    let selectedAnchorIDs = Set(selectedAnchors.map(\.idSHA256))
    let selectedCount = selectedAnchors.count
    let addedListItems = selectedAnchors.filter { !$0.isList }.count
    for anchor in selectedAnchors {
      if let styleIndex = structure.styleCounts.firstIndex(where: { $0.style == anchor.style }) {
        structure.styleCounts[styleIndex].count -= 1
        if structure.styleCounts[styleIndex].count <= 0 {
          structure.styleCounts.remove(at: styleIndex)
        }
      }
    }
    if let styleIndex = structure.styleCounts.firstIndex(where: { $0.style == "checklist" }) {
      structure.styleCounts[styleIndex].count += selectedCount
    } else {
      structure.styleCounts.append(NotesBodyStyleCount(style: "checklist", count: selectedCount))
    }

    for index in structure.paragraphAnchors.indices where selectedAnchorIDs.contains(structure.paragraphAnchors[index].idSHA256) {
      structure.paragraphAnchors[index].style = "checklist"
      structure.paragraphAnchors[index].isHeader = false
      structure.paragraphAnchors[index].isList = true
      structure.paragraphAnchors[index].isChecklist = true
      structure.paragraphAnchors[index].isBlockQuote = false
      structure.paragraphAnchors[index].indentationLevel = 0
      structure.paragraphAnchors[index].canIndent = true
      structure.paragraphAnchors[index].checklistDone = draft.checked
    }

    structure.listItemCount += addedListItems
    structure.checklistItemCount += selectedCount
    if draft.checked {
      structure.checklistDoneCount += selectedCount
    } else {
      structure.checklistOpenCount += selectedCount
    }
    structure.hasChecklist = true
    structure.hasChecklistInProgress = structure.checklistOpenCount > 0

    var states: [Int: Bool] = [:]
    var ordinalMap: [String: Int] = [:]
    var checklistOrdinal = 1
    for anchor in structure.paragraphAnchors.sorted(by: { $0.ordinal < $1.ordinal }) where anchor.isChecklist {
      ordinalMap[anchor.idSHA256] = checklistOrdinal
      states[checklistOrdinal] = anchor.checklistDone ?? false
      checklistOrdinal += 1
    }
    bodyChecklistStates[draft.noteID] = states
    bodyChecklistParagraphOrdinals[draft.noteID] = ordinalMap
    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistConvertRangeWriteResult(changed: true, note: note, structure: structure)
  }

  func reorderChecklistItem(_ draft: NotesBodyChecklistReorderDraft) throws
    -> NotesBodyChecklistReorderWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist reorder target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let checklistAnchors = structure.paragraphAnchors.filter { $0.isChecklist }
    guard let sourceIndex = checklistReorderSourceIndex(for: draft, checklistAnchors: checklistAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any checklist item.",
        details: ["id": draft.noteID]
      )
    }
    guard draft.targetOrdinal > 0 && draft.targetOrdinal <= checklistAnchors.count else {
      throw CLIError(
        code: .validationError,
        message: "`--to-ordinal` must target an existing checklist item.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistReorderDrafts.append(draft)
    let targetIndex = draft.targetOrdinal - 1
    guard sourceIndex != targetIndex else {
      return NotesBodyChecklistReorderWriteResult(changed: false, note: note, structure: structure)
    }

    let oldOrdinalMap = bodyChecklistParagraphOrdinals[draft.noteID] ?? [:]
    let oldStates = bodyChecklistStates[draft.noteID] ?? [:]
    var reorderedChecklistAnchors = checklistAnchors
    let movedAnchor = reorderedChecklistAnchors.remove(at: sourceIndex)
    reorderedChecklistAnchors.insert(movedAnchor, at: targetIndex)

    var remainingChecklistAnchors = reorderedChecklistAnchors
    structure.paragraphAnchors = structure.paragraphAnchors.map { anchor in
      guard anchor.isChecklist else {
        return anchor
      }
      var next = remainingChecklistAnchors.removeFirst()
      next.ordinal = anchor.ordinal
      return next
    }

    var newOrdinalMap: [String: Int] = [:]
    var newStates: [Int: Bool] = [:]
    for (index, anchor) in reorderedChecklistAnchors.enumerated() {
      let newOrdinal = index + 1
      newOrdinalMap[anchor.idSHA256] = newOrdinal
      let oldOrdinal = oldOrdinalMap[anchor.idSHA256] ?? newOrdinal
      newStates[newOrdinal] = oldStates[oldOrdinal] ?? false
    }
    bodyChecklistParagraphOrdinals[draft.noteID] = newOrdinalMap
    bodyChecklistStates[draft.noteID] = newStates
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistReorderWriteResult(changed: true, note: note, structure: structure)
  }

  func indentChecklistItem(_ draft: NotesBodyChecklistIndentDraft) throws
    -> NotesBodyChecklistIndentWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist indent target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let checklistAnchors = structure.paragraphAnchors.filter { $0.isChecklist }
    guard let checklistIndex = checklistIndentSourceIndex(for: draft, checklistAnchors: checklistAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any checklist item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchorID = checklistAnchors[checklistIndex].idSHA256
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchorID }) else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistIndentDrafts.append(draft)
    let currentIndent = structure.paragraphAnchors[anchorIndex].indentationLevel ?? 0
    let canIndent = structure.paragraphAnchors[anchorIndex].canIndent ?? true
    let proposedIndent = currentIndent + draft.delta
    guard proposedIndent >= 0, draft.delta <= 0 || canIndent else {
      return NotesBodyChecklistIndentWriteResult(changed: false, note: note, structure: structure)
    }
    guard proposedIndent != currentIndent else {
      return NotesBodyChecklistIndentWriteResult(changed: false, note: note, structure: structure)
    }

    structure.paragraphAnchors[anchorIndex].indentationLevel = proposedIndent
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistIndentWriteResult(changed: true, note: note, structure: structure)
  }

  func deleteChecklistItem(_ draft: NotesBodyChecklistDeleteDraft) throws
    -> NotesBodyChecklistDeleteWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body checklist delete target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let checklistAnchors = structure.paragraphAnchors.filter { $0.isChecklist }
    guard let checklistIndex = checklistDeleteSourceIndex(for: draft, checklistAnchors: checklistAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any checklist item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchor = checklistAnchors[checklistIndex]
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchor.idSHA256 }) else {
      throw CLIError(
        code: .notFound,
        message: "Checklist selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyChecklistDeleteDrafts.append(draft)
    let oldOrdinalMap = bodyChecklistParagraphOrdinals[draft.noteID] ?? [:]
    let oldStates = bodyChecklistStates[draft.noteID] ?? [:]
    let oldOrdinal = oldOrdinalMap[selectedAnchor.idSHA256] ?? checklistIndex + 1
    let wasDone = selectedAnchor.checklistDone ?? oldStates[oldOrdinal] ?? false

    structure.paragraphAnchors.remove(at: anchorIndex)
    for index in structure.paragraphAnchors.indices {
      structure.paragraphAnchors[index].ordinal = index + 1
    }
    let deletedByteCount = max(1, (selectedAnchor.titleByteCount ?? 0) + 1)
    structure.plainTextByteCount = max(0, (structure.plainTextByteCount ?? 0) - deletedByteCount)
    structure.plainTextSHA256 = "after-delete-\(selectedAnchor.idSHA256)"
    structure.richTextLength = max(0, (structure.richTextLength ?? 0) - deletedByteCount)
    structure.paragraphCount = max(0, (structure.paragraphCount ?? structure.paragraphAnchors.count + 1) - 1)
    structure.paragraphStyleRunCount = max(0, structure.paragraphStyleRunCount - 1)
    structure.listItemCount = max(0, structure.listItemCount - 1)
    structure.checklistItemCount = max(0, structure.checklistItemCount - 1)
    if wasDone {
      structure.checklistDoneCount = max(0, structure.checklistDoneCount - 1)
    } else {
      structure.checklistOpenCount = max(0, structure.checklistOpenCount - 1)
    }
    structure.hasChecklist = structure.checklistItemCount > 0
    structure.hasChecklistInProgress = structure.checklistOpenCount > 0
    if let styleIndex = structure.styleCounts.firstIndex(where: { $0.style == "checklist" }) {
      structure.styleCounts[styleIndex].count -= 1
      if structure.styleCounts[styleIndex].count <= 0 {
        structure.styleCounts.remove(at: styleIndex)
      }
    }

    var newOrdinalMap: [String: Int] = [:]
    var newStates: [Int: Bool] = [:]
    for (index, anchor) in structure.paragraphAnchors.filter({ $0.isChecklist }).enumerated() {
      let newOrdinal = index + 1
      newOrdinalMap[anchor.idSHA256] = newOrdinal
      let oldOrdinal = oldOrdinalMap[anchor.idSHA256] ?? newOrdinal
      newStates[newOrdinal] = anchor.checklistDone ?? oldStates[oldOrdinal] ?? false
    }
    bodyChecklistParagraphOrdinals[draft.noteID] = newOrdinalMap
    bodyChecklistStates[draft.noteID] = newStates
    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyChecklistDeleteWriteResult(changed: true, note: note, structure: structure)
  }

  func addListItem(_ draft: NotesBodyListAddDraft) throws -> NotesBodyListAddWriteResult {
    guard var note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list add target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    bodyListAddDrafts.append(draft)
    note.body = [note.body ?? "", draft.text].filter { !$0.isEmpty }.joined(separator: "\n")
    notes[draft.noteID] = note

    let addedLength = draft.text.utf8.count + 1
    structure.plainTextByteCount = (structure.plainTextByteCount ?? 0) + addedLength
    structure.plainTextSHA256 = testSHA256Hex(note.body ?? "")
    structure.richTextLength = (structure.richTextLength ?? 0) + addedLength
    structure.paragraphCount = (structure.paragraphCount ?? 0) + 1
    structure.paragraphStyleRunCount += 1
    structure.listItemCount += 1
    incrementStyle("list", in: &structure)
    let nextOrdinal = (structure.paragraphAnchors.map(\.ordinal).max() ?? 0) + 1
    let anchor = NotesBodyParagraphAnchorRecord(
      ordinal: nextOrdinal,
      idSHA256: "added-list-\(nextOrdinal)-paragraph-anchor-hash",
      titleByteCount: draft.text.utf8.count,
      titleSHA256: testSHA256Hex(draft.text),
      style: "list",
      listStyle: draft.style.rawValue,
      isList: true,
      isChecklist: false,
      indentationLevel: 0,
      canIndent: true
    )
    structure.paragraphAnchors.append(anchor)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListAddWriteResult(changed: true, note: note, structure: structure)
  }

  func convertParagraphToListItem(_ draft: NotesBodyListConvertDraft) throws
    -> NotesBodyListConvertWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list convert target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard let anchorIndex = listConvertAnchorIndex(for: draft, structure: structure) else {
      throw CLIError(
        code: .notFound,
        message: "Paragraph selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }
    guard !structure.paragraphAnchors[anchorIndex].isChecklist, !structure.paragraphAnchors[anchorIndex].isList else {
      throw CLIError(
        code: .validationError,
        message: "Ordinary list convert requires a non-list paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyListConvertDrafts.append(draft)
    decrementStyle(structure.paragraphAnchors[anchorIndex].style, in: &structure)
    incrementStyle("list", in: &structure)
    structure.paragraphAnchors[anchorIndex].style = "list"
    structure.paragraphAnchors[anchorIndex].listStyle = draft.style.rawValue
    structure.paragraphAnchors[anchorIndex].isHeader = false
    structure.paragraphAnchors[anchorIndex].isList = true
    structure.paragraphAnchors[anchorIndex].isChecklist = false
    structure.paragraphAnchors[anchorIndex].isBlockQuote = false
    structure.paragraphAnchors[anchorIndex].indentationLevel = 0
    structure.paragraphAnchors[anchorIndex].canIndent = true
    structure.paragraphAnchors[anchorIndex].checklistDone = nil
    structure.listItemCount += 1
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListConvertWriteResult(changed: true, note: note, structure: structure)
  }

  func convertParagraphRangeToListItems(_ draft: NotesBodyListConvertRangeDraft) throws
    -> NotesBodyListConvertRangeWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list convert-range target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    let orderedAnchors = structure.paragraphAnchors.sorted { $0.ordinal < $1.ordinal }
    guard draft.fromOrdinal > 0, draft.fromOrdinal <= draft.toOrdinal,
      draft.toOrdinal <= orderedAnchors.count
    else {
      throw CLIError(
        code: .validationError,
        message: "`--from-ordinal` and `--to-ordinal` must select an existing paragraph range.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchors = Array(orderedAnchors[(draft.fromOrdinal - 1)...(draft.toOrdinal - 1)])
    guard selectedAnchors.allSatisfy({ !$0.isList && !$0.isChecklist }) else {
      throw CLIError(
        code: .validationError,
        message: "Ordinary list range convert requires non-list paragraph anchors.",
        details: ["id": draft.noteID]
      )
    }

    bodyListConvertRangeDrafts.append(draft)
    let selectedAnchorIDs = Set(selectedAnchors.map(\.idSHA256))
    for anchor in selectedAnchors {
      decrementStyle(anchor.style, in: &structure)
    }
    incrementStyle("list", by: selectedAnchors.count, in: &structure)
    for index in structure.paragraphAnchors.indices where selectedAnchorIDs.contains(structure.paragraphAnchors[index].idSHA256) {
      structure.paragraphAnchors[index].style = "list"
      structure.paragraphAnchors[index].listStyle = draft.style.rawValue
      structure.paragraphAnchors[index].isHeader = false
      structure.paragraphAnchors[index].isList = true
      structure.paragraphAnchors[index].isChecklist = false
      structure.paragraphAnchors[index].isBlockQuote = false
      structure.paragraphAnchors[index].indentationLevel = 0
      structure.paragraphAnchors[index].canIndent = true
      structure.paragraphAnchors[index].checklistDone = nil
    }
    structure.listItemCount += selectedAnchors.count
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListConvertRangeWriteResult(changed: true, note: note, structure: structure)
  }

  func setListItemStyle(_ draft: NotesBodyListSetStyleDraft) throws -> NotesBodyListSetStyleWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list set-style target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let listAnchors = structure.paragraphAnchors.filter { $0.isList && !$0.isChecklist }.sorted { $0.ordinal < $1.ordinal }
    guard let sourceIndex = listSetStyleSourceIndex(for: draft, listAnchors: listAnchors),
      let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == listAnchors[sourceIndex].idSHA256 })
    else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any ordinary list item.",
        details: ["id": draft.noteID]
      )
    }

    bodyListSetStyleDrafts.append(draft)
    let changed = structure.paragraphAnchors[anchorIndex].listStyle != draft.style.rawValue
    if changed {
      structure.paragraphAnchors[anchorIndex].listStyle = draft.style.rawValue
      bodyStructures[draft.noteID] = structure
      reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)
    }

    return NotesBodyListSetStyleWriteResult(changed: changed, note: note, structure: structure)
  }

  func reorderListItem(_ draft: NotesBodyListReorderDraft) throws
    -> NotesBodyListReorderWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list reorder target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let listAnchors = structure.paragraphAnchors.filter { $0.isList && !$0.isChecklist }
    guard let sourceIndex = listReorderSourceIndex(for: draft, listAnchors: listAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any ordinary list item.",
        details: ["id": draft.noteID]
      )
    }
    guard draft.targetOrdinal > 0 && draft.targetOrdinal <= listAnchors.count else {
      throw CLIError(
        code: .validationError,
        message: "`--to-ordinal` must target an existing ordinary list item.",
        details: ["id": draft.noteID]
      )
    }

    bodyListReorderDrafts.append(draft)
    let targetIndex = draft.targetOrdinal - 1
    guard sourceIndex != targetIndex else {
      return NotesBodyListReorderWriteResult(changed: false, note: note, structure: structure)
    }

    var reorderedListAnchors = listAnchors
    let movedAnchor = reorderedListAnchors.remove(at: sourceIndex)
    reorderedListAnchors.insert(movedAnchor, at: targetIndex)

    var remainingListAnchors = reorderedListAnchors
    structure.paragraphAnchors = structure.paragraphAnchors.map { anchor in
      guard anchor.isList && !anchor.isChecklist else {
        return anchor
      }
      var next = remainingListAnchors.removeFirst()
      next.ordinal = anchor.ordinal
      return next
    }

    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListReorderWriteResult(changed: true, note: note, structure: structure)
  }

  func indentListItem(_ draft: NotesBodyListIndentDraft) throws
    -> NotesBodyListIndentWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list indent target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let listAnchors = structure.paragraphAnchors.filter { $0.isList && !$0.isChecklist }
    guard let listIndex = listIndentSourceIndex(for: draft, listAnchors: listAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any ordinary list item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchorID = listAnchors[listIndex].idSHA256
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchorID }) else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyListIndentDrafts.append(draft)
    let currentIndent = structure.paragraphAnchors[anchorIndex].indentationLevel ?? 0
    let canIndent = structure.paragraphAnchors[anchorIndex].canIndent ?? true
    let proposedIndent = currentIndent + draft.delta
    guard proposedIndent >= 0, draft.delta <= 0 || canIndent else {
      return NotesBodyListIndentWriteResult(changed: false, note: note, structure: structure)
    }
    guard proposedIndent != currentIndent else {
      return NotesBodyListIndentWriteResult(changed: false, note: note, structure: structure)
    }

    structure.paragraphAnchors[anchorIndex].indentationLevel = proposedIndent
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListIndentWriteResult(changed: true, note: note, structure: structure)
  }

  func deleteListItem(_ draft: NotesBodyListDeleteDraft) throws
    -> NotesBodyListDeleteWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list delete target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let listAnchors = structure.paragraphAnchors.filter { $0.isList && !$0.isChecklist }
    guard let listIndex = listDeleteSourceIndex(for: draft, listAnchors: listAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any ordinary list item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchor = listAnchors[listIndex]
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchor.idSHA256 }) else {
      throw CLIError(
        code: .notFound,
        message: "List selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyListDeleteDrafts.append(draft)
    structure.paragraphAnchors.remove(at: anchorIndex)
    for index in structure.paragraphAnchors.indices {
      structure.paragraphAnchors[index].ordinal = index + 1
    }
    let deletedByteCount = max(1, (selectedAnchor.titleByteCount ?? 0) + 1)
    structure.plainTextByteCount = max(0, (structure.plainTextByteCount ?? 0) - deletedByteCount)
    structure.plainTextSHA256 = "after-list-delete-\(selectedAnchor.idSHA256)"
    structure.richTextLength = max(0, (structure.richTextLength ?? 0) - deletedByteCount)
    structure.paragraphCount = max(0, (structure.paragraphCount ?? structure.paragraphAnchors.count + 1) - 1)
    structure.paragraphStyleRunCount = max(0, structure.paragraphStyleRunCount - 1)
    structure.listItemCount = max(0, structure.listItemCount - 1)
    if let styleIndex = structure.styleCounts.firstIndex(where: { $0.style == "list" }) {
      structure.styleCounts[styleIndex].count -= 1
      if structure.styleCounts[styleIndex].count <= 0 {
        structure.styleCounts.remove(at: styleIndex)
      }
    }

    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListDeleteWriteResult(changed: true, note: note, structure: structure)
  }

  func insertTextInListItem(_ draft: NotesBodyListTextInsertDraft) throws
    -> NotesBodyListTextInsertWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list text insertion target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard draft.targetKind == .ordinaryList || draft.insertKind == .lineBreak else {
      throw CLIError(
        code: .validationError,
        message: "Checklist tab insertion is not supported.",
        details: ["id": draft.noteID]
      )
    }

    let targetAnchors = bodyListTextInsertAnchors(for: draft.targetKind, structure: structure)
    guard let targetIndex = bodyListTextInsertSourceIndex(for: draft, targetAnchors: targetAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "List text insertion selector did not match any target item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchor = targetAnchors[targetIndex]
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchor.idSHA256 }) else {
      throw CLIError(
        code: .notFound,
        message: "List text insertion selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyListTextInsertDrafts.append(draft)
    let insertedText = draft.insertKind.insertedText
    let insertedByteCount = insertedText.utf8.count
    structure.paragraphAnchors[anchorIndex].titleByteCount =
      (structure.paragraphAnchors[anchorIndex].titleByteCount ?? 0) + insertedByteCount
    structure.paragraphAnchors[anchorIndex].titleSHA256 =
      testSHA256Hex("\(selectedAnchor.titleSHA256 ?? ""):\(draft.insertKind.rawValue):\(insertedByteCount)")
    structure.plainTextByteCount = (structure.plainTextByteCount ?? 0) + insertedByteCount
    structure.plainTextSHA256 =
      testSHA256Hex("\(structure.plainTextSHA256 ?? ""):\(draft.targetKind.rawValue):\(draft.insertKind.rawValue)")
    structure.richTextLength = (structure.richTextLength ?? 0) + insertedText.utf16.count

    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListTextInsertWriteResult(
      changed: true,
      note: note,
      structure: structure,
      insertedTextByteCount: insertedByteCount,
      insertedTextSHA256: testSHA256Hex(insertedText)
    )
  }

  func endList(_ draft: NotesBodyListEndDraft) throws -> NotesBodyListEndWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body list end target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }

    let targetAnchors = bodyListEndAnchors(for: draft.targetKind, structure: structure)
    guard let targetIndex = bodyListEndSourceIndex(for: draft, targetAnchors: targetAnchors) else {
      throw CLIError(
        code: .notFound,
        message: "List end selector did not match any target item.",
        details: ["id": draft.noteID]
      )
    }
    let selectedAnchor = targetAnchors[targetIndex]
    guard let anchorIndex = structure.paragraphAnchors.firstIndex(where: { $0.idSHA256 == selectedAnchor.idSHA256 }) else {
      throw CLIError(
        code: .notFound,
        message: "List end selector did not match any body paragraph anchor.",
        details: ["id": draft.noteID]
      )
    }

    bodyListEndDrafts.append(draft)
    let nextID = "ended-\(draft.targetKind.rawValue)-\(bodyListEndDrafts.count)-body-paragraph-anchor-hash"
    let created = NotesBodyParagraphAnchorRecord(
      ordinal: selectedAnchor.ordinal + 1,
      idSHA256: nextID,
      titleByteCount: 0,
      titleSHA256: testSHA256Hex(""),
      style: "body",
      isHeader: false,
      isList: false,
      isChecklist: false,
      isBlockQuote: false
    )
    structure.paragraphAnchors.insert(created, at: anchorIndex + 1)
    for index in structure.paragraphAnchors.indices {
      structure.paragraphAnchors[index].ordinal = index + 1
    }
    structure.paragraphCount = (structure.paragraphCount ?? structure.paragraphAnchors.count - 1) + 1
    structure.paragraphStyleRunCount += 1
    structure.plainTextByteCount = (structure.plainTextByteCount ?? 0) + 1
    structure.plainTextSHA256 =
      testSHA256Hex("\(structure.plainTextSHA256 ?? ""):\(draft.targetKind.rawValue):end")
    structure.richTextLength = (structure.richTextLength ?? 0) + 1
    incrementStyle("body", in: &structure)

    syncChecklistAnchorStates(noteID: draft.noteID, structure: &structure)
    bodyStructures[draft.noteID] = structure
    paragraphAnchors[draft.noteID, default: []].append(
      NotesParagraphAnchorResolution(anchor: created, paragraphID: "raw-\(nextID)", title: "")
    )
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)

    return NotesBodyListEndWriteResult(
      changed: true,
      note: note,
      structure: structure,
      createdParagraphStyle: "body",
      createdParagraphIDSHA256: nextID
    )
  }

  func setParagraphStyle(_ draft: NotesBodyParagraphStyleDraft) throws
    -> NotesBodyParagraphFormatWriteResult
  {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body paragraph style target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    guard let anchorIndex = paragraphFormatAnchorIndex(
      paragraphIDSHA256: draft.paragraphIDSHA256,
      ordinal: draft.ordinal,
      structure: structure
    ) else {
      throw CLIError(code: .notFound, message: "Paragraph selector did not match any body paragraph anchor.")
    }
    let anchor = structure.paragraphAnchors[anchorIndex]
    guard !anchor.isList, !anchor.isChecklist, !anchor.isBlockQuote else {
      throw CLIError(
        code: .validationError,
        message: "Notes paragraph formatting currently requires a non-list, non-checklist, non-block-quote paragraph."
      )
    }

    bodyParagraphStyleDrafts.append(draft)
    let changed = anchor.style != draft.style.rawValue || anchor.isHeader != draft.style.isHeader
    if changed {
      decrementStyle(anchor.style, in: &structure)
      incrementStyle(draft.style.rawValue, in: &structure)
      if anchor.isHeader && !draft.style.isHeader {
        structure.headingCount -= 1
      } else if !anchor.isHeader && draft.style.isHeader {
        structure.headingCount += 1
      }
      structure.paragraphAnchors[anchorIndex].style = draft.style.rawValue
      structure.paragraphAnchors[anchorIndex].isHeader = draft.style.isHeader
      structure.paragraphAnchors[anchorIndex].isList = false
      structure.paragraphAnchors[anchorIndex].isChecklist = false
      structure.paragraphAnchors[anchorIndex].isBlockQuote = false
      structure.paragraphAnchors[anchorIndex].listStyle = nil
      structure.paragraphAnchors[anchorIndex].indentationLevel = nil
      structure.paragraphAnchors[anchorIndex].canIndent = nil
      structure.paragraphAnchors[anchorIndex].checklistDone = nil
      var sections = bodyCollapsibleSections[draft.noteID] ?? []
      if let sectionIndex = sections.firstIndex(where: { $0.paragraphIDSHA256 == anchor.idSHA256 }) {
        if draft.style.createsCollapsibleSection {
          sections[sectionIndex].titleByteCount = anchor.titleByteCount
          sections[sectionIndex].titleSHA256 = anchor.titleSHA256
        } else {
          sections.remove(at: sectionIndex)
        }
      } else if draft.style.createsCollapsibleSection {
        sections.append(
          NotesBodyCollapsibleSectionRecord(
            ordinal: sections.count + 1,
            paragraphIDSHA256: anchor.idSHA256,
            titleByteCount: anchor.titleByteCount,
            titleSHA256: anchor.titleSHA256,
            collapsed: false
          ))
      }
      for index in sections.indices {
        sections[index].ordinal = index + 1
      }
      bodyCollapsibleSections[draft.noteID] = sections
      structure.collapsibleSectionCount = sections.count
      structure.collapsedSectionCount = sections.filter { $0.collapsed }.count
    }

    bodyStructures[draft.noteID] = structure
    reorderParagraphAnchorResolutions(noteID: draft.noteID, anchors: structure.paragraphAnchors)
    return NotesBodyParagraphFormatWriteResult(changed: changed, note: note, structure: structure)
  }

  func setParagraphAlignment(_ draft: NotesBodyParagraphAlignmentDraft) throws
    -> NotesBodyParagraphFormatWriteResult
