  private func incrementStyle(_ style: String, by amount: Int = 1, in structure: inout NotesBodyStructureRecord) {
    if let index = structure.styleCounts.firstIndex(where: { $0.style == style }) {
      structure.styleCounts[index].count += amount
    } else {
      structure.styleCounts.append(NotesBodyStyleCount(style: style, count: amount))
    }
  }

  private func decrementStyle(_ style: String, in structure: inout NotesBodyStructureRecord) {
    guard let index = structure.styleCounts.firstIndex(where: { $0.style == style }) else {
      return
    }
    structure.styleCounts[index].count -= 1
    if structure.styleCounts[index].count <= 0 {
      structure.styleCounts.remove(at: index)
    }
  }

  private func inlineEvidence(
    noteID: String,
    paragraphIDSHA256: String?,
    ordinal: Int?,
    text: String,
    occurrence: Int?,
    role: String,
    colorSHA256: String?,
    fontSHA256: String? = nil,
    structure: NotesBodyStructureRecord
  ) -> NotesBodyInlineMutationEvidence {
    let paragraphHash = paragraphIDSHA256
      ?? ordinal.flatMap { ordinal in structure.paragraphAnchors.first { $0.ordinal == ordinal }?.idSHA256 }
    return NotesBodyInlineMutationEvidence(
      paragraphIDSHA256: paragraphHash,
      textByteCount: text.utf8.count,
      textSHA256: testSHA256Hex(text),
      occurrence: occurrence ?? 1,
      role: role,
      colorSHA256: colorSHA256,
      fontSHA256: fontSHA256
    )
  }

  private func setInlineColor(
    _ draft: NotesBodyInlineColorDraft,
    role: String
  ) throws -> NotesBodyInlineColorWriteResult {
    guard let note = notes[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    if noteStates[draft.noteID]?.isPasswordProtected == true
      || noteStates[draft.noteID]?.isSharedReadOnly == true
    {
      throw CLIError(
        code: .permissionDenied,
        message: "Notes body inline color target must be editable.",
        details: ["id": draft.noteID]
      )
    }
    guard var structure = bodyStructures[draft.noteID] else {
      throw CLIError(code: .notFound, message: "Note body structure was not found.", details: ["id": draft.noteID])
    }
    let colorSHA256 = draft.color.map { testSHA256Hex($0) }
    let evidence = inlineEvidence(
      noteID: draft.noteID,
      paragraphIDSHA256: draft.paragraphIDSHA256,
      ordinal: draft.ordinal,
      text: draft.text,
      occurrence: draft.occurrence,
      role: role,
      colorSHA256: colorSHA256,
      structure: structure
    )
    let evidenceTextSHA256 = evidence.textSHA256
    let evidenceTextByteCount = evidence.textByteCount
    let evidenceParagraphIDSHA256 = evidence.paragraphIDSHA256
    let expectedColorSHA256 = colorSHA256
    let existing = structure.colorRuns.contains { run in
      guard run.role == role else { return false }
      guard run.textSHA256 == evidenceTextSHA256 else { return false }
      guard run.textByteCount == evidenceTextByteCount else { return false }
      guard run.paragraphIDSHA256 == evidenceParagraphIDSHA256 else { return false }
      guard let expectedColorSHA256 else {
        return true
      }
      return run.colorSHA256 == expectedColorSHA256
    }
    let targetPresent = colorSHA256 != nil
    let changed = existing != targetPresent
    if role == "foreground" {
      bodyInlineForegroundColorDrafts.append(draft)
    } else {
      bodyInlineHighlightColorDrafts.append(draft)
    }
    if changed {
      structure.colorRuns.removeAll {
        $0.role == role
          && $0.textSHA256 == evidence.textSHA256
          && $0.textByteCount == evidence.textByteCount
          && $0.paragraphIDSHA256 == evidence.paragraphIDSHA256
      }
      if let colorSHA256 {
        structure.colorRuns.append(
          NotesBodyInlineColorRunRecord(
            ordinal: structure.colorRuns.count + 1,
            paragraphIDSHA256: evidence.paragraphIDSHA256,
            role: role,
            colorSHA256: colorSHA256,
            textByteCount: evidence.textByteCount,
            textSHA256: evidence.textSHA256
          ))
        incrementInlineColor(role: role, colorSHA256: colorSHA256, in: &structure)
      } else {
        decrementInlineColor(role: role, in: &structure)
      }
      bodyStructures[draft.noteID] = structure
    }
    return NotesBodyInlineColorWriteResult(changed: changed, note: note, structure: structure, evidence: evidence)
  }

  private func incrementInlineFormat(_ format: String, in structure: inout NotesBodyStructureRecord) {
    structure.inlineFormatRunCount += 1
    switch format {
    case "bold": structure.boldRunCount += 1
    case "italic": structure.italicRunCount += 1
    case "underline": structure.underlineRunCount += 1
    case "strikethrough": structure.strikethroughRunCount += 1
    case "font": structure.fontRunCount += 1
    default: break
    }
    if let index = structure.inlineFormatCounts.firstIndex(where: { $0.format == format }) {
      structure.inlineFormatCounts[index].count += 1
    } else {
      structure.inlineFormatCounts.append(NotesBodyInlineFormatCount(format: format, count: 1))
    }
  }

  private func decrementInlineFormat(_ format: String, in structure: inout NotesBodyStructureRecord) {
    structure.inlineFormatRunCount = max(0, structure.inlineFormatRunCount - 1)
    switch format {
    case "bold": structure.boldRunCount = max(0, structure.boldRunCount - 1)
    case "italic": structure.italicRunCount = max(0, structure.italicRunCount - 1)
    case "underline": structure.underlineRunCount = max(0, structure.underlineRunCount - 1)
    case "strikethrough": structure.strikethroughRunCount = max(0, structure.strikethroughRunCount - 1)
    case "font": structure.fontRunCount = max(0, structure.fontRunCount - 1)
    default: break
    }
    guard let index = structure.inlineFormatCounts.firstIndex(where: { $0.format == format }) else {
      return
    }
    structure.inlineFormatCounts[index].count -= 1
    if structure.inlineFormatCounts[index].count <= 0 {
      structure.inlineFormatCounts.remove(at: index)
    }
  }

  private func incrementInlineColor(role: String, colorSHA256: String, in structure: inout NotesBodyStructureRecord) {
    if role == "foreground" {
      structure.foregroundColorRunCount += 1
      incrementInlineFormat("foreground_color", in: &structure)
    } else if role == "highlight" {
      structure.highlightRunCount += 1
      incrementInlineFormat("highlight", in: &structure)
    }
    if let index = structure.colorHashCounts.firstIndex(where: { $0.role == role && $0.colorSHA256 == colorSHA256 }) {
      structure.colorHashCounts[index].count += 1
    } else {
      structure.colorHashCounts.append(NotesBodyColorHashCount(role: role, colorSHA256: colorSHA256, count: 1))
    }
  }

  private func decrementInlineColor(role: String, in structure: inout NotesBodyStructureRecord) {
    if role == "foreground" {
      structure.foregroundColorRunCount = max(0, structure.foregroundColorRunCount - 1)
      decrementInlineFormat("foreground_color", in: &structure)
    } else if role == "highlight" {
      structure.highlightRunCount = max(0, structure.highlightRunCount - 1)
      decrementInlineFormat("highlight", in: &structure)
    }
  }

  private func syncChecklistAnchorStates(noteID: String, structure: inout NotesBodyStructureRecord) {
    let states = bodyChecklistStates[noteID] ?? [:]
    let ordinalMap = bodyChecklistParagraphOrdinals[noteID] ?? [:]
    for index in structure.paragraphAnchors.indices where structure.paragraphAnchors[index].isChecklist {
      let anchorID = structure.paragraphAnchors[index].idSHA256
      let checklistOrdinal = ordinalMap[anchorID]
      structure.paragraphAnchors[index].checklistDone = checklistOrdinal.flatMap { states[$0] }
        ?? structure.paragraphAnchors[index].checklistDone
        ?? false
    }
  }

  private func reorderParagraphAnchorResolutions(noteID: String, anchors: [NotesBodyParagraphAnchorRecord]) {
    guard let current = paragraphAnchors[noteID] else {
      return
    }
    let byID = Dictionary(uniqueKeysWithValues: current.map { ($0.anchor.idSHA256, $0) })
    paragraphAnchors[noteID] = anchors.compactMap { anchor in
      guard var resolution = byID[anchor.idSHA256] else {
        return nil
      }
      resolution.anchor = anchor
      return resolution
    }
  }

  func resolveParagraphAnchor(noteID id: String, paragraphIDSHA256: String) throws -> NotesParagraphAnchorResolution {
    let matches = (paragraphAnchors[id] ?? [])
      .filter { $0.anchor.idSHA256 == paragraphIDSHA256 }
    guard let match = matches.first else {
      throw CLIError(
        code: .notFound,
        message: "Paragraph anchor hash did not match any paragraph on the target note.",
        details: ["id": id]
      )
    }
    guard matches.count == 1 else {
      throw CLIError(
        code: .ambiguousIdentity,
        message: "Paragraph anchor hash matched multiple paragraphs on the target note.",
        details: ["id": id]
      )
    }
    return match
  }

  func readNoteState(noteID id: String) throws -> NotesNoteStateRecord {
    guard let state = noteStates[id] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    return state
  }

  private func noteExportPrivacyState(
    noteID id: String,
    formatName: String
  ) throws -> (isPasswordProtected: Bool, isPasswordProtectedAndLocked: Bool?, title: String?) {
    let state = try readNoteState(noteID: id)
    guard state.isPasswordProtected == false || state.isPasswordProtectedAndLocked == false else {
      throw CLIError(
        code: .unsupportedOperation,
        message:
          "Password-protected Notes \(formatName) export requires the selected note to already be unlocked in the current Notes session.",
        details: [
          "id_sha256": testSHA256Hex(id),
          "required_state": "non_password_protected_or_session_unlocked_password_protected_note",
          "future_gate": "secret_safe_authentication_session",
        ]
      )
    }
    return (
      state.isPasswordProtected,
      state.isPasswordProtectedAndLocked,
      state.isPasswordProtected ? nil : notes[id]?.title
    )
  }

  func exportNotePDF(noteID id: String) throws -> NotesNotePDFExportSource {
    guard let note = notes[id] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let exportState = try noteExportPrivacyState(noteID: id, formatName: "PDF")
    pdfExportedIDs.append(id)
    return NotesNotePDFExportSource(
      noteID: note.id,
      title: exportState.title,
      data: Data("%PDF-1.7\ntest note pdf\n%%EOF".utf8),
      isPasswordProtected: exportState.isPasswordProtected,
      isPasswordProtectedAndLocked: exportState.isPasswordProtectedAndLocked
    )
  }

  func exportNoteMarkdown(noteID id: String, includeAttachments: Bool) throws -> NotesNoteMarkdownExportSource {
    guard let note = notes[id] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let exportState = try noteExportPrivacyState(noteID: id, formatName: "Markdown")
    let attachmentCount = (attachments[id] ?? []).filter {
      ($0.isDeletedOrInTrash ?? false) == false
    }.count
    if attachmentCount > 0 && !includeAttachments {
      throw CLIError(
        code: .unsupportedOperation,
        message:
          "Notes Markdown export with attachment resources requires `--include-attachments` and a package output path.",
        details: ["id_sha256": "test", "attachment_count": "\(attachmentCount)"]
      )
    }
    guard id == "note-2" || id == "note-protected-unlocked" else {
      throw CLIError(
        code: .unsupportedOperation,
        message:
          "Notes Markdown export with attachment resources is gated; use `notes export rtfd` for this note.",
        details: ["id_sha256": "test", "attachment_count": "1"]
      )
    }
    markdownExportedIDs.append(id)
    let markdownData = id == "note-protected-unlocked"
      ? Data("# Protected\n\nUnlocked protected export body.\n".utf8)
      : Data("# Plan\n\n- Launch\n".utf8)
    return NotesNoteMarkdownExportSource(
      noteID: note.id,
      title: exportState.title,
      data: markdownData,
      includesAttachments: includeAttachments,
      attachmentCount: attachmentCount,
      markdownRelativePath: includeAttachments && exportState.title != nil ? "Plan.md" : "Note.md",
      resourceFiles: includeAttachments && attachmentCount > 0
        ? [
          NotesNoteMarkdownExportFile(
            relativePath: "Resources/Resource.png",
            data: Data("test markdown attachment".utf8)
          )
        ]
        : [],
      isPasswordProtected: exportState.isPasswordProtected,
      isPasswordProtectedAndLocked: exportState.isPasswordProtectedAndLocked
    )
  }

  func addFixtureAttachment(toNoteID id: String) {
    attachments[id, default: []].append(
      NotesAttachmentRecord(
        id: "fixture-attachment-\((attachments[id] ?? []).count + 1)",
        title: "Resource.png",
        typeUTI: "public.png",
        contentIdentifier: "fixture-resource",
        attachmentType: 9,
        fileSizeBytes: 128,
        mediaFilename: "Resource.png",
        isInline: true,
        isDeletedOrInTrash: false
      ))
  }

  func exportNoteHTML(
    noteID id: String,
    includeAttachments: Bool,
    includeAttachmentResources: Bool
  ) throws -> NotesNoteHTMLExportSource {
    guard let note = notes[id] else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    let exportState = try noteExportPrivacyState(noteID: id, formatName: "HTML")
    let attachmentCount = (attachments[id] ?? []).filter {
      ($0.isDeletedOrInTrash ?? false) == false
    }.count
    guard includeAttachments || attachmentCount == 0 else {
      throw CLIError(
        code: .unsupportedOperation,
        message: "Notes HTML export would omit attachment resources; use `notes export rtfd` for this note.",
        details: ["id_sha256": "test", "attachment_count": "\(attachmentCount)"]
      )
    }
    htmlExportedIDs.append(id)
    htmlExportIncludeAttachmentFlags.append(includeAttachments)
    htmlExportIncludeAttachmentResourceFlags.append(includeAttachmentResources)
    let data: Data
    if id == "note-protected-unlocked" {
      data = Data("<html><body><p>Unlocked protected export body.</p></body></html>".utf8)
    } else if includeAttachments {
      data = Data("<html><body><p>Launch plan</p><a href=\"cid:attachment-content-1\">Launch.pdf</a></body></html>".utf8)
    } else {
      data = Data("<html><body><p>Launch plan</p></body></html>".utf8)
    }
    return NotesNoteHTMLExportSource(
      noteID: note.id,
      title: exportState.title,
      data: data,
      includesAttachments: includeAttachments,
      attachmentCount: attachmentCount,
      htmlRelativePath: includeAttachmentResources && exportState.title != nil ? "Plan.html" : "Note.html",
      resourceFiles: includeAttachmentResources && attachmentCount > 0
        ? [
          NotesNoteHTMLExportFile(
            relativePath: "Resources/Resource.png",
            data: Data("test html attachment".utf8)
          )
        ]
        : [],
      isPasswordProtected: exportState.isPasswordProtected,
      isPasswordProtectedAndLocked: exportState.isPasswordProtectedAndLocked
    )
  }

  func exportNoteRTF(noteID id: String) throws -> NotesNoteRTFExportSource {
    guard let note = notes[id] else {
