  func updateNote(id: String, patch: NotesUpdatePatch) throws -> NotesNoteDetail {
    updatedPatches[id] = patch
    guard var note = try readNote(id: id) else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    if let title = patch.title {
      note.title = title
    }
    if let body = patch.body {
      note.body = body
    }
    if let appendBody = patch.appendBody {
      note.body = [note.body ?? "", appendBody].filter { !$0.isEmpty }.joined(separator: "\n")
    }
    notes[id] = note
    return note
  }

  func moveNote(_ draft: NotesMoveDraft) throws -> NotesNoteDetail {
    movedDrafts.append(draft)
    guard var note = try readNote(id: draft.noteID) else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    note.folderName = draft.folderName
    note.accountName = draft.accountName
    notes[draft.noteID] = note
    return note
  }

  func copyNote(_ draft: NotesCopyDraft) throws -> NotesNoteDetail {
    copiedDrafts.append(draft)
    guard let source = try readNote(id: draft.noteID) else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": draft.noteID])
    }
    let id = copiedDrafts.count == 1 ? "note-copy" : "note-copy-\(copiedDrafts.count)"
    let note = NotesNoteDetail(
      id: id,
      title: source.title,
      folderName: draft.folderName,
      accountName: draft.accountName,
      body: source.body,
      createdAt: source.createdAt,
      updatedAt: source.updatedAt,
      tags: source.tags
    )
    notes[id] = note
    return note
  }

  func readRestorableNote(id: String) throws -> NotesNoteDetail? {
    restorableNotes[id]
  }

  func listRestorableNotes(limit: Int) throws -> [NotesNoteDetail] {
    restorableListQueries.append(limit)
    return restorableNotes.values
      .sorted { $0.id < $1.id }
      .prefix(limit)
      .map { $0 }
  }

  func restoreNote(_ draft: NotesRestoreDraft) throws -> NotesNoteDetail {
    restoredDrafts.append(draft)
    guard var note = restorableNotes.removeValue(forKey: draft.noteID) else {
      throw CLIError(code: .notFound, message: "Restorable note was not found.", details: ["id": draft.noteID])
    }
    note.folderName = draft.folderName
    note.accountName = draft.accountName
    notes[draft.noteID] = note
    return note
  }

  func deleteNote(id: String) throws -> Bool {
    guard notes.removeValue(forKey: id) != nil else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    deletedIDs.append(id)
    return true
  }

  func purgeNote(id: String) throws -> Bool {
    guard restorableNotes.removeValue(forKey: id) != nil else {
      throw CLIError(code: .notFound, message: "Restorable note was not found.", details: ["id": id])
    }
    purgedIDs.append(id)
    return true
  }

  func setNotePinned(id: String, pinned: Bool) throws -> NotesNoteDetail {
    guard let note = try readNote(id: id) else {
      throw CLIError(code: .notFound, message: "Note was not found.", details: ["id": id])
    }
    guard var state = noteStates[id] else {
      throw CLIError(code: .notFound, message: "Note state was not found.", details: ["id": id])
    }
    state.isPinned = pinned
    noteStates[id] = state
    pinnedMutations.append("\(id):\(pinned)")
    return note
  }

  private func linkDestination(_ link: NotesLinkRecord) -> NotesLinkDestinationRecord {
    if link.kind == "paragraph" || link.kind == "internal_paragraph" || link.isParagraphLink
      || link.isInternalParagraphLink
    {
      let target = paragraphLinkTargets[link.id]
      return NotesLinkDestinationRecord(
        kind: link.isInternalParagraphLink || link.kind == "internal_paragraph" ? "internal_paragraph" : "paragraph",
        resolved: target != nil,
        urlScheme: link.urlScheme,
        urlSHA256: link.urlSHA256,
        targetNoteID: target?.noteID,
        targetNoteIDSHA256: target.map { testSHA256Hex($0.noteID) },
        targetParagraphIDSHA256: target?.paragraphIDSHA256,
        tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256,
        rawInternalTokenHidden: true,
        warnings: target == nil ? ["target_note_not_visible"] : []
      )
    }
    if link.kind == "note" || link.urlScheme == "notes" {
      let targetNoteID = noteLinkTargets[link.id]
      return NotesLinkDestinationRecord(
        kind: "note",
        resolved: targetNoteID != nil,
        urlScheme: link.urlScheme,
        urlSHA256: link.urlSHA256,
        targetNoteID: targetNoteID,
        targetNoteIDSHA256: targetNoteID.map(testSHA256Hex),
        tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256,
        rawInternalTokenHidden: true,
        warnings: targetNoteID == nil ? ["target_note_not_visible"] : []
      )
    }
    if link.urlScheme == "file" {
      return NotesLinkDestinationRecord(
        kind: "file",
        resolved: link.urlSHA256 != nil,
        urlScheme: link.urlScheme,
        urlSHA256: link.urlSHA256,
        tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256,
        rawURLHidden: true
      )
    }
    if link.kind == "app" {
      return NotesLinkDestinationRecord(
        kind: "app",
        resolved: link.urlSHA256 != nil,
        urlScheme: link.urlScheme,
        urlSHA256: link.urlSHA256,
        tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256,
        rawURLHidden: true
      )
    }
    if let urlString = link.urlString {
      return NotesLinkDestinationRecord(
        kind: "public_url",
        resolved: true,
        urlScheme: link.urlScheme,
        publicURLString: urlString,
        urlSHA256: link.urlSHA256,
        tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256
      )
    }
    return NotesLinkDestinationRecord(
      kind: "unresolved",
      resolved: false,
      urlScheme: link.urlScheme,
      urlSHA256: link.urlSHA256,
      tokenContentIdentifierSHA256: link.tokenContentIdentifierSHA256,
      warnings: ["unsupported_link_kind"]
    )
  }

  private func linkRecordMatches(_ link: NotesLinkRecord, selector: String) -> Bool {
    [
      link.id,
      link.displayText,
      link.altText,
      link.urlString,
      link.urlSHA256,
      link.tokenContentIdentifierSHA256,
    ].compactMap { $0 }.contains(selector)
  }

  private func noteSummaries(includeConversionFixture: Bool = false) -> [NotesNoteSummary] {
    notes.values
      .filter { includeConversionFixture || $0.id != "note-convertible" }
      .sorted { $0.id < $1.id }
      .map(noteSummary)
  }

  private func noteSummary(_ note: NotesNoteDetail) -> NotesNoteSummary {
    NotesNoteSummary(
      id: note.id,
      title: note.title,
      folderName: note.folderName,
      accountName: note.accountName,
      createdAt: note.createdAt,
      updatedAt: note.updatedAt
    )
  }

  private func testMarkdownImportedPlainText(_ body: String) -> String {
    body.components(separatedBy: .newlines)
      .map { line in
        var text = line.trimmingCharacters(in: .whitespacesAndNewlines)
        while text.hasPrefix("#") {
          text.removeFirst()
        }
        text = text.trimmingCharacters(in: .whitespacesAndNewlines)
        for marker in ["- ", "* ", "+ ", "> "] where text.hasPrefix(marker) {
          text.removeFirst(marker.count)
          return text.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if let markerEnd = text.firstIndex(where: { !$0.isNumber }) {
          let marker = text[markerEnd]
          if marker == "." || marker == ")" {
            let afterMarker = text.index(after: markerEnd)
            if afterMarker < text.endIndex, text[afterMarker].isWhitespace {
              return text[afterMarker...].trimmingCharacters(in: .whitespacesAndNewlines)
            }
          }
        }
        return text
      }
      .filter { !$0.isEmpty && !$0.hasPrefix("```") && !$0.hasPrefix("~~~") }
      .joined(separator: "\n")
  }

  private func testMarkdownBodyStructure(
    noteID: String,
    plainText: String,
    summary: NotesMarkdownSemanticSummary
  ) -> NotesBodyStructureRecord {
    let paragraphCount = max(1, plainText.components(separatedBy: .newlines).filter { !$0.isEmpty }.count)
    var styleCounts = [NotesBodyStyleCount(style: "body", count: max(1, paragraphCount - summary.headingCount - summary.listItemCount))]
    if summary.headingCount > 0 {
      styleCounts.append(NotesBodyStyleCount(style: "heading", count: summary.headingCount))
    }
    if summary.listItemCount > 0 {
      styleCounts.append(NotesBodyStyleCount(style: "list", count: summary.listItemCount))
    }
    if summary.blockQuoteLineCount > 0 {
      styleCounts.append(NotesBodyStyleCount(style: "block_quote", count: summary.blockQuoteLineCount))
    }
    return NotesBodyStructureRecord(
      noteID: noteID,
      isPasswordProtected: false,
      plainTextByteCount: Data(plainText.utf8).count,
      plainTextSHA256: testSHA256Hex(plainText),
      richTextLength: (plainText as NSString).length,
      paragraphCount: paragraphCount,
      paragraphStyleRunCount: styleCounts.reduce(0) { $0 + $1.count },
      headingCount: summary.headingCount,
      listItemCount: summary.listItemCount,
      blockQuoteCount: summary.blockQuoteLineCount,
      linkCount: summary.linkReferenceCount + summary.imageReferenceCount,
      inlineFormatRunCount: summary.inlineCodeSpanCount + summary.emphasizedSpanCount,
      boldRunCount: summary.emphasizedSpanCount,
      styleCounts: styleCounts,
      inlineFormatCounts: summary.emphasizedSpanCount > 0
        ? [NotesBodyInlineFormatCount(format: "bold", count: summary.emphasizedSpanCount)] : [],
      paragraphAnchors: [
        NotesBodyParagraphAnchorRecord(
          ordinal: 1,
          idSHA256: "markdown-import-paragraph-anchor-hash",
          titleByteCount: Data(plainText.utf8).count,
          titleSHA256: testSHA256Hex(plainText),
          style: summary.headingCount > 0 ? "heading" : "body",
          isHeader: summary.headingCount > 0
        )
      ]
    )
  }

  private func replaceSmartFolderCriteriaTag(
    oldStandardized: String,
    newStandardized: String,
    newDisplayText: String
  ) {
    mutateSmartFolderTagCriteria { tagSelection in
      tagSelection.tagIdentifiers = replaceTagIdentifiers(
        tagSelection.tagIdentifiers,
        oldStandardized: oldStandardized,
        newStandardized: newStandardized
      )
      tagSelection.includedTagIdentifiers = replaceTagIdentifiers(
        tagSelection.includedTagIdentifiers,
        oldStandardized: oldStandardized,
        newStandardized: newStandardized
      )
      tagSelection.excludedTagIdentifiers = replaceTagIdentifiers(
        tagSelection.excludedTagIdentifiers,
        oldStandardized: oldStandardized,
        newStandardized: newStandardized
      )
      tagSelection.displayTexts = replaceTagDisplayTexts(
        tagSelection.displayTexts,
        oldStandardized: oldStandardized,
        newDisplayText: newDisplayText
      )
      tagSelection.includedDisplayTexts = replaceTagDisplayTexts(
        tagSelection.includedDisplayTexts,
        oldStandardized: oldStandardized,
        newDisplayText: newDisplayText
      )
      tagSelection.excludedDisplayTexts = replaceTagDisplayTexts(
        tagSelection.excludedDisplayTexts,
        oldStandardized: oldStandardized,
        newDisplayText: newDisplayText
      )
    }
  }

  private func removeSmartFolderCriteriaTag(standardized: String) {
    mutateSmartFolderTagCriteria { tagSelection in
      tagSelection.tagIdentifiers = removeTagIdentifiers(tagSelection.tagIdentifiers, standardized: standardized)
      tagSelection.includedTagIdentifiers = removeTagIdentifiers(
        tagSelection.includedTagIdentifiers,
        standardized: standardized
      )
      tagSelection.excludedTagIdentifiers = removeTagIdentifiers(
        tagSelection.excludedTagIdentifiers,
        standardized: standardized
      )
      tagSelection.displayTexts = removeTagDisplayTexts(tagSelection.displayTexts, standardized: standardized)
      tagSelection.includedDisplayTexts = removeTagDisplayTexts(
        tagSelection.includedDisplayTexts,
        standardized: standardized
      )
      tagSelection.excludedDisplayTexts = removeTagDisplayTexts(
        tagSelection.excludedDisplayTexts,
        standardized: standardized
      )
    }
  }

  private func mutateSmartFolderTagCriteria(
    _ mutate: (inout NotesSmartFolderTagCriteria) -> Void
  ) {
    for index in smartFolders.indices {
      guard var criteria = smartFolders[index].criteria,
        var tagSelection = criteria.tagSelection
      else {
        continue
      }
      let original = tagSelection
      mutate(&tagSelection)
      guard tagSelection != original else {
        continue
      }
      normalizeSmartFolderTagCriteria(&tagSelection)
      criteria.tagSelection = tagSelection
      criteria.filters = criteria.filters.map { filter in
        guard filter.kind == "tags" else {
          return filter
        }
        var updated = filter
        updated.count = tagSelection.selectedTagCount
        updated.includedCount = tagSelection.includedTagCount
        updated.excludedCount = tagSelection.excludedTagCount
        return updated
      }
      smartFolders[index].criteria = criteria
    }
  }

  private func normalizeSmartFolderTagCriteria(
    _ tagSelection: inout NotesSmartFolderTagCriteria
  ) {
    tagSelection.tagIdentifiers = normalizedOptionalArray(tagSelection.tagIdentifiers)
    tagSelection.displayTexts = normalizedOptionalArray(tagSelection.displayTexts)
    tagSelection.includedTagIdentifiers = normalizedOptionalArray(tagSelection.includedTagIdentifiers)
    tagSelection.includedDisplayTexts = normalizedOptionalArray(tagSelection.includedDisplayTexts)
    tagSelection.excludedTagIdentifiers = normalizedOptionalArray(tagSelection.excludedTagIdentifiers)
    tagSelection.excludedDisplayTexts = normalizedOptionalArray(tagSelection.excludedDisplayTexts)
    tagSelection.selectedTagCount = tagSelection.tagIdentifiers?.count ?? tagSelection.displayTexts?.count
    tagSelection.includedTagCount =
      tagSelection.includedTagIdentifiers?.count
      ?? tagSelection.includedDisplayTexts?.count
      ?? tagSelection.selectedTagCount
    tagSelection.excludedTagCount =
      tagSelection.excludedTagIdentifiers?.count
      ?? tagSelection.excludedDisplayTexts?.count
      ?? 0
    tagSelection.tagIdentifiersSHA256 = smartFolderCriteriaHash(tagSelection.tagIdentifiers)
    tagSelection.displayTextsSHA256 = smartFolderCriteriaHash(tagSelection.displayTexts)
  }

  private func replaceTagIdentifiers(
    _ values: [String]?,
    oldStandardized: String,
    newStandardized: String
  ) -> [String]? {
    values?.map { tagIdentifierMatches($0, standardized: oldStandardized) ? "tag-\(newStandardized)" : $0 }
  }

  private func removeTagIdentifiers(_ values: [String]?, standardized: String) -> [String]? {
    values?.filter { !tagIdentifierMatches($0, standardized: standardized) }
  }

  private func replaceTagDisplayTexts(
    _ values: [String]?,
    oldStandardized: String,
    newDisplayText: String
  ) -> [String]? {
    values?.map { testStandardizedTagContent($0) == oldStandardized ? newDisplayText : $0 }
  }

  private func removeTagDisplayTexts(_ values: [String]?, standardized: String) -> [String]? {
    values?.filter { testStandardizedTagContent($0) != standardized }
  }

  private func normalizedOptionalArray(_ values: [String]?) -> [String]? {
    guard let values, !values.isEmpty else {
      return nil
    }
    return values
  }

  private func smartFolderCriteriaHash(_ values: [String]?) -> String? {
    guard let values, !values.isEmpty else {
      return nil
    }
    return testSHA256Hex(values.sorted().joined(separator: "\0"))
  }

  private func tagIdentifierMatches(_ value: String, standardized: String) -> Bool {
    let lowered = value.localizedLowercase
    return lowered == standardized || lowered == "tag-\(standardized)"
  }

  private func tagRecord(tag: String, accountName: String) -> NotesTagRecord {
    let standardized = testStandardizedTagContent(tag)
    let display =
      standardized.isEmpty
      ? tag
      : standardized.prefix(1).uppercased() + String(standardized.dropFirst())
    return NotesTagRecord(
      id: "tag-\(standardized)",
      displayText: display,
      standardizedContent: standardized,
      accountName: accountName,
      visibleUseCount: notes.values.filter { note in
        note.tags.contains { testTagMatches($0, standardized) }
      }.count
    )
  }

  private func testTagMatches(_ record: NotesTagRecord, _ tag: String) -> Bool {
    let standardized = testStandardizedTagContent(tag)
    return record.id.localizedCaseInsensitiveCompare(tag) == .orderedSame
      || record.displayText.localizedCaseInsensitiveCompare(tag) == .orderedSame
      || record.standardizedContent?.localizedCaseInsensitiveCompare(standardized) == .orderedSame
  }

  private func testStandardizedTagContent(_ tag: String) -> String {
    let withoutPrefix = tag.hasPrefix("#") ? String(tag.dropFirst()) : tag
    return withoutPrefix.trimmingCharacters(in: .whitespacesAndNewlines).localizedLowercase
  }

  private func testFolderSortDescription(_ draft: NotesFolderSortDraft) -> String {
    switch draft.by {
    case "default":
      return "Default"
    case "date-edited":
      return draft.direction == "oldest-first" ? "Date Edited Oldest First" : "Date Edited Newest First"
    case "date-created":
      return draft.direction == "oldest-first" ? "Date Created Oldest First" : "Date Created Newest First"
    case "title":
      return draft.direction == "descending" ? "Title Descending" : "Title Ascending"
    default:
      return draft.by
    }
  }
}

