private final class TestMailBackend: MailReading, MailDrafting, MailSending, MailMessageMutating,
  @unchecked Sendable
{
  private(set) var readStatusChanged = false
  private(set) var readMessageCount = 0
  private(set) var bodyPreviewCount = 0
  private(set) var listMessageQueries: [MailMessageQuery] = []
  var createdDrafts: [MailDraftRequest] = []
  var sentMessages: [MailDraftRequest] = []
  var movedMessages: [(MailMessageDetail, String)] = []
  var archivedMessages: [(MailMessageDetail, String)] = []
  var deletedMessages: [MailMessageDetail] = []

  func listAccounts() throws -> [MailAccountRecord] {
    [MailAccountRecord(name: "Work")]
  }

  func listMailboxes(account: String?, limit: Int) throws -> [MailboxRecord] {
    [
      MailboxRecord(accountName: "Work", name: "Inbox"),
      MailboxRecord(accountName: "Work", name: "Processed"),
      MailboxRecord(accountName: "Work", name: "Archive"),
    ].prefix(limit).map { $0 }
  }

  func readMailbox(account: String?, mailbox: String) throws -> MailboxRecord? {
    try listMailboxes(account: account, limit: 50).first {
      $0.name == mailbox && (account == nil || $0.accountName == account)
    }
  }

  func listMessages(_ query: MailMessageQuery) throws -> [MailMessageSummary] {
    listMessageQueries.append(query)
    return [
      (
        summary: MailMessageSummary(
          id: "message-1",
          accountName: "Work",
          mailboxName: "Inbox",
          subject: "Launch",
          sender: "ada@example.com",
          isRead: false
        ),
        body: "Private body only returned for explicit body preview."
      )
    ]
    .filter { query.unreadOnly ? !$0.summary.isRead : true }
    .filter { item in
      guard let searchText = query.searchText, let scope = query.searchScope else {
        return true
      }
      switch scope {
      case "subject":
        return item.summary.subject.localizedCaseInsensitiveContains(searchText)
      case "sender":
        return item.summary.sender.localizedCaseInsensitiveContains(searchText)
      case "body":
        return item.body.localizedCaseInsensitiveContains(searchText)
      default:
        return false
      }
    }
    .prefix(query.limit)
    .map(\.summary)
  }

  func readMessage(id: String, account: String?, mailbox: String) throws -> MailMessageDetail? {
    readMessageCount += 1
    guard id == "message-1", mailbox == "Inbox" else {
      return nil
    }

    return MailMessageDetail(
      id: "message-1",
      accountName: account ?? "Work",
      mailboxName: mailbox,
      subject: "Launch",
      sender: "ada@example.com",
      recipients: ["team@example.com"],
      isRead: false,
      bodyIncluded: false
    )
  }

  func previewMessageBody(
    id: String,
    account: String?,
    mailbox: String,
    maxBytes: Int
  ) throws -> MailBodyPreviewResponse? {
    bodyPreviewCount += 1
    guard var message = try readMessage(id: id, account: account, mailbox: mailbox) else {
      return nil
    }
    let body = "Private body only returned for explicit body preview."
    let truncated = body.utf8.count > maxBytes
    let preview = String(body.prefix(maxBytes))
    message.bodyIncluded = true
    return MailBodyPreviewResponse(message: message, body: preview, truncated: truncated)
  }

  func createDraft(_ draft: MailDraftRequest) throws -> MailDraftRecord {
    createdDrafts.append(draft)
    return MailDraftRecord(
      id: "draft-1",
      to: draft.to,
      cc: draft.cc,
      bcc: draft.bcc,
      subject: draft.subject,
      bodyIncluded: false
    )
  }

  func sendMail(_ draft: MailDraftRequest) throws -> MailSendRecord {
    sentMessages.append(draft)
    return MailSendRecord(
      to: draft.to,
      cc: draft.cc,
      bcc: draft.bcc,
      subject: draft.subject,
      bodyIncluded: false
    )
  }

  func moveMessage(
    _ message: MailMessageDetail,
    destinationMailbox: String
  ) throws -> MailMessageMutationRecord {
    movedMessages.append((message, destinationMailbox))
    return mailMutationRecord(message, destinationMailbox: destinationMailbox)
  }

  func archiveMessage(
    _ message: MailMessageDetail,
    archiveMailbox: String
  ) throws -> MailMessageMutationRecord {
    archivedMessages.append((message, archiveMailbox))
    return mailMutationRecord(message, destinationMailbox: archiveMailbox)
  }

  func deleteMessage(_ message: MailMessageDetail) throws -> MailMessageMutationRecord {
    deletedMessages.append(message)
    return mailMutationRecord(message, destinationMailbox: nil)
  }
}

private func mailMutationRecord(
  _ message: MailMessageDetail,
  destinationMailbox: String?
) -> MailMessageMutationRecord {
  MailMessageMutationRecord(
    id: message.id,
    accountName: message.accountName,
    sourceMailboxName: message.mailboxName,
    destinationMailboxName: destinationMailbox,
    subject: message.subject,
    sender: message.sender
  )
}

private func jsonObject(_ json: String) throws -> [String: Any] {
  let data = Data(json.utf8)
  guard let object = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
    throw NotesMailCommandTestError.notObject
  }
  return object
}

private func jsonString(_ object: [String: Any]) throws -> String {
  let data = try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys])
  guard let string = String(data: data, encoding: .utf8) else {
    throw NotesMailCommandTestError.notObject
  }
  return string
}

private func temporaryMarkdownFile(_ body: String) throws -> String {
  let url = FileManager.default.temporaryDirectory
    .appendingPathComponent("apple-cli-\(UUID().uuidString)")
    .appendingPathExtension("md")
  try body.write(to: url, atomically: true, encoding: .utf8)
  return url.standardizedFileURL.path
}

private func temporaryMarkdownPackage(
  markdown: String,
  resourceName: String,
  resourceData: Data
) throws -> URL {
  let packageURL = FileManager.default.temporaryDirectory
    .appendingPathComponent("apple-cli-\(UUID().uuidString)")
    .appendingPathExtension("mdpkg")
    .standardizedFileURL
  let resourcesURL = packageURL.appendingPathComponent("Resources", isDirectory: true)
  try FileManager.default.createDirectory(at: resourcesURL, withIntermediateDirectories: true)
  try markdown.write(
    to: packageURL.appendingPathComponent("Package.md"),
    atomically: true,
    encoding: .utf8
  )
  try resourceData.write(to: resourcesURL.appendingPathComponent(resourceName))
  return packageURL
}

