private func testSHA256Hex(_ value: String) -> String {
  SHA256.hash(data: Data(value.utf8)).map { String(format: "%02x", $0) }.joined()
}

private func bodyTableCellKey(tableOrdinal: Int, row: Int, column: Int) -> String {
  "\(tableOrdinal):\(row):\(column)"
}

private func bodyTableCellFormatDigest(text: String, formats: Set<NotesBodyInlineFormat>) -> String {
  let sortedFormats = formats.map(\.rawValue).sorted().joined(separator: ",")
  return testSHA256Hex("\(text.utf8.count):\(testSHA256Hex(text)):\(sortedFormats)")
}

private func parsedBodyTableCells(tableOrdinal: Int, text: String) -> [String: String] {
  var cells: [String: String] = [:]
  for (rowIndex, row) in text.components(separatedBy: CharacterSet.newlines).enumerated() {
    for (columnIndex, value) in row.components(separatedBy: "\t").enumerated() {
      cells[bodyTableCellKey(tableOrdinal: tableOrdinal, row: rowIndex + 1, column: columnIndex + 1)] = value
    }
  }
  return cells
}

private func replacingFirstOccurrence(in body: String, target: String, replacement: String) -> String {
  guard let range = body.range(of: target) else {
    return body.isEmpty ? replacement : [body, replacement].joined(separator: "\n")
  }
  var body = body
  body.replaceSubrange(range, with: replacement)
  return body
}

private func testFontSHA256(family: String, size: Double) -> String {
  testSHA256Hex("\(family)|\(String(format: "%.3f", size))")
}

private enum NotesMailCommandTestError: Error {
  case notObject
}
